INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C1','soc',4,2,'u3',1,'자연환경과 인문환경 — 우리를 둘러싸고 있는 모든 것 = 환경 · 자연 그대로 생겨난 것 = 자연환경(산·들·하천·바다·갯벌·섬, 날씨에 영향을 주는 비·눈·바람·기온) · 사람들이 만든 것 = 인문환경(논과 밭·항구·건물·목장·도로·다리·공원·공장·시장·스키장) · 논과 밭은 사람들이 농사를 지으려고 만든 것이라 인문환경 · 갈래는 색이나 크기가 아니라 「자연 그대로 생겨났나, 사람들이 만들었나」로 정함 — 같은 갈래면 어느 두 장이든 짝 · 예전 사진의 넓은 논 → 최근 사진의 높은 건물·아파트 단지·넓어진 도로',ARRAY['[4사10-01] 여러 지역의 자연환경과 인문환경의 특징을 살펴보고, 환경의 이용과 개발에 따른 영향을 탐구한다(차시 머리 주석 기준)']::text[],1) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C2','soc',4,2,'u3',2,'산이 많은 지역의 특징과 변화 — 울창한 숲·산봉우리·계곡 · 소나 양을 기르는 목장, 바람으로 전기를 만드는 풍력 발전기 · 산비탈(산에 가파르게 기울어진 곳)에 밭을 만들어 농사, 약초와 버섯 재배 · 물을 저장하거나 전기를 만드는 댐 · 여가 활동을 즐기도록 만든 스키장·캠핑장·삼림욕장 · 스키장 주변 식당·숙박 시설 → 관광객에게 음식을 팔거나 숙소를 빌려줌 · 산골 고장 일기: 옛날 산비탈 밭·옥수수와 감자 농사 → 스키장이 생겨 관광객이 크게 늘고 하는 일이 달라짐',ARRAY['[4사10-01] 여러 지역의 자연환경과 인문환경의 특징을 살펴보고, 환경의 이용과 개발에 따른 영향을 탐구한다(차시 머리 주석 기준)']::text[],2) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C3','soc',4,2,'u3',3,'들이 펼쳐진 지역의 특징과 변화 — 땅이 넓고 평평함 · 하천이나 저수지 가까이에 만든 논과 밭 · 논에서 벼농사, 밭이나 비닐하우스에서 채소와 과일 재배 · 축사(소·돼지), 공장(물건), 경기장(경기와 관중), 백화점(사고팖), 기차역(기차 타기) · 많은 사람이 모여 살면서 회사와 공장·아파트·도로가 생겨남, 백화점·대형 할인점 같은 상점과 박물관·미술관 같은 문화 시설 · 옛 지도 → 요즘 지도: 학교가 많아지고 도로가 복잡해짐 → 사는 사람이 많아졌다고 볼 수 있음 · 요즘 모습이 선 자리는 옛날에 논이나 밭',ARRAY['[4사10-01] 여러 지역의 자연환경과 인문환경의 특징을 살펴보고, 환경의 이용과 개발에 따른 영향을 탐구한다(차시 머리 주석 기준)']::text[],3) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C4','soc',4,2,'u3',4,'바다가 있는 지역의 특징과 변화 — 갯벌·모래사장 · 배가 안전하게 드나드는 항구, 사람의 힘으로 물고기나 김 등을 기르는 양식장 · 고기잡이(배), 수산물 직판장(생선 사고팔기), 바닷가 식당·숙박 시설 · 바닷가 공업 도시: 옛날 고기잡이·농사 → 여러 공장을 세우며 공업 발달 — 바다와 가까워 배로 원료(물건을 만드는 재료)와 제품(공장에서 만든 물건)을 실어 나를 수 있어서 · 공장에서 일하는 사람이 생기고 사는 사람이 늘어남 · 해양 생태 연구원(바닷속 생물의 종류·수·먹이 조사, 환경 변화에 따른 모습 연구)',ARRAY['[4사10-01] 여러 지역의 자연환경과 인문환경의 특징을 살펴보고, 환경의 이용과 개발에 따른 영향을 탐구한다(차시 머리 주석 기준)']::text[],4) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C5','soc',4,2,'u3',5,'환경의 이용과 개발에 따른 영향 — 사람들은 필요에 따라 환경을 이용·개발하고 달라진 환경은 사람들에게 영향 · 산: 스키장·케이블카로 여가 활동 ↔ 삼림 훼손, 산사태 위험, 동식물이 사는 곳이 사라짐 · 골프장 개발 기사: 관광객·지역 경제 ↔ 산 훼손·환경 오염, 의견은 까닭과 함께 · 들: 도로·철도로 교통 발달, 이동 시간 줄고 교류 활발 ↔ 교통 체증·대기 오염·소음 · 바다: 바다의 일부나 갯벌을 새로운 땅으로 = 간척 → 공업 단지·주택 단지, 경제 발전 ↔ 공장 폐수로 환경 오염 → 노력으로 생물이 다시 찾아옴 · 좋은 점과 문제점은 같은 개발에서 함께 생김 · 인간과 환경의 조화: 생태 통로(야생 동물 길), 생태 하천(오염된 하천 되살리기), 자연 휴식년제(일정 기간 출입 막기), 생태 도시(전차·자전거 전용 도로·태양광)',ARRAY['[4사10-01] 여러 지역의 자연환경과 인문환경의 특징을 살펴보고, 환경의 이용과 개발에 따른 영향을 탐구한다(차시 머리 주석 기준)']::text[],5) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C6','soc',4,2,'u3',6,'지역의 환경과 변화 정리 — 자연환경과 인문환경의 뜻 → 세 지역의 특징과 변화 → 이용과 개발의 긍정적·부정적 영향 → 인간과 환경의 조화를 이루는 방법 · 그림 그리기(조화를 이루는 방법 — 바닷가 쓰레기 줍기, 캠핑장, 생태 통로, 자연 휴식년제) · 편지 쓰기(훼손·오염된 자연환경이 되어 사람에게 — 산의 편지: 친구들이 사라졌다, 쉬는 기간을 주면) · 낱말 퍼즐(자연환경·인문환경·교통·산사태·생태 통로·자연 휴식년제) · 생태 통로와 자연 휴식년제는 둘 다 조화를 이루려는 노력',ARRAY['[4사10-01] 여러 지역의 자연환경과 인문환경의 특징을 살펴보고, 환경의 이용과 개발에 따른 영향을 탐구한다(차시 머리 주석 기준)']::text[],6) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C7','soc',4,2,'u3',7,'도시의 뜻 — 밤하늘에서 본 우리나라: 밝게 빛나는 곳 = 밤에도 불이 켜진 곳이 많고 밤늦게까지 활동하는 도시 · 「도시」 하면 떠오르는 낱말을 까닭과 함께(복잡하다 — 사람·상점이 많아서, 빠르다 — 자동차·기차, 바쁘다 — 오가며 움직여서) · 도시는 삶의 터전, 각종 공공 기관과 병원·상점 등 편의 시설이 잘 갖춰짐 · 많은 인구가 모여 살면서 정치·경제·사회 활동의 중심이 되는 곳 = 도시 · 가 본 도시: 건물·높은 빌딩, 자동차·정류장·기차역·지하철역, 시장·오가는 사람',ARRAY['[4사10-02] 도시의 특징을 살펴보고, 도시에 사는 사람들의 생활 모습과 도시 생활의 좋은 점·문제점을 탐구한다(차시 머리 주석 기준)']::text[],7) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C8','soc',4,2,'u3',8,'도시의 특징 — 인구: 우리나라 인구 10명 가운데 9명 정도가 도시에 삶(대부분), 일자리가 많고 생활이 편리해서 · 이동하는 사람·회사·아파트나 연립주택이 많음 · 산업: 제조업(물건을 한 번에 많이 만듦), 상업(시장·대형 할인점에서 사고팖), 금융업(돈을 맡아 주거나 빌려줌), 관광 산업(행사·관광) — 도시에는 다양한 산업 · 교통: 많은 사람과 물건이 빠르고 편리하게 이동, 지하철역·기차역·버스 터미널·공항·항구 · 길이 이어지면 곳과 곳 사이가 가까워짐 · 지도 애플리케이션: 시청·도청 주변, 교통 시설, 산업 단지, 특색 있는 장소',ARRAY['[4사10-02] 도시의 특징을 살펴보고, 도시에 사는 사람들의 생활 모습과 도시 생활의 좋은 점·문제점을 탐구한다(차시 머리 주석 기준)']::text[],8) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C9','soc',4,2,'u3',9,'도시 사람들의 생활 모습 — 사는 곳: 아파트·주택, 상점과 아파트가 함께 있는 건물(단독 주택은 관리가 어렵지만 마음이 편함) · 하는 일: 회사(사무실)·공장에서 물건을 만들거나 은행·우체국처럼 서비스를 제공 · 출퇴근: 지하철은 막히지 않아 예상한 시간에 닿지만 출근 시간엔 붐빔, 자동차는 도로가 막힐 걱정 · 여가 생활: 미술관 관람, 놀이터·공원 자전거, 달리기, 영화관·콘서트 · 무언극(대사 없이 몸짓과 표정만으로 전달하는 연극) · 스마트 도시 전문가(정보 통신 기술로 똑똑하고 효율적인 도시, 도시 문제 분석·해결 — 창의력·집중력)',ARRAY['[4사10-02] 도시의 특징을 살펴보고, 도시에 사는 사람들의 생활 모습과 도시 생활의 좋은 점·문제점을 탐구한다(차시 머리 주석 기준)']::text[],9) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C10','soc',4,2,'u3',10,'도시 생활의 좋은 점과 문제점 — 좋은 점: 교통(이동이 빠르고 편리), 주택(새 주택·아파트 — 쾌적한 주거 공간), 산업(다양한 일자리), 편의 시설(공공 기관·영화관·병원) · 문제점: 교통(특정 시간 혼잡·주차 공간 부족), 주택(집값이 비싸고 낡은 주택), 환경(대기·수질·토양 오염), 쓰레기 양 증가 · 네 갈래가 좋은 점과 문제점에 나란히 — 좋은 점은 상황이 달라지면 문제점이 되기도 함, 좁은 지역에 많은 사람이 모여 살기 때문 · 해결 노력: 바람길 숲(외곽 숲의 맑은 공기 → 미세 먼지·대기 오염 줄이기), 생활 쓰레기 줄이기 캠페인(재사용) · 캠페인 문구(문제 고르기 → 할 일 → 짧고 기억에 남게)',ARRAY['[4사10-02] 도시의 특징을 살펴보고, 도시에 사는 사람들의 생활 모습과 도시 생활의 좋은 점·문제점을 탐구한다(차시 머리 주석 기준)']::text[],10) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO concepts (code,subject,grade,semester,unit_code,lesson_no,name,achievement_codes,ord) VALUES ('SO4-2-u3-C11','soc',4,2,'u3',11,'도시의 특징과 생활 모습 정리 — 도시의 뜻 → 인구·산업·교통 → 사는 집·하는 일·여가 생활 → 좋은 점과 문제점 → 해결 노력 · 정리 방법은 하나가 아님: 도시 그리기(살고 싶은 도시·만들고 싶은 시설) 또는 이야기책 만들기(배경 = 자연과 조화를 이룬 도시, 주인공 = 그 도시에 사는 나) · 이야기책은 도화지로 작은 책 모양을 먼저 만든 뒤 글·그림 · 도시의 모습과 그 속에서 사는 나의 모습을 나란히 이어야 이야기가 섬 · 자연과 조화를 이룬 도시: 체육관·영화관·도서관, 햇빛으로 전기를 만드는 지붕과 가로등, 숲과 물이 흐르는 공원 · 단원 정리: 가운데 단원 이름, 두 갈래(지역의 환경과 변화 / 도시의 특징과 생활 모습)로 묶기, 놀이로 풀기',ARRAY['[4사10-02] 도시의 특징을 살펴보고, 도시에 사는 사람들의 생활 모습과 도시 생활의 좋은 점·문제점을 탐구한다(차시 머리 주석 기준)']::text[],11) ON CONFLICT (code) DO UPDATE SET name=EXCLUDED.name, lesson_no=EXCLUDED.lesson_no, achievement_codes=EXCLUDED.achievement_codes, ord=EXCLUDED.ord;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X01','soc',4,'u3',ARRAY['SO4-2-u3-C1']::text[],'색·크기·풀이 자라는지 같은 겉모습으로 갈래를 정해, 사람들이 만든 논·밭·공원·목장을 자연환경으로 여긴다','누가 만들었나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X02','soc',4,'u3',ARRAY['SO4-2-u3-C1']::text[],'비·눈·바람·기온 같은 날씨를 환경에 넣지 않거나 인문환경으로 여긴다','날씨에 영향을 주는 것도 자연환경') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X03','soc',4,'u3',ARRAY['SO4-2-u3-C1']::text[],'환경을 자연환경이나 인문환경 한쪽으로만 좁히거나, 같은 갈래의 짝이 처음부터 한 가지로 정해져 있다고 여긴다','둘러싸고 있는 모든 것 · 같은 갈래면 짝') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X04','soc',4,'u3',ARRAY['SO4-2-u3-C2']::text[],'산이 많은 지역의 자연환경·시설·하는 일을 들이나 바다 지역의 것과 바꾸어 안다','숲 · 계곡 · 목장 · 산비탈 밭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X05','soc',4,'u3',ARRAY['SO4-2-u3-C2']::text[],'스키장 같은 여가 시설이 생긴 뒤 관광객·식당·숙박 시설·하는 일이 달라진 변화를 놓치거나 옛날과 오늘날을 바꾸어 안다','관광객이 늘고 하는 일이 달라져요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X06','soc',4,'u3',ARRAY['SO4-2-u3-C3']::text[],'들이 펼쳐진 지역의 특징(하천·저수지 가까이 논밭, 벼농사, 비닐하우스, 축사)을 다른 지역의 것과 바꾸어 안다','넓고 평평한 땅 · 논과 밭') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X07','soc',4,'u3',ARRAY['SO4-2-u3-C3']::text[],'많은 사람이 모여 살면서 회사·공장·아파트·도로·상점·문화 시설이 생겨난 변화를 놓치거나, 장소와 그곳의 생활 모습을 잘못 잇는다','사람이 모이면 생기는 것') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X08','soc',4,'u3',ARRAY['SO4-2-u3-C3']::text[],'옛 지도와 요즘 지도를 견주어 알 수 있는 것을 잘못 짐작하거나, 요즘 모습이 선 자리의 옛 모습을 놓친다','학교가 늘면 사는 사람도 늘어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X09','soc',4,'u3',ARRAY['SO4-2-u3-C4']::text[],'바다가 있는 지역의 자연환경·시설(갯벌·모래사장·항구·양식장·수산물 직판장)을 잘못 알거나 양식과 고기잡이를 헷갈린다','기르는 곳 = 양식장') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X10','soc',4,'u3',ARRAY['SO4-2-u3-C4']::text[],'바닷가에 공업이 발달한 까닭(배로 원료와 제품을 실어 나름)을 놓치거나 원료와 제품을 바꾸어 안다','원료는 재료 · 제품은 만든 물건') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X11','soc',4,'u3',ARRAY['SO4-2-u3-C5']::text[],'환경의 이용과 개발은 좋은 점만, 또는 문제점만 가져온다고 여긴다','좋은 점과 문제점이 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X12','soc',4,'u3',ARRAY['SO4-2-u3-C5']::text[],'지역과 그 지역의 이용·개발 모습이나 영향을 잘못 짝짓는다(간척을 산에서, 스키장을 바다에서 등)','산 · 들 · 바다마다 달라요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X13','soc',4,'u3',ARRAY['SO4-2-u3-C5']::text[],'좋은 점만 남기고 문제점만 따로 없앨 수 있다고, 또는 문제를 풀려면 개발을 모두 되돌려야만 한다고 여긴다','함께 생겨요 · 조화를 이뤄요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X14','soc',4,'u3',ARRAY['SO4-2-u3-C5']::text[],'생태 통로·생태 하천·자연 휴식년제의 뜻을 서로 바꾸거나, 조화를 이루려는 노력을 개발을 더 늘리는 일로 여긴다','동물의 길 · 하천 되살리기 · 쉬는 기간') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X15','soc',4,'u3',ARRAY['SO4-2-u3-C5']::text[],'개발에 관한 의견을 까닭 없이 내거나, 한쪽 영향만 보고 정한다','좋은 점과 문제점을 따져 까닭과 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X16','soc',4,'u3',ARRAY['SO4-2-u3-C6']::text[],'정리 활동에서 꾸밈(그림 솜씨·편지 길이)만 보고 담을 내용을 놓치거나, 정리 방법은 한 가지뿐이라고 여긴다','무엇을 담았나요?') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X17','soc',4,'u3',ARRAY['SO4-2-u3-C6']::text[],'단원 낱말(산사태·간척·교통·자연 휴식년제)의 뜻을 서로 바꾸거나, 생태 통로와 자연 휴식년제가 같은 조화 노력임을 놓친다','낱말의 뜻을 다시 떠올려요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X18','soc',4,'u3',ARRAY['SO4-2-u3-C7']::text[],'사람이 많거나 건물이 높기만 하면 도시라고 여겨, 정치·경제·사회 활동의 중심이라는 뜻을 놓친다','많은 인구 · 활동의 중심') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X19','soc',4,'u3',ARRAY['SO4-2-u3-C7']::text[],'도시에 공공 기관·편의 시설이 잘 갖춰져 있음이나, 밤에 밝게 빛나는 까닭을 놓친다','불 켜진 곳 · 공공 기관 · 편의 시설') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X20','soc',4,'u3',ARRAY['SO4-2-u3-C7']::text[],'「도시」 하면 떠오르는 낱말과 까닭을 엉뚱하게 잇거나 까닭 없이 말한다','낱말과 까닭을 함께') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X21','soc',4,'u3',ARRAY['SO4-2-u3-C8']::text[],'도시에 사는 인구가 얼마나 되는지 잘못 안다(10명 가운데 한두 명 등)','10명 가운데 9명 정도') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X22','soc',4,'u3',ARRAY['SO4-2-u3-C8']::text[],'산업 이름과 하는 일(제조업·상업·금융업·관광 산업)을 바꾸어 알거나, 도시에는 한 가지 산업만 있다고 여긴다','만들기 · 사고팔기 · 돈 · 관광') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X23','soc',4,'u3',ARRAY['SO4-2-u3-C8']::text[],'교통이 발달한 모습을 보여 주는 곳을 잘못 고르거나, 길이 이어지면 곳과 곳 사이가 가까워짐을 놓친다','역 · 터미널 · 공항 · 항구') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X24','soc',4,'u3',ARRAY['SO4-2-u3-C9']::text[],'도시 사람들의 사는 곳과 하는 일을 다른 지역의 것과 바꾸어 안다(목장·양식장·벼농사 등)','아파트 · 회사 · 공장 · 은행') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X25','soc',4,'u3',ARRAY['SO4-2-u3-C9']::text[],'도시 사람들의 여가 생활을 잘못 알거나, 교통수단의 좋은 점과 불편한 점을 한쪽만 본다','지하철은 안 막히지만 붐벼요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X26','soc',4,'u3',ARRAY['SO4-2-u3-C9']::text[],'무언극의 뜻(대사 없이 몸짓과 표정만으로 전달)을 잘못 안다','말 없이 몸짓과 표정') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X27','soc',4,'u3',ARRAY['SO4-2-u3-C10']::text[],'도시 생활에는 좋은 점만, 또는 문제점만 있다고 여긴다','좋은 점도 문제점도 있어요') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X28','soc',4,'u3',ARRAY['SO4-2-u3-C10']::text[],'좋은 점이 상황이 달라지면 문제점이 될 수 있음을 놓치거나, 그 까닭(좁은 지역에 많은 사람)을 놓친다','좁은 곳에 많은 사람') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X29','soc',4,'u3',ARRAY['SO4-2-u3-C10']::text[],'도시 문제와 그 문제를 해결하려는 노력을 잘못 짝짓는다(바람길 숲을 쓰레기 문제에 등)','바람길 숲 = 공기 · 캠페인 = 쓰레기') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X30','soc',4,'u3',ARRAY['SO4-2-u3-C11']::text[],'이야기책을 만드는 차례나 담을 것(도시의 모습과 그 속의 나)을 잘못 알거나, 정리 방법은 하나뿐이라고 여긴다','책 모양 먼저 · 도시와 나를 나란히') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X31','soc',4,'u3',ARRAY['SO4-2-u3-C11']::text[],'자연과 조화를 이룬 도시의 모습을 잘못 안다(굴뚝 연기·쓰레기가 많은 도시 등)','자연을 해치지 않는 에너지 · 숲과 물') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO misconceptions (code,subject,grade,unit_code,concept_codes,title,teacher_hint) VALUES ('SO4-2-u3-X32','soc',4,'u3',ARRAY['SO4-2-u3-C6','SO4-2-u3-C11']::text[],'단원 내용을 두 갈래(지역의 환경과 변화 / 도시의 특징과 생활 모습)로 묶을 때 서로 바꾸어 붙인다','환경과 변화 · 도시와 생활') ON CONFLICT (code) DO UPDATE SET title=EXCLUDED.title, teacher_hint=EXCLUDED.teacher_hint, concept_codes=EXCLUDED.concept_codes;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#1','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',1,'mc','auto','우리를 둘러싸고 있는 모든 것을 무엇이라고 하나요?',ARRAY['SO4-2-u3-X03','SO4-2-u3-X02']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C1","difficulty":1,"kind":"mc","stem":"우리를 둘러싸고 있는 모든 것을 무엇이라고 하나요?","options":[{"t":"환경","correct":true},{"t":"지도","mis":"SO4-2-u3-X03"},{"t":"날씨","mis":"SO4-2-u3-X02"},{"t":"도로","mis":"SO4-2-u3-X03"}],"explanation":["산도 건물도 둘러싸요.","모두 함께 부르는 말이에요.","환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#2','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',1,'sa','auto','환경 가운데 사람들이 만든 것을 ○○환경이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C1","difficulty":1,"kind":"sa","stem":"환경 가운데 사람들이 만든 것을 ○○환경이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["인문"],"explanation":["사람들이 만들었어요.","인◯환경이에요.","인문이에요."],"mis":"SO4-2-u3-X01"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#3','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',1,'ox','auto','하천은 자연 그대로 생겨난 자연환경이에요.',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C1","difficulty":1,"kind":"ox","stem":"하천은 자연 그대로 생겨난 자연환경이에요.","answer":"O","reason_options":[{"t":"빗물과 지하수가 낮은 곳으로 흘러가며 만든 물줄기이기 때문에","correct":true},{"t":"사람들이 땅을 파서 만든 물길이기 때문에","mis":"SO4-2-u3-X01"}],"mis":"SO4-2-u3-X01","explanation":["하천은 누가 만들었나요?","자연이 만들었어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#4','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',1,'mc','auto','환경 카드 열두 장 가운데 자연환경은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C1","difficulty":1,"kind":"mc","stem":"환경 카드 열두 장 가운데 자연환경은 무엇인가요?","options":[{"t":"섬","correct":true},{"t":"다리","mis":"SO4-2-u3-X01"},{"t":"공원","mis":"SO4-2-u3-X01"},{"t":"시장","mis":"SO4-2-u3-X01"}],"explanation":["사람이 만들지 않은 것을 찾아요.","섬은 바다에 생겨났어요.","섬이에요."],"asset":{"type":"passage","lines":["하천 · 갯벌 · 섬 · 바람 · 스키장 · 다리","공원 · 도로 · 공장 · 아파트 · 밭 · 시장"],"title":"환경 카드 열두 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#5','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',2,'mc','auto','비, 눈, 바람, 기온은 어느 환경에 속하나요?',ARRAY['SO4-2-u3-X02','SO4-2-u3-X01']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C1","difficulty":2,"kind":"mc","stem":"비, 눈, 바람, 기온은 어느 환경에 속하나요?","options":[{"t":"날씨에 영향을 주는 것이라 자연환경에 속해요","correct":true},{"t":"날마다 달라지니 인문환경에 속해요","mis":"SO4-2-u3-X02"},{"t":"눈에 잘 안 보이니 환경이 아니에요","mis":"SO4-2-u3-X02"},{"t":"사람들이 만든 것이라 인문환경이에요","mis":"SO4-2-u3-X01"}],"explanation":["누가 만들었나요?","자연이에요.","자연환경이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#6','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',2,'mc','auto','논과 밭이 인문환경인 까닭은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C1","difficulty":2,"kind":"mc","stem":"논과 밭이 인문환경인 까닭은 무엇인가요?","options":[{"t":"사람들이 농사를 지으려고 만든 것이기 때문이에요","correct":true},{"t":"곡식이 자라는 땅이기 때문이에요","mis":"SO4-2-u3-X01"},{"t":"넓게 펼쳐져 있기 때문이에요","mis":"SO4-2-u3-X01"},{"t":"비가 오면 물이 고이기 때문이에요","mis":"SO4-2-u3-X01"}],"explanation":["겉모습이 아니에요.","누가 만들었나요?","사람들이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#7','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',2,'ox','auto','공원은 나무와 풀이 많으니 자연환경이에요.',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C1","difficulty":2,"kind":"ox","stem":"공원은 나무와 풀이 많으니 자연환경이에요.","answer":"X","reason_options":[{"t":"나무가 있어도 사람들이 만든 곳이라 인문환경이기 때문에","correct":true},{"t":"초록색으로 보이는 것은 모두 자연환경이기 때문에","mis":"SO4-2-u3-X01"}],"mis":"SO4-2-u3-X01","explanation":["공원은 누가 만들었나요?","사람들이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#8','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',2,'match','auto','환경 카드를 알맞은 갈래와 이으세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-2-u3-C1","difficulty":2,"kind":"match","stem":"환경 카드를 알맞은 갈래와 이으세요.","pairs":[{"l":"갯벌","r":"자연환경 — 바닷가에 생겨났어요"},{"l":"스키장","r":"인문환경 — 사람들이 만든 놀이 시설이에요"},{"l":"도로","r":"인문환경 — 사람들이 오가려고 만들었어요"}],"mis":"SO4-2-u3-X01","explanation":["갯벌은 자연이에요.","스키장은 사람이 만들었어요.","도로도 사람이 만들었어요."],"asset":{"type":"passage","lines":["하천 · 갯벌 · 섬 · 바람 · 스키장 · 다리","공원 · 도로 · 공장 · 아파트 · 밭 · 시장"],"title":"환경 카드 열두 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#9','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',2,'blank','auto','자연환경과 인문환경은 (    )가 만들었는지를 보고 나눠요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u3-X01','SO4-2-u3-X03']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C1","difficulty":2,"kind":"blank","stem":"자연환경과 인문환경은 (    )가 만들었는지를 보고 나눠요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"누구","correct":true},{"t":"얼마나 큰지","mis":"SO4-2-u3-X01"},{"t":"무슨 색인지","mis":"SO4-2-u3-X01"},{"t":"언제 보았는지","mis":"SO4-2-u3-X03"}],"explanation":["색도 크기도 아니에요.","만든 쪽을 봐요.","누구예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_basic#10','soc',4,2,'u3','L01','g4_2_soc_u3_L01_basic','lesson_basic','SO4-2-u3-C1',3,'mc','auto','한 지역을 찍은 두 사진에서 달라진 점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X03','SO4-2-u3-X01']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C1","difficulty":3,"kind":"mc","stem":"한 지역을 찍은 두 사진에서 달라진 점으로 알맞은 것은 무엇인가요?","options":[{"t":"논이 있던 곳에 높은 건물과 아파트가 생기고 도로가 넓어졌어요","correct":true},{"t":"높은 건물이 사라지고 논이 늘었어요","mis":"SO4-2-u3-X03"},{"t":"하천과 산이 새로 생겼어요","mis":"SO4-2-u3-X01"},{"t":"달라진 것이 하나도 없어요","mis":"SO4-2-u3-X03"}],"explanation":["예전엔 논이에요.","최근엔 건물이에요.","도로도 넓어졌어요."],"asset":{"type":"passage","lines":["예전 사진 — 넓게 펼쳐진 논이 보여요. 길은 좁아요.","최근 사진 — 높은 건물과 아파트 단지가 보여요. 도로가 넓어졌어요."],"title":"한 지역을 찍은 두 사진(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#1','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',2,'mc','auto','환경 카드 열두 장을 두 갈래로 나누면 자연환경은 몇 장인가요?',ARRAY['SO4-2-u3-X01','SO4-2-u3-X02']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C1","difficulty":2,"kind":"mc","stem":"환경 카드 열두 장을 두 갈래로 나누면 자연환경은 몇 장인가요?","options":[{"t":"4장","correct":true},{"t":"6장","mis":"SO4-2-u3-X01"},{"t":"2장","mis":"SO4-2-u3-X02"},{"t":"8장","mis":"SO4-2-u3-X01"}],"explanation":["하천·갯벌·섬·바람이에요.","나머지는 사람이 만들었어요.","4장이에요."],"asset":{"type":"passage","lines":["하천 · 갯벌 · 섬 · 바람 · 스키장 · 다리","공원 · 도로 · 공장 · 아파트 · 밭 · 시장"],"title":"환경 카드 열두 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#2','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',2,'ox','auto','하천 카드는 갯벌, 섬, 바람 가운데 어느 카드와도 짝이 될 수 있어요.',ARRAY['SO4-2-u3-X03']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C1","difficulty":2,"kind":"ox","stem":"하천 카드는 갯벌, 섬, 바람 가운데 어느 카드와도 짝이 될 수 있어요.","answer":"O","reason_options":[{"t":"네 장 모두 자연 그대로 생겨난 자연환경이기 때문에","correct":true},{"t":"하천의 짝은 처음부터 한 장으로 정해져 있기 때문에","mis":"SO4-2-u3-X03"}],"mis":"SO4-2-u3-X03","explanation":["네 장의 갈래를 봐요.","모두 자연환경이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["하천 · 갯벌 · 섬 · 바람 · 스키장 · 다리","공원 · 도로 · 공장 · 아파트 · 밭 · 시장"],"title":"환경 카드 열두 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#3','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',3,'error','auto','환경 카드를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X01','SO4-2-u3-X03']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C1","difficulty":3,"kind":"error","stem":"환경 카드를 나누며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「공원에는 나무가 많으니까 자연환경이야.」","correct":true,"mis_target":"SO4-2-u3-X01"},{"t":"친구 다 — 「밭은 사람들이 만든 곳이니까 인문환경이야.」","mis":"SO4-2-u3-X01"},{"t":"친구 라 — 「갯벌은 자연 그대로 생겨났어.」","mis":"SO4-2-u3-X03"}],"explanation":["공원은 누가 만들었나요?","사람들이에요.","친구 가가 잘못 말했어요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"공원에는 나무가 많으니까 자연환경이야."},{"who":"친구 나","text":"바람은 눈에 안 보이니까 환경이 아니야."},{"who":"친구 다","text":"밭은 사람들이 농사를 지으려고 만든 곳이니까 인문환경이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#4','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',3,'mc','auto','친구 나의 말을 바르게 고친 것은 무엇인가요?',ARRAY['SO4-2-u3-X02','SO4-2-u3-X03']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C1","difficulty":3,"kind":"mc","stem":"친구 나의 말을 바르게 고친 것은 무엇인가요?","options":[{"t":"바람은 날씨에 영향을 주는 것이라 자연환경에 속해요","correct":true},{"t":"바람은 사람들이 만든 인문환경이에요","mis":"SO4-2-u3-X02"},{"t":"바람은 눈에 보이지 않으니 환경이 아니에요","mis":"SO4-2-u3-X02"},{"t":"바람은 바다에서만 부는 환경이에요","mis":"SO4-2-u3-X03"}],"explanation":["바람도 둘러싸요.","날씨에 영향을 줘요.","자연환경이에요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"공원에는 나무가 많으니까 자연환경이야."},{"who":"친구 나","text":"바람은 눈에 안 보이니까 환경이 아니야."},{"who":"친구 다","text":"밭은 사람들이 농사를 지으려고 만든 곳이니까 인문환경이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#5','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',3,'mc','auto','「자연환경 짝」과 「인문환경 짝」을 바르게 만든 것은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C1","difficulty":3,"kind":"mc","stem":"「자연환경 짝」과 「인문환경 짝」을 바르게 만든 것은 무엇인가요?","options":[{"t":"섬과 바람 / 다리와 시장","correct":true},{"t":"섬과 다리 / 바람과 시장","mis":"SO4-2-u3-X01"},{"t":"공원과 갯벌 / 하천과 공장","mis":"SO4-2-u3-X01"},{"t":"밭과 하천 / 섬과 아파트","mis":"SO4-2-u3-X01"}],"explanation":["같은 갈래끼리예요.","섬·바람은 자연이에요.","다리·시장은 사람이에요."],"asset":{"type":"passage","lines":["하천 · 갯벌 · 섬 · 바람 · 스키장 · 다리","공원 · 도로 · 공장 · 아파트 · 밭 · 시장"],"title":"환경 카드 열두 장"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#6','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',3,'ox','auto','목장은 소와 양이 풀을 뜯는 곳이니 자연환경이에요.',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C1","difficulty":3,"kind":"ox","stem":"목장은 소와 양이 풀을 뜯는 곳이니 자연환경이에요.","answer":"X","reason_options":[{"t":"목장은 사람들이 가축을 기르려고 만든 인문환경이기 때문에","correct":true},{"t":"동물이 사는 곳은 모두 자연환경이기 때문에","mis":"SO4-2-u3-X01"}],"mis":"SO4-2-u3-X01","explanation":["목장을 누가 만들었나요?","사람들이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#7','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',3,'mc','auto','자연환경만 모은 것은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C1","difficulty":3,"kind":"mc","stem":"자연환경만 모은 것은 무엇인가요?","options":[{"t":"산 · 갯벌 · 기온","correct":true},{"t":"산 · 항구 · 기온","mis":"SO4-2-u3-X01"},{"t":"들 · 건물 · 비","mis":"SO4-2-u3-X01"},{"t":"하천 · 눈 · 목장","mis":"SO4-2-u3-X01"}],"explanation":["하나씩 따져요.","항구·건물·목장은 사람이 만들었어요.","산·갯벌·기온이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#8','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',4,'mc','auto','한 지역을 찍은 두 사진을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X01','SO4-2-u3-X03','SO4-2-u3-X02']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C1","difficulty":4,"kind":"mc","stem":"한 지역을 찍은 두 사진을 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사람들이 논이 있던 자리에 건물과 도로를 만들면서 인문환경이 바뀌었어요","correct":true},{"t":"자연환경인 논이 건물로 바뀌었어요","mis":"SO4-2-u3-X01"},{"t":"환경은 시간이 지나도 바뀌지 않아요","mis":"SO4-2-u3-X03"},{"t":"바람과 기온이 사람 손으로 바뀌었어요","mis":"SO4-2-u3-X02"}],"explanation":["논도 건물도 사람이 만들었어요.","인문환경이 바뀌었어요.","그것을 골라요."],"asset":{"type":"passage","lines":["예전 사진 — 넓게 펼쳐진 논이 보여요. 길은 좁아요.","최근 사진 — 높은 건물과 아파트 단지가 보여요. 도로가 넓어졌어요."],"title":"한 지역을 찍은 두 사진(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#9','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',4,'mc','auto','친구들의 말을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X01','SO4-2-u3-X02']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C1","difficulty":4,"kind":"mc","stem":"친구들의 말을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"겉모습이 아니라 자연 그대로 생겼는지, 사람들이 만들었는지로 갈래를 정해요","correct":true},{"t":"초록색이 많으면 자연환경이에요","mis":"SO4-2-u3-X01"},{"t":"눈에 보이지 않으면 환경이 아니에요","mis":"SO4-2-u3-X02"},{"t":"크고 넓은 것은 인문환경이에요","mis":"SO4-2-u3-X01"}],"explanation":["친구 가는 나무를 봤어요.","친구 나는 눈을 봤어요.","친구 다는 누가 만들었는지 봤어요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"공원에는 나무가 많으니까 자연환경이야."},{"who":"친구 나","text":"바람은 눈에 안 보이니까 환경이 아니야."},{"who":"친구 다","text":"밭은 사람들이 농사를 지으려고 만든 곳이니까 인문환경이야."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L01_challenge#10','soc',4,2,'u3','L01','g4_2_soc_u3_L01_challenge','lesson_challenge','SO4-2-u3-C1',4,'essay','teacher','우리 지역에서 볼 수 있는 자연환경과 인문환경을 하나씩 쓰고, 그렇게 나눈 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C1","difficulty":4,"kind":"essay","stem":"우리 지역에서 볼 수 있는 자연환경과 인문환경을 하나씩 쓰고, 그렇게 나눈 까닭을 쓰세요.","answer_guide":{"answer":"예: 자연환경은 학교 뒤의 산이에요. 사람이 만들지 않고 자연 그대로 생겨났기 때문이에요. 인문환경은 학교 앞 도로예요. 사람들이 차와 사람이 다니도록 만들었기 때문이에요.","scoring_points":["자연환경을 하나 썼는가","인문환경을 하나 썼는가","누가 만들었는지로 까닭을 썼는가"]},"explanation":["하나씩 골라요.","누가 만들었나요?","까닭을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#1','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',1,'mc','auto','산이 많은 지역에서 볼 수 있는 자연환경으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X04']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C2","difficulty":1,"kind":"mc","stem":"산이 많은 지역에서 볼 수 있는 자연환경으로 알맞은 것은 무엇인가요?","options":[{"t":"울창한 숲과 계곡","correct":true},{"t":"넓은 모래사장","mis":"SO4-2-u3-X04"},{"t":"끝없이 펼쳐진 들판","mis":"SO4-2-u3-X04"},{"t":"바닷가 갯벌","mis":"SO4-2-u3-X04"}],"explanation":["산을 떠올려요.","숲과 계곡이 있어요.","그것을 골라요."],"asset":{"type":"passage","lines":["㉠ 울창한 숲과 산봉우리, 계곡","㉡ 소나 양을 기르는 목장","㉢ 바람으로 전기를 만드는 풍력 발전기","㉣ 산비탈의 밭과 약초·버섯 재배","㉤ 물을 저장하거나 전기를 만드는 댐","㉥ 스키장 · 캠핑장 · 삼림욕장"],"title":"산이 많은 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#2','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',1,'sa','auto','산이 많은 지역에서 바람으로 전기를 만들어 내는 시설은 무엇인가요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C2","difficulty":1,"kind":"sa","stem":"산이 많은 지역에서 바람으로 전기를 만들어 내는 시설은 무엇인가요? 다섯 글자로 쓰세요.","answer":["풍력 발전기","풍력발전기"],"explanation":["바람의 힘이에요.","풍력 ◯◯◯예요.","풍력 발전기예요."],"asset":{"type":"passage","lines":["㉠ 울창한 숲과 산봉우리, 계곡","㉡ 소나 양을 기르는 목장","㉢ 바람으로 전기를 만드는 풍력 발전기","㉣ 산비탈의 밭과 약초·버섯 재배","㉤ 물을 저장하거나 전기를 만드는 댐","㉥ 스키장 · 캠핑장 · 삼림욕장"],"title":"산이 많은 지역에서 볼 수 있는 모습"},"mis":"SO4-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#3','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',1,'ox','auto','산비탈은 산에 가파르게 기울어져 있는 곳이에요.',ARRAY['SO4-2-u3-X04']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C2","difficulty":1,"kind":"ox","stem":"산비탈은 산에 가파르게 기울어져 있는 곳이에요.","answer":"O","reason_options":[{"t":"산의 비스듬한 면을 가리키는 말이기 때문에","correct":true},{"t":"산 아래 넓고 평평한 땅을 가리키는 말이기 때문에","mis":"SO4-2-u3-X04"}],"mis":"SO4-2-u3-X04","explanation":["비탈은 기울어진 곳이에요.","산의 비스듬한 면이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#4','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',1,'mc','auto','산이 많은 지역에서 사람들이 여가 활동을 즐기도록 만든 곳이 아닌 것은 무엇인가요?',ARRAY['SO4-2-u3-X05']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C2","difficulty":1,"kind":"mc","stem":"산이 많은 지역에서 사람들이 여가 활동을 즐기도록 만든 곳이 아닌 것은 무엇인가요?","options":[{"t":"계곡","correct":true},{"t":"스키장","mis":"SO4-2-u3-X05"},{"t":"캠핑장","mis":"SO4-2-u3-X05"},{"t":"삼림욕장","mis":"SO4-2-u3-X05"}],"explanation":["사람이 만든 곳을 찾아요.","계곡은 자연이에요.","계곡을 골라요."],"asset":{"type":"passage","lines":["㉠ 울창한 숲과 산봉우리, 계곡","㉡ 소나 양을 기르는 목장","㉢ 바람으로 전기를 만드는 풍력 발전기","㉣ 산비탈의 밭과 약초·버섯 재배","㉤ 물을 저장하거나 전기를 만드는 댐","㉥ 스키장 · 캠핑장 · 삼림욕장"],"title":"산이 많은 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#5','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',2,'mc','auto','산이 많은 지역의 사람들이 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X04']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C2","difficulty":2,"kind":"mc","stem":"산이 많은 지역의 사람들이 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"산비탈에 밭을 만들어 농사를 짓거나 약초와 버섯을 재배해요","correct":true},{"t":"넓은 논에서 벼농사를 크게 지어요","mis":"SO4-2-u3-X04"},{"t":"바다에서 물고기를 잡아요","mis":"SO4-2-u3-X04"},{"t":"갯벌에서 조개를 캐요","mis":"SO4-2-u3-X04"}],"explanation":["산비탈을 떠올려요.","밭과 약초예요.","그것을 골라요."],"asset":{"type":"passage","lines":["㉠ 울창한 숲과 산봉우리, 계곡","㉡ 소나 양을 기르는 목장","㉢ 바람으로 전기를 만드는 풍력 발전기","㉣ 산비탈의 밭과 약초·버섯 재배","㉤ 물을 저장하거나 전기를 만드는 댐","㉥ 스키장 · 캠핑장 · 삼림욕장"],"title":"산이 많은 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#6','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',2,'match','auto','산이 많은 지역의 모습과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u3-C2","difficulty":2,"kind":"match","stem":"산이 많은 지역의 모습과 하는 일을 알맞게 이으세요.","pairs":[{"l":"목장","r":"소나 양을 길러요"},{"l":"댐","r":"물을 저장하거나 전기를 만들어요"},{"l":"산비탈 밭","r":"옥수수나 감자 농사를 지어요"}],"mis":"SO4-2-u3-X04","explanation":["목장은 가축이에요.","댐은 물이에요.","밭은 농사예요."],"asset":{"type":"passage","lines":["㉠ 울창한 숲과 산봉우리, 계곡","㉡ 소나 양을 기르는 목장","㉢ 바람으로 전기를 만드는 풍력 발전기","㉣ 산비탈의 밭과 약초·버섯 재배","㉤ 물을 저장하거나 전기를 만드는 댐","㉥ 스키장 · 캠핑장 · 삼림욕장"],"title":"산이 많은 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#7','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',2,'ox','auto','스키장 주변에 식당이나 숙박 시설이 생긴 것은 관광객이 찾아오기 때문이에요.',ARRAY['SO4-2-u3-X05']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C2","difficulty":2,"kind":"ox","stem":"스키장 주변에 식당이나 숙박 시설이 생긴 것은 관광객이 찾아오기 때문이에요.","answer":"O","reason_options":[{"t":"관광객에게 음식을 팔거나 숙소를 빌려주려고 지었기 때문에","correct":true},{"t":"스키장과 식당은 서로 관계가 없기 때문에","mis":"SO4-2-u3-X05"}],"mis":"SO4-2-u3-X05","explanation":["스키장에 누가 오나요?","관광객이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#8','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',2,'mc','auto','일기에 나타난 ○○군의 옛날 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X05']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C2","difficulty":2,"kind":"mc","stem":"일기에 나타난 ○○군의 옛날 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"산비탈에 밭이 많았고 옥수수와 감자 농사를 지었어요","correct":true},{"t":"큰 스키장이 있었어요","mis":"SO4-2-u3-X05"},{"t":"식당과 숙박 시설이 줄지어 있었어요","mis":"SO4-2-u3-X05"},{"t":"관광객이 아주 많았어요","mis":"SO4-2-u3-X05"}],"explanation":["아버지 어릴 때예요.","산비탈 밭이에요.","옥수수와 감자예요."],"asset":{"type":"passage","lines":["아버지의 고향 ○○군에 다녀왔다.","아버지께서 어릴 때는 산비탈에 밭이 많았다고 하셨다.","그때는 사람들이 주로 옥수수와 감자 농사를 지었다고 한다.","지금은 큰 스키장이 생겨 관광객이 아주 많아졌다.","스키장 둘레에는 식당과 숙박 시설이 줄지어 있었다."],"title":"산골 고장에 다녀온 일기(지어낸 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#9','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',2,'blank','auto','일기에서 스키장이 생기면서 ○○군에 (    )이 크게 늘었어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u3-X05','SO4-2-u3-X04']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C2","difficulty":2,"kind":"blank","stem":"일기에서 스키장이 생기면서 ○○군에 (    )이 크게 늘었어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"관광객","correct":true},{"t":"감자밭","mis":"SO4-2-u3-X05"},{"t":"산봉우리","mis":"SO4-2-u3-X04"},{"t":"계곡","mis":"SO4-2-u3-X04"}],"explanation":["지금 모습이에요.","찾아오는 사람이에요.","관광객이에요."],"asset":{"type":"passage","lines":["아버지의 고향 ○○군에 다녀왔다.","아버지께서 어릴 때는 산비탈에 밭이 많았다고 하셨다.","그때는 사람들이 주로 옥수수와 감자 농사를 지었다고 한다.","지금은 큰 스키장이 생겨 관광객이 아주 많아졌다.","스키장 둘레에는 식당과 숙박 시설이 줄지어 있었다."],"title":"산골 고장에 다녀온 일기(지어낸 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_basic#10','soc',4,2,'u3','L02','g4_2_soc_u3_L02_basic','lesson_basic','SO4-2-u3-C2',3,'mc','auto','일기를 보고 스키장이 생긴 뒤 ○○군 사람들에게 나타났을 변화로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X05']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C2","difficulty":3,"kind":"mc","stem":"일기를 보고 스키장이 생긴 뒤 ○○군 사람들에게 나타났을 변화로 가장 알맞은 것은 무엇인가요?","options":[{"t":"식당이나 숙박 시설에서 일하는 사람이 생기는 등 하는 일이 달라졌어요","correct":true},{"t":"모두 옥수수 농사만 짓게 되었어요","mis":"SO4-2-u3-X05"},{"t":"찾아오는 사람이 줄었어요","mis":"SO4-2-u3-X05"},{"t":"하는 일은 하나도 달라지지 않았어요","mis":"SO4-2-u3-X05"}],"explanation":["관광객이 늘었어요.","식당과 숙소가 생겼어요.","하는 일이 달라졌어요."],"asset":{"type":"passage","lines":["아버지의 고향 ○○군에 다녀왔다.","아버지께서 어릴 때는 산비탈에 밭이 많았다고 하셨다.","그때는 사람들이 주로 옥수수와 감자 농사를 지었다고 한다.","지금은 큰 스키장이 생겨 관광객이 아주 많아졌다.","스키장 둘레에는 식당과 숙박 시설이 줄지어 있었다."],"title":"산골 고장에 다녀온 일기(지어낸 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#1','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',2,'mc','auto','산이 많은 지역에서 볼 수 있는 모습 가운데 인문환경만 고른 것은 무엇인가요?',ARRAY['SO4-2-u3-X01','SO4-2-u3-X03']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C2","difficulty":2,"kind":"mc","stem":"산이 많은 지역에서 볼 수 있는 모습 가운데 인문환경만 고른 것은 무엇인가요?","options":[{"t":"㉡ · ㉢ · ㉤","correct":true},{"t":"㉠ · ㉡ · ㉢","mis":"SO4-2-u3-X01"},{"t":"㉠ · ㉤ · ㉥","mis":"SO4-2-u3-X01"},{"t":"㉠ 하나뿐","mis":"SO4-2-u3-X03"}],"explanation":["㉠은 자연이에요.","목장·발전기·댐은 사람이 만들었어요.","㉡·㉢·㉤이에요."],"asset":{"type":"passage","lines":["㉠ 울창한 숲과 산봉우리, 계곡","㉡ 소나 양을 기르는 목장","㉢ 바람으로 전기를 만드는 풍력 발전기","㉣ 산비탈의 밭과 약초·버섯 재배","㉤ 물을 저장하거나 전기를 만드는 댐","㉥ 스키장 · 캠핑장 · 삼림욕장"],"title":"산이 많은 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#2','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',2,'ox','auto','일기 속 ○○군의 옛날과 지금 모습은 서로 같아요.',ARRAY['SO4-2-u3-X05']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C2","difficulty":2,"kind":"ox","stem":"일기 속 ○○군의 옛날과 지금 모습은 서로 같아요.","answer":"X","reason_options":[{"t":"옛날엔 밭과 농사, 지금은 스키장과 관광객으로 달라졌기 때문에","correct":true},{"t":"산이 많은 지역은 시간이 지나도 바뀌지 않기 때문에","mis":"SO4-2-u3-X05"}],"mis":"SO4-2-u3-X05","explanation":["옛날을 봐요.","지금을 봐요.","그래서 X예요."],"asset":{"type":"passage","lines":["아버지의 고향 ○○군에 다녀왔다.","아버지께서 어릴 때는 산비탈에 밭이 많았다고 하셨다.","그때는 사람들이 주로 옥수수와 감자 농사를 지었다고 한다.","지금은 큰 스키장이 생겨 관광객이 아주 많아졌다.","스키장 둘레에는 식당과 숙박 시설이 줄지어 있었다."],"title":"산골 고장에 다녀온 일기(지어낸 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#3','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',3,'error','auto','산이 많은 지역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X04','SO4-2-u3-X05']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C2","difficulty":3,"kind":"error","stem":"산이 많은 지역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「산이 많은 지역에서는 넓은 논에서 벼농사를 주로 지어.」","correct":true,"mis_target":"SO4-2-u3-X04"},{"t":"친구 가 — 「목장에서 소나 양을 길러.」","mis":"SO4-2-u3-X04"},{"t":"친구 다 — 「스키장 주변에 숙박 시설이 생겼어.」","mis":"SO4-2-u3-X05"}],"explanation":["산은 기울어져 있어요.","넓은 논이 어려워요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 울창한 숲과 산봉우리, 계곡","㉡ 소나 양을 기르는 목장","㉢ 바람으로 전기를 만드는 풍력 발전기","㉣ 산비탈의 밭과 약초·버섯 재배","㉤ 물을 저장하거나 전기를 만드는 댐","㉥ 스키장 · 캠핑장 · 삼림욕장"],"title":"산이 많은 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#4','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',3,'mc','auto','일기에서 옛날 이야기와 오늘날 이야기를 가르는 곳은 어디인가요?',ARRAY['SO4-2-u3-X05']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C2","difficulty":3,"kind":"mc","stem":"일기에서 옛날 이야기와 오늘날 이야기를 가르는 곳은 어디인가요?","options":[{"t":"「그때는 …」 문장과 「지금은 …」 문장 사이","correct":true},{"t":"첫 문장과 둘째 문장 사이","mis":"SO4-2-u3-X05"},{"t":"「지금은 …」 문장과 마지막 문장 사이","mis":"SO4-2-u3-X05"},{"t":"가를 곳이 없어요","mis":"SO4-2-u3-X05"}],"explanation":["옛날 이야기를 찾아요.","지금 이야기가 시작돼요.","그 사이예요."],"asset":{"type":"passage","lines":["아버지의 고향 ○○군에 다녀왔다.","아버지께서 어릴 때는 산비탈에 밭이 많았다고 하셨다.","그때는 사람들이 주로 옥수수와 감자 농사를 지었다고 한다.","지금은 큰 스키장이 생겨 관광객이 아주 많아졌다.","스키장 둘레에는 식당과 숙박 시설이 줄지어 있었다."],"title":"산골 고장에 다녀온 일기(지어낸 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#5','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',3,'mc','auto','산이 많은 지역에 스키장이 생기면 둘레에 함께 생기기 쉬운 것은 무엇인가요?',ARRAY['SO4-2-u3-X04']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C2","difficulty":3,"kind":"mc","stem":"산이 많은 지역에 스키장이 생기면 둘레에 함께 생기기 쉬운 것은 무엇인가요?","options":[{"t":"식당과 숙박 시설","correct":true},{"t":"갯벌과 모래사장","mis":"SO4-2-u3-X04"},{"t":"넓은 논과 저수지","mis":"SO4-2-u3-X04"},{"t":"새 산봉우리","mis":"SO4-2-u3-X04"}],"explanation":["관광객이 와요.","먹고 자야 해요.","식당과 숙박 시설이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#6','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',3,'ox','auto','산이 많은 지역의 댐은 사람들이 만든 인문환경이에요.',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C2","difficulty":3,"kind":"ox","stem":"산이 많은 지역의 댐은 사람들이 만든 인문환경이에요.","answer":"O","reason_options":[{"t":"물을 저장하거나 전기를 만들려고 사람들이 지은 시설이기 때문에","correct":true},{"t":"산에 있는 것은 모두 자연환경이기 때문에","mis":"SO4-2-u3-X01"}],"mis":"SO4-2-u3-X01","explanation":["댐은 누가 지었나요?","사람들이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 울창한 숲과 산봉우리, 계곡","㉡ 소나 양을 기르는 목장","㉢ 바람으로 전기를 만드는 풍력 발전기","㉣ 산비탈의 밭과 약초·버섯 재배","㉤ 물을 저장하거나 전기를 만드는 댐","㉥ 스키장 · 캠핑장 · 삼림욕장"],"title":"산이 많은 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#7','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',3,'mc','auto','산이 많은 지역에서 가 보고 싶은 장소와 까닭을 알맞게 이은 것은 무엇인가요?',ARRAY['SO4-2-u3-X04']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C2","difficulty":3,"kind":"mc","stem":"산이 많은 지역에서 가 보고 싶은 장소와 까닭을 알맞게 이은 것은 무엇인가요?","options":[{"t":"삼림욕장 — 숲속에서 상쾌한 공기를 마실 수 있어서요","correct":true},{"t":"모래사장 — 모래성을 쌓을 수 있어서요","mis":"SO4-2-u3-X04"},{"t":"수산물 시장 — 생선을 살 수 있어서요","mis":"SO4-2-u3-X04"},{"t":"삼림욕장 — 바닷물에서 헤엄칠 수 있어서요","mis":"SO4-2-u3-X04"}],"explanation":["산에 있는 곳이에요.","까닭도 맞아야 해요.","삼림욕장과 숲이에요."],"asset":{"type":"passage","lines":["㉠ 울창한 숲과 산봉우리, 계곡","㉡ 소나 양을 기르는 목장","㉢ 바람으로 전기를 만드는 풍력 발전기","㉣ 산비탈의 밭과 약초·버섯 재배","㉤ 물을 저장하거나 전기를 만드는 댐","㉥ 스키장 · 캠핑장 · 삼림욕장"],"title":"산이 많은 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#8','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',4,'mc','auto','산이 많은 지역에서 볼 수 있는 모습과 일기를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X05','SO4-2-u3-X03','SO4-2-u3-X04']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C2","difficulty":4,"kind":"mc","stem":"산이 많은 지역에서 볼 수 있는 모습과 일기를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"산이 많은 지역은 숲과 산비탈 밭이 특징이고, 여가 시설이 생기며 사람들의 생활도 달라져요","correct":true},{"t":"산이 많은 지역은 옛날과 오늘날이 똑같아요","mis":"SO4-2-u3-X05"},{"t":"산이 많은 지역에는 사람들이 만든 것이 없어요","mis":"SO4-2-u3-X03"},{"t":"산이 많은 지역 사람들은 주로 고기를 잡아요","mis":"SO4-2-u3-X04"}],"explanation":["특징을 떠올려요.","변화를 떠올려요.","둘을 합쳐요."],"asset":{"type":"passage","lines":["아버지의 고향 ○○군에 다녀왔다.","아버지께서 어릴 때는 산비탈에 밭이 많았다고 하셨다.","그때는 사람들이 주로 옥수수와 감자 농사를 지었다고 한다.","지금은 큰 스키장이 생겨 관광객이 아주 많아졌다.","스키장 둘레에는 식당과 숙박 시설이 줄지어 있었다."],"title":"산골 고장에 다녀온 일기(지어낸 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#9','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',4,'mc','auto','스키장이 생긴 뒤 ○○군에 일어난 일을 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['SO4-2-u3-X05']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C2","difficulty":4,"kind":"mc","stem":"스키장이 생긴 뒤 ○○군에 일어난 일을 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"스키장이 생겨요 → 관광객이 늘어요 → 식당과 숙박 시설이 생겨요","correct":true},{"t":"식당이 생겨요 → 스키장이 생겨요 → 밭이 늘어요","mis":"SO4-2-u3-X05"},{"t":"관광객이 줄어요 → 스키장이 생겨요 → 식당이 사라져요","mis":"SO4-2-u3-X05"},{"t":"밭이 늘어요 → 관광객이 줄어요 → 스키장이 생겨요","mis":"SO4-2-u3-X05"}],"explanation":["스키장이 먼저예요.","사람이 찾아와요.","그다음 식당과 숙소예요."],"asset":{"type":"passage","lines":["아버지의 고향 ○○군에 다녀왔다.","아버지께서 어릴 때는 산비탈에 밭이 많았다고 하셨다.","그때는 사람들이 주로 옥수수와 감자 농사를 지었다고 한다.","지금은 큰 스키장이 생겨 관광객이 아주 많아졌다.","스키장 둘레에는 식당과 숙박 시설이 줄지어 있었다."],"title":"산골 고장에 다녀온 일기(지어낸 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L02_challenge#10','soc',4,2,'u3','L02','g4_2_soc_u3_L02_challenge','lesson_challenge','SO4-2-u3-C2',4,'essay','teacher','일기 속 ○○군의 옛날 모습과 지금 모습을 견주어 쓰고, 스키장이 생기면서 사람들이 하는 일이 어떻게 달라졌을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C2","difficulty":4,"kind":"essay","stem":"일기 속 ○○군의 옛날 모습과 지금 모습을 견주어 쓰고, 스키장이 생기면서 사람들이 하는 일이 어떻게 달라졌을지 쓰세요.","answer_guide":{"answer":"예: 옛날에는 산비탈에 밭이 많아 사람들이 옥수수와 감자 농사를 지었어요. 지금은 스키장이 생겨 관광객이 많아졌어요. 그래서 스키장 둘레의 식당이나 숙박 시설에서 일하는 사람이 생겼을 거예요.","scoring_points":["옛날 모습을 썼는가","지금 모습을 썼는가","하는 일의 변화를 썼는가"]},"explanation":["옛날을 써요.","지금을 써요.","변화를 써요."],"asset":{"type":"passage","lines":["아버지의 고향 ○○군에 다녀왔다.","아버지께서 어릴 때는 산비탈에 밭이 많았다고 하셨다.","그때는 사람들이 주로 옥수수와 감자 농사를 지었다고 한다.","지금은 큰 스키장이 생겨 관광객이 아주 많아졌다.","스키장 둘레에는 식당과 숙박 시설이 줄지어 있었다."],"title":"산골 고장에 다녀온 일기(지어낸 글)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#1','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',1,'mc','auto','들이 펼쳐진 지역에서 하천이나 저수지 가까이에 만든 것은 무엇인가요?',ARRAY['SO4-2-u3-X06']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C3","difficulty":1,"kind":"mc","stem":"들이 펼쳐진 지역에서 하천이나 저수지 가까이에 만든 것은 무엇인가요?","options":[{"t":"논과 밭","correct":true},{"t":"스키장","mis":"SO4-2-u3-X06"},{"t":"풍력 발전기","mis":"SO4-2-u3-X06"},{"t":"산비탈 밭","mis":"SO4-2-u3-X06"}],"explanation":["물이 가까이 있어요.","농사에 물이 필요해요.","논과 밭이에요."],"asset":{"type":"passage","lines":["하천과 저수지 가까이에 논과 밭이 펼쳐져 있어요.","논에서는 벼농사를 짓고, 비닐하우스에서는 채소와 과일을 길러요.","많은 사람이 모여 살면서 회사와 공장, 아파트, 도로가 생겼어요."],"title":"들이 펼쳐진 지역"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#2','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',1,'sa','auto','들이 펼쳐진 지역에서 비닐로 덮은 시설 안에 채소나 과일을 기르는 곳은 무엇인가요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C3","difficulty":1,"kind":"sa","stem":"들이 펼쳐진 지역에서 비닐로 덮은 시설 안에 채소나 과일을 기르는 곳은 무엇인가요? 다섯 글자로 쓰세요.","answer":["비닐하우스"],"explanation":["비닐로 덮었어요.","비닐◯◯◯예요.","비닐하우스예요."],"asset":{"type":"passage","lines":["축사 · 비닐하우스 · 공장","경기장 · 백화점 · 기차역"],"title":"들이 펼쳐진 지역 그림 속 장소"},"mis":"SO4-2-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#3','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',1,'ox','auto','들이 펼쳐진 지역은 땅이 넓고 평평해요.',ARRAY['SO4-2-u3-X06']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C3","difficulty":1,"kind":"ox","stem":"들이 펼쳐진 지역은 땅이 넓고 평평해요.","answer":"O","reason_options":[{"t":"넓은 들판이 펼쳐져 논과 밭을 만들기 좋기 때문에","correct":true},{"t":"가파른 비탈이 많기 때문에","mis":"SO4-2-u3-X06"}],"mis":"SO4-2-u3-X06","explanation":["들판을 떠올려요.","넓고 평평해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#4','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',1,'mc','auto','박물관이나 미술관 같은 곳을 무엇이라고 하나요?',ARRAY['SO4-2-u3-X07','SO4-2-u3-X06']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C3","difficulty":1,"kind":"mc","stem":"박물관이나 미술관 같은 곳을 무엇이라고 하나요?","options":[{"t":"문화 시설","correct":true},{"t":"축사","mis":"SO4-2-u3-X07"},{"t":"저수지","mis":"SO4-2-u3-X06"},{"t":"기차역","mis":"SO4-2-u3-X07"}],"explanation":["그림과 옛 물건을 봐요.","문화를 누려요.","문화 시설이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#5','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',2,'match','auto','그림 속 장소와 그곳에서 볼 수 있는 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"match","stem":"그림 속 장소와 그곳에서 볼 수 있는 모습을 알맞게 이으세요.","pairs":[{"l":"축사","r":"소나 돼지를 키워요"},{"l":"공장","r":"생활에 필요한 물건을 만들어요"},{"l":"경기장","r":"운동 경기와 관중을 볼 수 있어요"},{"l":"기차역","r":"기차를 타려는 사람들이 있어요"}],"mis":"SO4-2-u3-X07","explanation":["축사는 가축이에요.","공장은 물건이에요.","경기장과 기차역도 이어요."],"asset":{"type":"passage","lines":["축사 · 비닐하우스 · 공장","경기장 · 백화점 · 기차역"],"title":"들이 펼쳐진 지역 그림 속 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#6','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',2,'mc','auto','들이 펼쳐진 지역에 많은 사람이 모여 살면서 생겨난 것으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X06']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"mc","stem":"들이 펼쳐진 지역에 많은 사람이 모여 살면서 생겨난 것으로 알맞은 것은 무엇인가요?","options":[{"t":"회사와 공장, 아파트, 도로","correct":true},{"t":"울창한 숲과 계곡","mis":"SO4-2-u3-X06"},{"t":"갯벌과 모래사장","mis":"SO4-2-u3-X06"},{"t":"산봉우리와 산비탈","mis":"SO4-2-u3-X06"}],"explanation":["사람이 모였어요.","사람이 만든 것이 늘어요.","회사·아파트·도로예요."],"asset":{"type":"passage","lines":["하천과 저수지 가까이에 논과 밭이 펼쳐져 있어요.","논에서는 벼농사를 짓고, 비닐하우스에서는 채소와 과일을 길러요.","많은 사람이 모여 살면서 회사와 공장, 아파트, 도로가 생겼어요."],"title":"들이 펼쳐진 지역"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#7','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',2,'ox','auto','백화점이나 대형 할인점은 들이 펼쳐진 지역에서 볼 수 있는 상점이에요.',ARRAY['SO4-2-u3-X07']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"ox","stem":"백화점이나 대형 할인점은 들이 펼쳐진 지역에서 볼 수 있는 상점이에요.","answer":"O","reason_options":[{"t":"많은 사람이 모여 살면 물건을 사고파는 곳이 생기기 때문에","correct":true},{"t":"상점은 산이 많은 지역에만 있기 때문에","mis":"SO4-2-u3-X07"}],"mis":"SO4-2-u3-X07","explanation":["사람이 많아요.","물건을 사야 해요.","그래서 O예요."],"asset":{"type":"passage","lines":["축사 · 비닐하우스 · 공장","경기장 · 백화점 · 기차역"],"title":"들이 펼쳐진 지역 그림 속 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#8','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',2,'mc','auto','△△군의 요즘 지도에서 옛 지도보다 달라진 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X08']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"mc","stem":"△△군의 요즘 지도에서 옛 지도보다 달라진 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"학교가 많아지고 도로가 복잡해졌어요","correct":true},{"t":"논과 밭이 더 넓어졌어요","mis":"SO4-2-u3-X08"},{"t":"학교가 사라졌어요","mis":"SO4-2-u3-X08"},{"t":"길이 더 좁아졌어요","mis":"SO4-2-u3-X08"}],"explanation":["학교 수를 봐요.","1곳에서 4곳이에요.","도로도 복잡해요."],"asset":{"type":"passage","lines":["옛 지도 — 논과 밭이 넓어요. 학교 1곳, 좁은 길이 몇 개 있어요.","요즘 지도 — 아파트와 회사가 많아요. 학교 4곳, 도로가 복잡해요.","요즘 지도 — 백화점과 미술관도 생겼어요."],"title":"△△군의 옛 지도와 요즘 지도(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#9','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',2,'blank','auto','△△군의 요즘 지도에서 아파트가 선 자리는 옛 지도에서 주로 (    )이었어요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u3-X08']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"blank","stem":"△△군의 요즘 지도에서 아파트가 선 자리는 옛 지도에서 주로 (    )이었어요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"논과 밭","correct":true},{"t":"바다","mis":"SO4-2-u3-X08"},{"t":"높은 산","mis":"SO4-2-u3-X08"},{"t":"백화점","mis":"SO4-2-u3-X08"}],"explanation":["옛 지도를 봐요.","넓은 땅이 있었어요.","논과 밭이에요."],"asset":{"type":"passage","lines":["옛 지도 — 논과 밭이 넓어요. 학교 1곳, 좁은 길이 몇 개 있어요.","요즘 지도 — 아파트와 회사가 많아요. 학교 4곳, 도로가 복잡해요.","요즘 지도 — 백화점과 미술관도 생겼어요."],"title":"△△군의 옛 지도와 요즘 지도(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_basic#10','soc',4,2,'u3','L03','g4_2_soc_u3_L03_basic','lesson_basic','SO4-2-u3-C3',3,'mc','auto','△△군의 옛 지도와 요즘 지도를 견주어 보니, 이 지역에 사는 사람은 어떻게 되었다고 볼 수 있나요?',ARRAY['SO4-2-u3-X08']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C3","difficulty":3,"kind":"mc","stem":"△△군의 옛 지도와 요즘 지도를 견주어 보니, 이 지역에 사는 사람은 어떻게 되었다고 볼 수 있나요?","options":[{"t":"학교가 늘어났으니 사는 사람이 더 많아졌다고 볼 수 있어요","correct":true},{"t":"학교가 늘어났으니 사는 사람이 줄었어요","mis":"SO4-2-u3-X08"},{"t":"사는 사람은 알 수 없어요","mis":"SO4-2-u3-X08"},{"t":"논이 줄었으니 사람이 모두 떠났어요","mis":"SO4-2-u3-X08"}],"explanation":["학교가 1곳에서 4곳이에요.","다닐 아이가 많아요.","사람이 늘었어요."],"asset":{"type":"passage","lines":["옛 지도 — 논과 밭이 넓어요. 학교 1곳, 좁은 길이 몇 개 있어요.","요즘 지도 — 아파트와 회사가 많아요. 학교 4곳, 도로가 복잡해요.","요즘 지도 — 백화점과 미술관도 생겼어요."],"title":"△△군의 옛 지도와 요즘 지도(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#1','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',2,'mc','auto','그림 속 장소 가운데 사람들이 물건을 사고파는 곳은 어디인가요?',ARRAY['SO4-2-u3-X07','SO4-2-u3-X06']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"mc","stem":"그림 속 장소 가운데 사람들이 물건을 사고파는 곳은 어디인가요?","options":[{"t":"백화점","correct":true},{"t":"축사","mis":"SO4-2-u3-X07"},{"t":"비닐하우스","mis":"SO4-2-u3-X06"},{"t":"경기장","mis":"SO4-2-u3-X07"}],"explanation":["장소를 하나씩 봐요.","사고파는 곳이에요.","백화점이에요."],"asset":{"type":"passage","lines":["축사 · 비닐하우스 · 공장","경기장 · 백화점 · 기차역"],"title":"들이 펼쳐진 지역 그림 속 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#2','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',2,'ox','auto','들이 펼쳐진 지역의 논이 하천이나 저수지 가까이에 있는 것은 우연이에요.',ARRAY['SO4-2-u3-X06']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"ox","stem":"들이 펼쳐진 지역의 논이 하천이나 저수지 가까이에 있는 것은 우연이에요.","answer":"X","reason_options":[{"t":"벼농사에 물이 많이 필요해서 물 가까이에 만들기 때문에","correct":true},{"t":"논은 물과 관계없기 때문에","mis":"SO4-2-u3-X06"}],"mis":"SO4-2-u3-X06","explanation":["벼는 물이 필요해요.","물 가까이 만들어요.","그래서 X예요."],"asset":{"type":"passage","lines":["하천과 저수지 가까이에 논과 밭이 펼쳐져 있어요.","논에서는 벼농사를 짓고, 비닐하우스에서는 채소와 과일을 길러요.","많은 사람이 모여 살면서 회사와 공장, 아파트, 도로가 생겼어요."],"title":"들이 펼쳐진 지역"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#3','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',3,'error','auto','들이 펼쳐진 지역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X06','SO4-2-u3-X07']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C3","difficulty":3,"kind":"error","stem":"들이 펼쳐진 지역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「들이 펼쳐진 지역에서는 산비탈에 약초를 길러.」","correct":true,"mis_target":"SO4-2-u3-X06"},{"t":"친구 가 — 「논에서 벼농사를 지어.」","mis":"SO4-2-u3-X06"},{"t":"친구 나 — 「사람이 모여 살면서 아파트가 생겼어.」","mis":"SO4-2-u3-X07"}],"explanation":["들은 평평해요.","산비탈은 산이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["하천과 저수지 가까이에 논과 밭이 펼쳐져 있어요.","논에서는 벼농사를 짓고, 비닐하우스에서는 채소와 과일을 길러요.","많은 사람이 모여 살면서 회사와 공장, 아파트, 도로가 생겼어요."],"title":"들이 펼쳐진 지역"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#4','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',3,'mc','auto','장소와 그곳에서 볼 수 있는 사람들의 생활 모습을 알맞게 이은 것은 무엇인가요?',ARRAY['SO4-2-u3-X07']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C3","difficulty":3,"kind":"mc","stem":"장소와 그곳에서 볼 수 있는 사람들의 생활 모습을 알맞게 이은 것은 무엇인가요?","options":[{"t":"기차역 — 기차를 타고 다른 지역으로 여행을 가요","correct":true},{"t":"축사 — 운동 경기를 관람해요","mis":"SO4-2-u3-X07"},{"t":"백화점 — 벼농사를 지어요","mis":"SO4-2-u3-X07"},{"t":"경기장 — 소를 키워요","mis":"SO4-2-u3-X07"}],"explanation":["기차역을 봐요.","기차를 타요.","그것을 골라요."],"asset":{"type":"passage","lines":["축사 · 비닐하우스 · 공장","경기장 · 백화점 · 기차역"],"title":"들이 펼쳐진 지역 그림 속 장소"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#5','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',3,'mc','auto','△△군의 요즘 지도에서 새로 생긴 문화 시설은 무엇인가요?',ARRAY['SO4-2-u3-X08','SO4-2-u3-X07']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C3","difficulty":3,"kind":"mc","stem":"△△군의 요즘 지도에서 새로 생긴 문화 시설은 무엇인가요?","options":[{"t":"미술관","correct":true},{"t":"학교","mis":"SO4-2-u3-X08"},{"t":"백화점","mis":"SO4-2-u3-X07"},{"t":"논","mis":"SO4-2-u3-X08"}],"explanation":["셋째 줄을 봐요.","그림을 보는 곳이에요.","미술관이에요."],"asset":{"type":"passage","lines":["옛 지도 — 논과 밭이 넓어요. 학교 1곳, 좁은 길이 몇 개 있어요.","요즘 지도 — 아파트와 회사가 많아요. 학교 4곳, 도로가 복잡해요.","요즘 지도 — 백화점과 미술관도 생겼어요."],"title":"△△군의 옛 지도와 요즘 지도(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#6','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',3,'ox','auto','요즘 지도에 아파트가 생기면서 옛 지도의 논과 밭이 있던 자리는 모두 그대로 논과 밭으로 남았어요.',ARRAY['SO4-2-u3-X08']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C3","difficulty":3,"kind":"ox","stem":"요즘 지도에 아파트가 생기면서 옛 지도의 논과 밭이 있던 자리는 모두 그대로 논과 밭으로 남았어요.","answer":"X","reason_options":[{"t":"논과 밭이 있던 자리 위에 아파트와 회사가 들어섰기 때문에","correct":true},{"t":"옛 모습은 시간이 지나도 바뀌지 않기 때문에","mis":"SO4-2-u3-X08"}],"mis":"SO4-2-u3-X08","explanation":["같은 자리를 봐요.","아파트가 섰어요.","그래서 X예요."],"asset":{"type":"passage","lines":["옛 지도 — 논과 밭이 넓어요. 학교 1곳, 좁은 길이 몇 개 있어요.","요즘 지도 — 아파트와 회사가 많아요. 학교 4곳, 도로가 복잡해요.","요즘 지도 — 백화점과 미술관도 생겼어요."],"title":"△△군의 옛 지도와 요즘 지도(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#7','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',3,'mc','auto','들이 펼쳐진 지역에 사람이 많이 모여 살게 된 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X06','SO4-2-u3-X07']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C3","difficulty":3,"kind":"mc","stem":"들이 펼쳐진 지역에 사람이 많이 모여 살게 된 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"땅이 넓고 평평해 집과 도로, 회사를 짓기 좋기 때문이에요","correct":true},{"t":"가파른 비탈이 많기 때문이에요","mis":"SO4-2-u3-X06"},{"t":"갯벌이 넓기 때문이에요","mis":"SO4-2-u3-X06"},{"t":"사람이 만든 것이 하나도 없기 때문이에요","mis":"SO4-2-u3-X07"}],"explanation":["들의 땅을 떠올려요.","넓고 평평해요.","짓기 좋아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#8','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',4,'mc','auto','△△군의 옛 지도와 요즘 지도를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X08','SO4-2-u3-X01','SO4-2-u3-X07']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C3","difficulty":4,"kind":"mc","stem":"△△군의 옛 지도와 요즘 지도를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"사람이 많이 모여 살면서 논과 밭이 있던 곳에 아파트·학교·도로·상점·문화 시설이 늘었어요","correct":true},{"t":"사람이 줄면서 논과 밭이 더 넓어졌어요","mis":"SO4-2-u3-X08"},{"t":"자연환경만 바뀌고 인문환경은 그대로예요","mis":"SO4-2-u3-X01"},{"t":"달라진 것은 학교 하나뿐이에요","mis":"SO4-2-u3-X07"}],"explanation":["옛 지도를 봐요.","요즘 지도를 봐요.","늘어난 것을 모아요."],"asset":{"type":"passage","lines":["옛 지도 — 논과 밭이 넓어요. 학교 1곳, 좁은 길이 몇 개 있어요.","요즘 지도 — 아파트와 회사가 많아요. 학교 4곳, 도로가 복잡해요.","요즘 지도 — 백화점과 미술관도 생겼어요."],"title":"△△군의 옛 지도와 요즘 지도(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#9','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',4,'mc','auto','들이 펼쳐진 지역과 산이 많은 지역의 사람들이 하는 일을 바르게 견준 것은 무엇인가요?',ARRAY['SO4-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C3","difficulty":4,"kind":"mc","stem":"들이 펼쳐진 지역과 산이 많은 지역의 사람들이 하는 일을 바르게 견준 것은 무엇인가요?","options":[{"t":"들에서는 논에서 벼농사를, 산에서는 산비탈 밭에서 농사를 지어요","correct":true},{"t":"들에서는 약초를, 산에서는 벼농사를 지어요","mis":"SO4-2-u3-X06"},{"t":"두 지역 모두 고기잡이를 해요","mis":"SO4-2-u3-X06"},{"t":"두 지역 모두 농사를 짓지 않아요","mis":"SO4-2-u3-X06"}],"explanation":["들은 논이에요.","산은 산비탈 밭이에요.","둘을 견줘요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L03_challenge#10','soc',4,2,'u3','L03','g4_2_soc_u3_L03_challenge','lesson_challenge','SO4-2-u3-C3',4,'essay','teacher','△△군의 옛 지도와 요즘 지도를 견주어 달라진 점을 두 가지 쓰고, 그렇게 달라진 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C3","difficulty":4,"kind":"essay","stem":"△△군의 옛 지도와 요즘 지도를 견주어 달라진 점을 두 가지 쓰고, 그렇게 달라진 까닭을 쓰세요.","answer_guide":{"answer":"예: 옛 지도보다 요즘 지도에는 학교가 1곳에서 4곳으로 늘었고, 논과 밭이 있던 자리에 아파트와 회사가 생겼어요. 많은 사람이 모여 살게 되면서 살 곳과 일할 곳, 다닐 학교가 더 필요해졌기 때문이에요.","scoring_points":["달라진 점 두 가지를 썼는가","지도에 있는 사실로 썼는가","사람이 많이 모여 산다는 까닭을 썼는가"]},"explanation":["두 지도를 견줘요.","두 가지를 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["옛 지도 — 논과 밭이 넓어요. 학교 1곳, 좁은 길이 몇 개 있어요.","요즘 지도 — 아파트와 회사가 많아요. 학교 4곳, 도로가 복잡해요.","요즘 지도 — 백화점과 미술관도 생겼어요."],"title":"△△군의 옛 지도와 요즘 지도(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#1','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',1,'mc','auto','바다가 있는 지역에서 볼 수 있는 자연환경으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X01','SO4-2-u3-X09']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C4","difficulty":1,"kind":"mc","stem":"바다가 있는 지역에서 볼 수 있는 자연환경으로 알맞은 것은 무엇인가요?","options":[{"t":"갯벌과 모래사장","correct":true},{"t":"항구와 양식장","mis":"SO4-2-u3-X01"},{"t":"산봉우리와 계곡","mis":"SO4-2-u3-X09"},{"t":"비닐하우스와 축사","mis":"SO4-2-u3-X09"}],"explanation":["자연 그대로예요.","바닷가에 생겼어요.","갯벌과 모래사장이에요."],"asset":{"type":"passage","lines":["㉠ 갯벌과 모래사장","㉡ 배가 안전하게 드나드는 항구","㉢ 물고기나 김을 기르는 양식장","㉣ 생선을 사고파는 수산물 직판장","㉤ 놀러 온 사람들이 묵는 식당과 숙박 시설"],"title":"바다가 있는 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#2','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',1,'sa','auto','사람의 힘을 이용해 물고기나 김 등을 기르는 곳은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C4","difficulty":1,"kind":"sa","stem":"사람의 힘을 이용해 물고기나 김 등을 기르는 곳은 무엇인가요? 세 글자로 쓰세요.","answer":["양식장"],"explanation":["기르는 곳이에요.","양◯◯이에요.","양식장이에요."],"asset":{"type":"passage","lines":["㉠ 갯벌과 모래사장","㉡ 배가 안전하게 드나드는 항구","㉢ 물고기나 김을 기르는 양식장","㉣ 생선을 사고파는 수산물 직판장","㉤ 놀러 온 사람들이 묵는 식당과 숙박 시설"],"title":"바다가 있는 지역에서 볼 수 있는 모습"},"mis":"SO4-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#3','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',1,'ox','auto','항구는 배가 안전하게 드나들 수 있도록 사람들이 만든 곳이에요.',ARRAY['SO4-2-u3-X09']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C4","difficulty":1,"kind":"ox","stem":"항구는 배가 안전하게 드나들 수 있도록 사람들이 만든 곳이에요.","answer":"O","reason_options":[{"t":"배가 머물고 짐을 싣고 내리도록 만든 시설이기 때문에","correct":true},{"t":"바다가 저절로 만든 자연환경이기 때문에","mis":"SO4-2-u3-X09"}],"mis":"SO4-2-u3-X09","explanation":["배가 드나들어요.","사람들이 만들었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 갯벌과 모래사장","㉡ 배가 안전하게 드나드는 항구","㉢ 물고기나 김을 기르는 양식장","㉣ 생선을 사고파는 수산물 직판장","㉤ 놀러 온 사람들이 묵는 식당과 숙박 시설"],"title":"바다가 있는 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#4','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',1,'mc','auto','수산물 직판장에서 볼 수 있는 모습은 무엇인가요?',ARRAY['SO4-2-u3-X09','SO4-2-u3-X10']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C4","difficulty":1,"kind":"mc","stem":"수산물 직판장에서 볼 수 있는 모습은 무엇인가요?","options":[{"t":"생선을 사고팔아요","correct":true},{"t":"물고기를 바다에서 길러요","mis":"SO4-2-u3-X09"},{"t":"배가 원료를 실어 와요","mis":"SO4-2-u3-X10"},{"t":"모래성을 쌓아요","mis":"SO4-2-u3-X09"}],"explanation":["직판장은 파는 곳이에요.","수산물은 바다에서 나요.","생선을 사고팔아요."],"asset":{"type":"passage","lines":["㉠ 갯벌과 모래사장","㉡ 배가 안전하게 드나드는 항구","㉢ 물고기나 김을 기르는 양식장","㉣ 생선을 사고파는 수산물 직판장","㉤ 놀러 온 사람들이 묵는 식당과 숙박 시설"],"title":"바다가 있는 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#5','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',2,'match','auto','바다가 있는 지역의 장소와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"match","stem":"바다가 있는 지역의 장소와 하는 일을 알맞게 이으세요.","pairs":[{"l":"배","r":"바다에서 물고기를 잡아요"},{"l":"양식장","r":"물고기나 김을 길러요"},{"l":"수산물 직판장","r":"생선을 사고팔아요"},{"l":"숙박 시설","r":"놀러 온 사람이 묵어요"}],"mis":"SO4-2-u3-X09","explanation":["배는 고기잡이예요.","양식장은 기르기예요.","직판장과 숙소도 이어요."],"asset":{"type":"passage","lines":["㉠ 갯벌과 모래사장","㉡ 배가 안전하게 드나드는 항구","㉢ 물고기나 김을 기르는 양식장","㉣ 생선을 사고파는 수산물 직판장","㉤ 놀러 온 사람들이 묵는 식당과 숙박 시설"],"title":"바다가 있는 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#6','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',2,'mc','auto','원료와 제품을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-2-u3-X10']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"mc","stem":"원료와 제품을 바르게 말한 것은 무엇인가요?","options":[{"t":"원료는 물건을 만드는 재료이고, 제품은 공장에서 만든 물건이에요","correct":true},{"t":"원료는 공장에서 만든 물건이에요","mis":"SO4-2-u3-X10"},{"t":"제품은 물건을 만드는 재료예요","mis":"SO4-2-u3-X10"},{"t":"원료와 제품은 같은 뜻이에요","mis":"SO4-2-u3-X10"}],"explanation":["만들기 전이 원료예요.","만든 뒤가 제품이에요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#7','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',2,'ox','auto','△△시에 공업이 발달한 것은 바다와 가까워 배로 원료와 제품을 실어 나를 수 있기 때문이에요.',ARRAY['SO4-2-u3-X10']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"ox","stem":"△△시에 공업이 발달한 것은 바다와 가까워 배로 원료와 제품을 실어 나를 수 있기 때문이에요.","answer":"O","reason_options":[{"t":"무거운 원료와 제품을 배로 한꺼번에 나를 수 있기 때문에","correct":true},{"t":"바다에서 공장 물건이 저절로 생겨나기 때문에","mis":"SO4-2-u3-X10"}],"mis":"SO4-2-u3-X10","explanation":["넷째 줄을 읽어요.","배가 실어 날라요.","그래서 O예요."],"asset":{"type":"passage","lines":["옛날 — 사람들은 주로 고기잡이를 하거나 농사를 지었어요.","옛날 사진 — 건물이 거의 없고 좁은 도로가 보여요.","요즘 사진 — 큰 항구와 넓은 도로, 바닷가의 공장이 보여요.","배가 원료를 싣고 들어오고, 공장에서 만든 제품을 싣고 나가요."],"title":"바닷가 △△시의 옛날과 요즘(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#8','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',2,'mc','auto','△△시의 옛날 사람들이 주로 한 일은 무엇인가요?',ARRAY['SO4-2-u3-X05','SO4-2-u3-X10']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"mc","stem":"△△시의 옛날 사람들이 주로 한 일은 무엇인가요?","options":[{"t":"고기잡이를 하거나 농사를 지었어요","correct":true},{"t":"공장에서 제품을 만들었어요","mis":"SO4-2-u3-X05"},{"t":"큰 항구에서 원료를 내렸어요","mis":"SO4-2-u3-X10"},{"t":"넓은 도로에서 장사를 했어요","mis":"SO4-2-u3-X05"}],"explanation":["첫째 줄을 읽어요.","옛날 이야기예요.","고기잡이와 농사예요."],"asset":{"type":"passage","lines":["옛날 — 사람들은 주로 고기잡이를 하거나 농사를 지었어요.","옛날 사진 — 건물이 거의 없고 좁은 도로가 보여요.","요즘 사진 — 큰 항구와 넓은 도로, 바닷가의 공장이 보여요.","배가 원료를 싣고 들어오고, 공장에서 만든 제품을 싣고 나가요."],"title":"바닷가 △△시의 옛날과 요즘(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#9','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',2,'blank','auto','△△시의 요즘 사진에는 큰 항구와 넓은 도로, 바닷가의 (    )이 보여요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u3-X04','SO4-2-u3-X09','SO4-2-u3-X06']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"blank","stem":"△△시의 요즘 사진에는 큰 항구와 넓은 도로, 바닷가의 (    )이 보여요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"공장","correct":true},{"t":"산비탈 밭","mis":"SO4-2-u3-X04"},{"t":"계곡","mis":"SO4-2-u3-X09"},{"t":"축사","mis":"SO4-2-u3-X06"}],"explanation":["셋째 줄을 읽어요.","제품을 만드는 곳이에요.","공장이에요."],"asset":{"type":"passage","lines":["옛날 — 사람들은 주로 고기잡이를 하거나 농사를 지었어요.","옛날 사진 — 건물이 거의 없고 좁은 도로가 보여요.","요즘 사진 — 큰 항구와 넓은 도로, 바닷가의 공장이 보여요.","배가 원료를 싣고 들어오고, 공장에서 만든 제품을 싣고 나가요."],"title":"바닷가 △△시의 옛날과 요즘(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_basic#10','soc',4,2,'u3','L04','g4_2_soc_u3_L04_basic','lesson_basic','SO4-2-u3-C4',3,'mc','auto','△△시에 공업이 발달하면서 나타났을 변화로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X05','SO4-2-u3-X10']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C4","difficulty":3,"kind":"mc","stem":"△△시에 공업이 발달하면서 나타났을 변화로 가장 알맞은 것은 무엇인가요?","options":[{"t":"공장에서 일하는 사람이 생기고 사는 사람도 늘어났을 거예요","correct":true},{"t":"사는 사람이 모두 떠났을 거예요","mis":"SO4-2-u3-X05"},{"t":"고기잡이하는 사람만 늘었을 거예요","mis":"SO4-2-u3-X10"},{"t":"도로가 더 좁아졌을 거예요","mis":"SO4-2-u3-X05"}],"explanation":["공장이 생겼어요.","일할 사람이 필요해요.","사는 사람이 늘어요."],"asset":{"type":"passage","lines":["옛날 — 사람들은 주로 고기잡이를 하거나 농사를 지었어요.","옛날 사진 — 건물이 거의 없고 좁은 도로가 보여요.","요즘 사진 — 큰 항구와 넓은 도로, 바닷가의 공장이 보여요.","배가 원료를 싣고 들어오고, 공장에서 만든 제품을 싣고 나가요."],"title":"바닷가 △△시의 옛날과 요즘(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#1','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',2,'mc','auto','바다가 있는 지역에서 볼 수 있는 모습 가운데 자연환경은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"mc","stem":"바다가 있는 지역에서 볼 수 있는 모습 가운데 자연환경은 무엇인가요?","options":[{"t":"㉠","correct":true},{"t":"㉡","mis":"SO4-2-u3-X01"},{"t":"㉢","mis":"SO4-2-u3-X01"},{"t":"㉣","mis":"SO4-2-u3-X01"}],"explanation":["사람이 만들지 않았어요.","갯벌과 모래사장이에요.","㉠이에요."],"asset":{"type":"passage","lines":["㉠ 갯벌과 모래사장","㉡ 배가 안전하게 드나드는 항구","㉢ 물고기나 김을 기르는 양식장","㉣ 생선을 사고파는 수산물 직판장","㉤ 놀러 온 사람들이 묵는 식당과 숙박 시설"],"title":"바다가 있는 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#2','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',2,'ox','auto','양식장에서 일하는 것과 배를 타고 바다에서 물고기를 잡는 것은 같은 일이에요.',ARRAY['SO4-2-u3-X09']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"ox","stem":"양식장에서 일하는 것과 배를 타고 바다에서 물고기를 잡는 것은 같은 일이에요.","answer":"X","reason_options":[{"t":"양식장은 기르는 일이고 고기잡이는 바다에 사는 것을 잡는 일이기 때문에","correct":true},{"t":"바다에서 하는 일은 모두 같기 때문에","mis":"SO4-2-u3-X09"}],"mis":"SO4-2-u3-X09","explanation":["기르나요, 잡나요?","서로 달라요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 갯벌과 모래사장","㉡ 배가 안전하게 드나드는 항구","㉢ 물고기나 김을 기르는 양식장","㉣ 생선을 사고파는 수산물 직판장","㉤ 놀러 온 사람들이 묵는 식당과 숙박 시설"],"title":"바다가 있는 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#3','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',3,'error','auto','△△시를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X10','SO4-2-u3-X05']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C4","difficulty":3,"kind":"error","stem":"△△시를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「배는 공장에서 만든 원료를 싣고 나가.」","correct":true,"mis_target":"SO4-2-u3-X10"},{"t":"친구 가 — 「옛날에는 고기잡이와 농사를 했어.」","mis":"SO4-2-u3-X05"},{"t":"친구 다 — 「요즘은 바닷가에 공장이 있어.」","mis":"SO4-2-u3-X10"}],"explanation":["공장에서 만든 것은요?","제품이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["옛날 — 사람들은 주로 고기잡이를 하거나 농사를 지었어요.","옛날 사진 — 건물이 거의 없고 좁은 도로가 보여요.","요즘 사진 — 큰 항구와 넓은 도로, 바닷가의 공장이 보여요.","배가 원료를 싣고 들어오고, 공장에서 만든 제품을 싣고 나가요."],"title":"바닷가 △△시의 옛날과 요즘(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#4','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',3,'mc','auto','바닷가 공장이 제품을 만들 수 있는 때는 언제인가요?',ARRAY['SO4-2-u3-X10','SO4-2-u3-X09']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C4","difficulty":3,"kind":"mc","stem":"바닷가 공장이 제품을 만들 수 있는 때는 언제인가요?","options":[{"t":"배가 실어 온 원료가 있을 때","correct":true},{"t":"배가 제품을 싣고 나간 뒤 아무 때나","mis":"SO4-2-u3-X10"},{"t":"원료가 하나도 없을 때","mis":"SO4-2-u3-X10"},{"t":"모래사장에 사람이 많을 때","mis":"SO4-2-u3-X09"}],"explanation":["재료가 있어야 해요.","원료는 배로 와요.","원료가 있을 때예요."],"asset":{"type":"passage","lines":["옛날 — 사람들은 주로 고기잡이를 하거나 농사를 지었어요.","옛날 사진 — 건물이 거의 없고 좁은 도로가 보여요.","요즘 사진 — 큰 항구와 넓은 도로, 바닷가의 공장이 보여요.","배가 원료를 싣고 들어오고, 공장에서 만든 제품을 싣고 나가요."],"title":"바닷가 △△시의 옛날과 요즘(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#5','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',3,'mc','auto','해양 생태 연구원이 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X10','SO4-2-u3-X09','SO4-2-u3-X04']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C4","difficulty":3,"kind":"mc","stem":"해양 생태 연구원이 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"바닷속 생물의 종류와 수, 먹이를 조사해요","correct":true},{"t":"항구에서 원료를 내려요","mis":"SO4-2-u3-X10"},{"t":"수산물 직판장에서 생선을 팔아요","mis":"SO4-2-u3-X09"},{"t":"산비탈에서 약초를 길러요","mis":"SO4-2-u3-X04"}],"explanation":["첫째 줄을 읽어요.","바닷속에 들어가요.","생물을 조사해요."],"asset":{"type":"passage","lines":["깊은 바닷속에 들어가 생물의 종류와 수, 먹이를 조사해요.","바다 환경이 바뀌면 생물이 사는 모습이 어떻게 바뀌는지 연구해요.","바다 생물과 바다 환경에 관심을 갖고 끊임없이 탐구해요."],"title":"해양 생태 연구원이 하는 일"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#6','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',3,'ox','auto','바닷가 식당이나 숙박 시설에서 일하는 사람도 바다가 있는 지역 사람들이 하는 일 가운데 하나예요.',ARRAY['SO4-2-u3-X09']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C4","difficulty":3,"kind":"ox","stem":"바닷가 식당이나 숙박 시설에서 일하는 사람도 바다가 있는 지역 사람들이 하는 일 가운데 하나예요.","answer":"O","reason_options":[{"t":"바닷가에 놀러 오는 사람들이 이용하는 곳에서 일하기 때문에","correct":true},{"t":"바다와 관련 있는 일은 고기잡이 하나뿐이기 때문에","mis":"SO4-2-u3-X09"}],"mis":"SO4-2-u3-X09","explanation":["㉤을 봐요.","놀러 오는 사람이 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 갯벌과 모래사장","㉡ 배가 안전하게 드나드는 항구","㉢ 물고기나 김을 기르는 양식장","㉣ 생선을 사고파는 수산물 직판장","㉤ 놀러 온 사람들이 묵는 식당과 숙박 시설"],"title":"바다가 있는 지역에서 볼 수 있는 모습"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#7','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',3,'mc','auto','△△시의 옛날 사진과 요즘 사진의 차이로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X05','SO4-2-u3-X12']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C4","difficulty":3,"kind":"mc","stem":"△△시의 옛날 사진과 요즘 사진의 차이로 알맞은 것은 무엇인가요?","options":[{"t":"좁은 도로가 넓어지고, 큰 항구와 공장이 생겼어요","correct":true},{"t":"공장이 사라지고 좁은 도로가 생겼어요","mis":"SO4-2-u3-X05"},{"t":"달라진 것이 없어요","mis":"SO4-2-u3-X05"},{"t":"갯벌이 산으로 바뀌었어요","mis":"SO4-2-u3-X12"}],"explanation":["옛날 사진을 봐요.","요즘 사진을 봐요.","넓어지고 생겼어요."],"asset":{"type":"passage","lines":["옛날 — 사람들은 주로 고기잡이를 하거나 농사를 지었어요.","옛날 사진 — 건물이 거의 없고 좁은 도로가 보여요.","요즘 사진 — 큰 항구와 넓은 도로, 바닷가의 공장이 보여요.","배가 원료를 싣고 들어오고, 공장에서 만든 제품을 싣고 나가요."],"title":"바닷가 △△시의 옛날과 요즘(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#8','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',4,'mc','auto','바다가 있는 지역에서 볼 수 있는 모습과 △△시를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X09','SO4-2-u3-X10']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C4","difficulty":4,"kind":"mc","stem":"바다가 있는 지역에서 볼 수 있는 모습과 △△시를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"바다를 이용해 물고기를 잡거나 기르고, 배로 원료와 제품을 나르며 공업이 발달하기도 해요","correct":true},{"t":"바다가 있는 지역 사람들은 바다와 관계없는 일만 해요","mis":"SO4-2-u3-X09"},{"t":"바닷가에는 공장이 생길 수 없어요","mis":"SO4-2-u3-X10"},{"t":"원료는 공장에서 만들어 배로 실어 와요","mis":"SO4-2-u3-X10"}],"explanation":["하는 일을 봐요.","공업도 봐요.","둘을 합쳐요."],"asset":{"type":"passage","lines":["옛날 — 사람들은 주로 고기잡이를 하거나 농사를 지었어요.","옛날 사진 — 건물이 거의 없고 좁은 도로가 보여요.","요즘 사진 — 큰 항구와 넓은 도로, 바닷가의 공장이 보여요.","배가 원료를 싣고 들어오고, 공장에서 만든 제품을 싣고 나가요."],"title":"바닷가 △△시의 옛날과 요즘(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#9','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',4,'mc','auto','산이 많은 지역, 들이 펼쳐진 지역, 바다가 있는 지역의 모습을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO4-2-u3-X04','SO4-2-u3-X06','SO4-2-u3-X09']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C4","difficulty":4,"kind":"mc","stem":"산이 많은 지역, 들이 펼쳐진 지역, 바다가 있는 지역의 모습을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"목장과 풍력 발전기 / 논과 비닐하우스 / 항구와 양식장","correct":true},{"t":"항구와 양식장 / 목장과 풍력 발전기 / 논과 비닐하우스","mis":"SO4-2-u3-X04"},{"t":"논과 비닐하우스 / 항구와 양식장 / 목장과 풍력 발전기","mis":"SO4-2-u3-X06"},{"t":"양식장과 논 / 항구와 목장 / 비닐하우스와 풍력 발전기","mis":"SO4-2-u3-X09"}],"explanation":["산·들·바다 차례예요.","하나씩 맞춰요.","첫째 것이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L04_challenge#10','soc',4,2,'u3','L04','g4_2_soc_u3_L04_challenge','lesson_challenge','SO4-2-u3-C4',4,'essay','teacher','△△시에 공업이 발달한 까닭을 원료와 제품이라는 낱말을 넣어 쓰고, 공업이 발달하면서 사람들의 생활이 어떻게 달라졌을지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C4","difficulty":4,"kind":"essay","stem":"△△시에 공업이 발달한 까닭을 원료와 제품이라는 낱말을 넣어 쓰고, 공업이 발달하면서 사람들의 생활이 어떻게 달라졌을지 쓰세요.","answer_guide":{"answer":"예: △△시는 바다와 가까워 배로 원료를 실어 오고 공장에서 만든 제품을 실어 보낼 수 있어서 공업이 발달했어요. 그래서 옛날에는 고기잡이와 농사를 하던 사람들 가운데 공장에서 일하는 사람이 생겼고, 일자리를 찾아 사는 사람도 늘었을 거예요.","scoring_points":["원료와 제품을 넣어 까닭을 썼는가","배로 실어 나른다는 점을 썼는가","생활의 변화를 썼는가"]},"explanation":["까닭을 써요.","두 낱말을 넣어요.","변화를 써요."],"asset":{"type":"passage","lines":["옛날 — 사람들은 주로 고기잡이를 하거나 농사를 지었어요.","옛날 사진 — 건물이 거의 없고 좁은 도로가 보여요.","요즘 사진 — 큰 항구와 넓은 도로, 바닷가의 공장이 보여요.","배가 원료를 싣고 들어오고, 공장에서 만든 제품을 싣고 나가요."],"title":"바닷가 △△시의 옛날과 요즘(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#1','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',1,'mc','auto','바다의 일부나 갯벌을 새로운 땅으로 만드는 일을 무엇이라고 하나요?',ARRAY['SO4-2-u3-X12','SO4-2-u3-X14']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C5","difficulty":1,"kind":"mc","stem":"바다의 일부나 갯벌을 새로운 땅으로 만드는 일을 무엇이라고 하나요?","options":[{"t":"간척","correct":true},{"t":"양식","mis":"SO4-2-u3-X12"},{"t":"개간","mis":"SO4-2-u3-X12"},{"t":"휴식년제","mis":"SO4-2-u3-X14"}],"explanation":["바다를 땅으로 바꿔요.","간◯이에요.","간척이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#2','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',1,'sa','auto','야생 동물이 자유롭게 이동하도록 도로나 철도 위에 다리를 놓거나 굴을 파서 마련한 길은 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C5","difficulty":1,"kind":"sa","stem":"야생 동물이 자유롭게 이동하도록 도로나 철도 위에 다리를 놓거나 굴을 파서 마련한 길은 무엇인가요? 네 글자로 쓰세요.","answer":["생태 통로","생태통로"],"explanation":["동물이 지나는 길이에요.","생태 ◯◯예요.","생태 통로예요."],"asset":{"type":"passage","lines":["㉮ 생태 통로 — 도로가 야생 동물이 사는 곳을 가로지른 곳에 만들어요.","㉯ 생태 하천 — 오염된 하천을 생물이 잘 사는 하천으로 되살려요.","㉰ 자연 휴식년제 — 일정 기간 사람이 들어가지 못하게 막아요."],"title":"인간과 환경의 조화를 이루려는 노력"},"mis":"SO4-2-u3-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#3','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',1,'ox','auto','사람들은 필요에 따라 환경을 이용하고 개발해요.',ARRAY['SO4-2-u3-X11']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C5","difficulty":1,"kind":"ox","stem":"사람들은 필요에 따라 환경을 이용하고 개발해요.","answer":"O","reason_options":[{"t":"살기 편하게 하거나 여가를 즐기려고 환경을 바꾸어 쓰기 때문에","correct":true},{"t":"환경은 사람이 바꿀 수 없기 때문에","mis":"SO4-2-u3-X11"}],"mis":"SO4-2-u3-X11","explanation":["스키장도 간척도 있어요.","필요해서 했어요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#4','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',1,'mc','auto','산이 많은 지역에서 환경을 이용하고 개발한 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X12']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C5","difficulty":1,"kind":"mc","stem":"산이 많은 지역에서 환경을 이용하고 개발한 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"스키장이나 케이블카를 만들어 여가 활동을 즐겨요","correct":true},{"t":"갯벌을 메워 공업 단지를 만들어요","mis":"SO4-2-u3-X12"},{"t":"넓은 들에 고속철도를 놓아요","mis":"SO4-2-u3-X12"},{"t":"바다에 양식장을 만들어요","mis":"SO4-2-u3-X12"}],"explanation":["산을 떠올려요.","여가 시설이에요.","스키장과 케이블카예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#5','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',2,'match','auto','지역과 그 지역에서 환경을 이용하고 개발한 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"match","stem":"지역과 그 지역에서 환경을 이용하고 개발한 모습을 알맞게 이으세요.","pairs":[{"l":"산이 많은 지역","r":"스키장과 케이블카"},{"l":"들이 펼쳐진 지역","r":"도로와 철도"},{"l":"바다가 있는 지역","r":"간척으로 만든 공업 단지"}],"mis":"SO4-2-u3-X12","explanation":["산은 여가 시설이에요.","들은 교통이에요.","바다는 간척이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#6','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',2,'mc','auto','들이 펼쳐진 지역에 도로와 철도가 생겨 교통이 발달하면 좋은 점은 무엇인가요?',ARRAY['SO4-2-u3-X11']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"mc","stem":"들이 펼쳐진 지역에 도로와 철도가 생겨 교통이 발달하면 좋은 점은 무엇인가요?","options":[{"t":"지역 간 이동 시간이 줄고 교류가 활발해져 생활이 편리해져요","correct":true},{"t":"자동차 소음이 줄어요","mis":"SO4-2-u3-X11"},{"t":"다른 지역에 가기 더 어려워져요","mis":"SO4-2-u3-X11"},{"t":"공기가 저절로 맑아져요","mis":"SO4-2-u3-X11"}],"explanation":["길이 빨라졌어요.","오가기 쉬워요.","생활이 편리해요."],"asset":{"type":"passage","lines":["옛날 지도 — 논과 밭 사이로 좁은 길이 나 있어요.","요즘 지도 — 고속철도와 지하철도, 역이 생겼어요.","요즘 지도 — 백화점과 버스 터미널도 생겼어요."],"title":"들이 펼쳐진 □□시의 옛날 지도와 요즘 지도(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#7','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',2,'ox','auto','교통이 발달한 들이 펼쳐진 지역에는 좋은 점만 생겨요.',ARRAY['SO4-2-u3-X11']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"ox","stem":"교통이 발달한 들이 펼쳐진 지역에는 좋은 점만 생겨요.","answer":"X","reason_options":[{"t":"교통량이 늘어 교통 체증과 대기 오염, 소음 문제가 생기기도 하기 때문에","correct":true},{"t":"교통이 발달하면 어떤 문제도 생기지 않기 때문에","mis":"SO4-2-u3-X11"}],"mis":"SO4-2-u3-X11","explanation":["자동차가 늘어요.","막히고 시끄러워요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#8','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',2,'mc','auto','○○군 골프장 기사에서 예상되는 문제점은 무엇인가요?',ARRAY['SO4-2-u3-X11']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"mc","stem":"○○군 골프장 기사에서 예상되는 문제점은 무엇인가요?","options":[{"t":"산이 훼손되어 환경 오염이 일어날 거예요","correct":true},{"t":"관광객이 늘어날 거예요","mis":"SO4-2-u3-X11"},{"t":"지역의 경제가 살아날 거예요","mis":"SO4-2-u3-X11"},{"t":"아무 문제도 없을 거예요","mis":"SO4-2-u3-X11"}],"explanation":["반대 쪽 줄을 봐요.","산이 훼손돼요.","환경 오염이에요."],"asset":{"type":"passage","lines":["○○군이 산에 골프장을 만들려고 해요.","찬성 — 관광객이 늘어 지역의 경제가 살아날 거예요.","반대 — 산이 훼손되어 환경 오염이 일어날 거예요."],"title":"○○군 골프장 기사(지어낸 기사)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#9','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',2,'blank','auto','산이 많은 지역에서 개발로 삼림이 훼손되면 (    )가 발생할 위험이 커져요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u3-X12','SO4-2-u3-X11']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"blank","stem":"산이 많은 지역에서 개발로 삼림이 훼손되면 (    )가 발생할 위험이 커져요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"산사태","correct":true},{"t":"간척","mis":"SO4-2-u3-X12"},{"t":"교통 체증","mis":"SO4-2-u3-X12"},{"t":"풍년","mis":"SO4-2-u3-X11"}],"explanation":["나무가 사라져요.","흙이 무너져요.","산사태예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_basic#10','soc',4,2,'u3','L05','g4_2_soc_u3_L05_basic','lesson_basic','SO4-2-u3-C5',3,'mc','auto','□□호 이야기의 ②와 ③을 함께 보고 알 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u3-X11','SO4-2-u3-X12']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"mc","stem":"□□호 이야기의 ②와 ③을 함께 보고 알 수 있는 것은 무엇인가요?","options":[{"t":"간척으로 공장이 생겨 경제는 발전했지만 폐수로 환경 오염이 일어났어요","correct":true},{"t":"간척으로 좋은 점만 생겼어요","mis":"SO4-2-u3-X11"},{"t":"간척으로 문제점만 생겼어요","mis":"SO4-2-u3-X11"},{"t":"간척은 산이 많은 지역에서 하는 일이에요","mis":"SO4-2-u3-X12"}],"explanation":["②는 좋은 점이에요.","③은 문제점이에요.","함께 생겼어요."],"asset":{"type":"passage","lines":["① 간척 이전 — 주민들이 갯벌에서 조개와 낙지를 잡았어요.","② 간척 이후 — 넓은 땅에 공장이 생겨 일하는 주민이 생겼어요.","③ 그 뒤 — 공장에서 흘러내린 폐수로 물이 오염되었어요.","④ 오늘날 — 오염을 줄이는 노력으로 떠났던 생물이 돌아와요."],"title":"바닷가 □□호 이야기 네 장면(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#1','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',2,'mc','auto','자연환경이 원래 모습을 되찾을 수 있도록 일정 기간 사람의 출입을 막는 제도는 무엇인가요?',ARRAY['SO4-2-u3-X14','SO4-2-u3-X12']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"mc","stem":"자연환경이 원래 모습을 되찾을 수 있도록 일정 기간 사람의 출입을 막는 제도는 무엇인가요?","options":[{"t":"자연 휴식년제","correct":true},{"t":"생태 통로","mis":"SO4-2-u3-X14"},{"t":"생태 하천","mis":"SO4-2-u3-X14"},{"t":"간척","mis":"SO4-2-u3-X12"}],"explanation":["㉰를 봐요.","쉬는 기간을 줘요.","자연 휴식년제예요."],"asset":{"type":"passage","lines":["㉮ 생태 통로 — 도로가 야생 동물이 사는 곳을 가로지른 곳에 만들어요.","㉯ 생태 하천 — 오염된 하천을 생물이 잘 사는 하천으로 되살려요.","㉰ 자연 휴식년제 — 일정 기간 사람이 들어가지 못하게 막아요."],"title":"인간과 환경의 조화를 이루려는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#2','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',2,'ox','auto','□□호 이야기의 ④는 인간과 환경의 조화를 이루려는 노력이 효과를 낸 모습이에요.',ARRAY['SO4-2-u3-X14']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"ox","stem":"□□호 이야기의 ④는 인간과 환경의 조화를 이루려는 노력이 효과를 낸 모습이에요.","answer":"O","reason_options":[{"t":"오염을 줄이는 노력으로 떠났던 생물이 다시 찾아오기 때문에","correct":true},{"t":"공장을 더 많이 세웠기 때문에","mis":"SO4-2-u3-X14"}],"mis":"SO4-2-u3-X14","explanation":["④를 읽어요.","생물이 돌아와요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 간척 이전 — 주민들이 갯벌에서 조개와 낙지를 잡았어요.","② 간척 이후 — 넓은 땅에 공장이 생겨 일하는 주민이 생겼어요.","③ 그 뒤 — 공장에서 흘러내린 폐수로 물이 오염되었어요.","④ 오늘날 — 오염을 줄이는 노력으로 떠났던 생물이 돌아와요."],"title":"바닷가 □□호 이야기 네 장면(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#3','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',3,'error','auto','환경의 이용과 개발을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X13','SO4-2-u3-X11','SO4-2-u3-X14']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"error","stem":"환경의 이용과 개발을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「좋은 점만 남기고 문제점만 쏙 빼면 돼.」","correct":true,"mis_target":"SO4-2-u3-X13"},{"t":"친구 가 — 「개발하면 좋은 점과 문제점이 함께 생겨.」","mis":"SO4-2-u3-X11"},{"t":"친구 나 — 「생태 통로로 동물의 길을 지켜.」","mis":"SO4-2-u3-X14"}],"explanation":["하나만 뺄 수 있을까요?","함께 생겨요.","친구 다가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#4','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',3,'mc','auto','개발로 생긴 문제를 줄이는 방법으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X13','SO4-2-u3-X11','SO4-2-u3-X14']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"mc","stem":"개발로 생긴 문제를 줄이는 방법으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"개발은 이어 가면서 인간과 환경의 조화를 이루는 노력을 해요","correct":true},{"t":"모든 개발을 개발 전으로 되돌려요","mis":"SO4-2-u3-X13"},{"t":"문제가 생겨도 그냥 두어요","mis":"SO4-2-u3-X11"},{"t":"개발을 더 빨리 많이 해요","mis":"SO4-2-u3-X14"}],"explanation":["되돌리면 좋은 점도 사라져요.","그냥 두면 안 돼요.","조화를 이뤄요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#5','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',3,'mc','auto','오염된 하천을 다양한 하천 생물이 잘 사는 하천으로 되살리는 노력은 무엇인가요?',ARRAY['SO4-2-u3-X14','SO4-2-u3-X12']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"mc","stem":"오염된 하천을 다양한 하천 생물이 잘 사는 하천으로 되살리는 노력은 무엇인가요?","options":[{"t":"생태 하천 만들기","correct":true},{"t":"자연 휴식년제","mis":"SO4-2-u3-X14"},{"t":"생태 통로 만들기","mis":"SO4-2-u3-X14"},{"t":"간척하기","mis":"SO4-2-u3-X12"}],"explanation":["㉯를 봐요.","하천을 되살려요.","생태 하천이에요."],"asset":{"type":"passage","lines":["㉮ 생태 통로 — 도로가 야생 동물이 사는 곳을 가로지른 곳에 만들어요.","㉯ 생태 하천 — 오염된 하천을 생물이 잘 사는 하천으로 되살려요.","㉰ 자연 휴식년제 — 일정 기간 사람이 들어가지 못하게 막아요."],"title":"인간과 환경의 조화를 이루려는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#6','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',3,'ox','auto','○○군 골프장 개발에 찬성하는 사람도 환경 오염을 줄이는 방법을 함께 생각할 수 있어요.',ARRAY['SO4-2-u3-X15']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"ox","stem":"○○군 골프장 개발에 찬성하는 사람도 환경 오염을 줄이는 방법을 함께 생각할 수 있어요.","answer":"O","reason_options":[{"t":"좋은 점과 문제점을 함께 따져 의견을 낼 수 있기 때문에","correct":true},{"t":"찬성하면 문제점은 생각하지 않아도 되기 때문에","mis":"SO4-2-u3-X15"}],"mis":"SO4-2-u3-X15","explanation":["찬성 쪽 의견이에요.","문제점도 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["○○군이 산에 골프장을 만들려고 해요.","찬성 — 관광객이 늘어 지역의 경제가 살아날 거예요.","반대 — 산이 훼손되어 환경 오염이 일어날 거예요."],"title":"○○군 골프장 기사(지어낸 기사)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#7','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',3,'mc','auto','□□시의 요즘 지도에서 옛날 지도에는 없던 교통로와 교통 시설은 무엇인가요?',ARRAY['SO4-2-u3-X12']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"mc","stem":"□□시의 요즘 지도에서 옛날 지도에는 없던 교통로와 교통 시설은 무엇인가요?","options":[{"t":"고속철도와 지하철도, 역","correct":true},{"t":"논과 밭 사이 좁은 길","mis":"SO4-2-u3-X12"},{"t":"갯벌과 양식장","mis":"SO4-2-u3-X12"},{"t":"스키장과 케이블카","mis":"SO4-2-u3-X12"}],"explanation":["둘째 줄을 읽어요.","새로 생겼어요.","고속철도와 역이에요."],"asset":{"type":"passage","lines":["옛날 지도 — 논과 밭 사이로 좁은 길이 나 있어요.","요즘 지도 — 고속철도와 지하철도, 역이 생겼어요.","요즘 지도 — 백화점과 버스 터미널도 생겼어요."],"title":"들이 펼쳐진 □□시의 옛날 지도와 요즘 지도(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#8','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',4,'mc','auto','□□호 이야기 네 장면을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X11','SO4-2-u3-X13']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C5","difficulty":4,"kind":"mc","stem":"□□호 이야기 네 장면을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"개발은 좋은 점과 문제점을 함께 가져오고, 사람들의 노력으로 환경을 되살릴 수 있어요","correct":true},{"t":"간척하면 갯벌 생물이 더 많아져요","mis":"SO4-2-u3-X11"},{"t":"한 번 오염된 곳은 되살릴 수 없어요","mis":"SO4-2-u3-X13"},{"t":"개발에는 문제점이 하나도 없어요","mis":"SO4-2-u3-X11"}],"explanation":["②③은 영향이에요.","④는 노력이에요.","함께 보아요."],"asset":{"type":"passage","lines":["① 간척 이전 — 주민들이 갯벌에서 조개와 낙지를 잡았어요.","② 간척 이후 — 넓은 땅에 공장이 생겨 일하는 주민이 생겼어요.","③ 그 뒤 — 공장에서 흘러내린 폐수로 물이 오염되었어요.","④ 오늘날 — 오염을 줄이는 노력으로 떠났던 생물이 돌아와요."],"title":"바닷가 □□호 이야기 네 장면(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#9','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',4,'mc','auto','조화를 이루려는 노력 ㉮~㉰의 같은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X14']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C5","difficulty":4,"kind":"mc","stem":"조화를 이루려는 노력 ㉮~㉰의 같은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"이용과 개발로 생긴 문제를 줄여 사람과 자연이 함께 살게 해요","correct":true},{"t":"셋 모두 새 땅을 만드는 일이에요","mis":"SO4-2-u3-X14"},{"t":"셋 모두 개발을 더 늘리는 일이에요","mis":"SO4-2-u3-X14"},{"t":"셋 모두 사람의 출입을 막는 제도예요","mis":"SO4-2-u3-X14"}],"explanation":["㉮는 동물의 길이에요.","㉯㉰도 자연을 지켜요.","조화가 같아요."],"asset":{"type":"passage","lines":["㉮ 생태 통로 — 도로가 야생 동물이 사는 곳을 가로지른 곳에 만들어요.","㉯ 생태 하천 — 오염된 하천을 생물이 잘 사는 하천으로 되살려요.","㉰ 자연 휴식년제 — 일정 기간 사람이 들어가지 못하게 막아요."],"title":"인간과 환경의 조화를 이루려는 노력"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L05_challenge#10','soc',4,2,'u3','L05','g4_2_soc_u3_L05_challenge','lesson_challenge','SO4-2-u3-C5',4,'essay','teacher','○○군 골프장 개발에 대한 내 의견을 찬성이나 반대 가운데 하나로 쓰고, 좋은 점과 문제점을 모두 따져 까닭을 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C5","difficulty":4,"kind":"essay","stem":"○○군 골프장 개발에 대한 내 의견을 찬성이나 반대 가운데 하나로 쓰고, 좋은 점과 문제점을 모두 따져 까닭을 쓰세요.","answer_guide":{"answer":"예: 저는 반대해요. 관광객이 늘어 지역 경제에 도움이 될 수는 있지만, 산이 훼손되면 동식물이 사는 곳이 사라지고 산사태 위험도 커지기 때문이에요. 꼭 개발한다면 숲을 덜 해치는 방법을 찾아야 해요.","scoring_points":["찬성이나 반대를 분명히 썼는가","좋은 점과 문제점을 모두 따졌는가","까닭을 썼는가"]},"explanation":["의견을 정해요.","둘 다 따져요.","까닭을 써요."],"asset":{"type":"passage","lines":["○○군이 산에 골프장을 만들려고 해요.","찬성 — 관광객이 늘어 지역의 경제가 살아날 거예요.","반대 — 산이 훼손되어 환경 오염이 일어날 거예요."],"title":"○○군 골프장 기사(지어낸 기사)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#1','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',1,'mc','auto','산이나 바다처럼 자연 그대로 생겨난 환경을 무엇이라고 하나요? (주제 정리)',ARRAY['SO4-2-u3-X17']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C6","difficulty":1,"kind":"mc","stem":"산이나 바다처럼 자연 그대로 생겨난 환경을 무엇이라고 하나요? (주제 정리)","options":[{"t":"자연환경","correct":true},{"t":"인문환경","mis":"SO4-2-u3-X17"},{"t":"교통","mis":"SO4-2-u3-X17"},{"t":"생태 통로","mis":"SO4-2-u3-X17"}],"explanation":["자연 그대로예요.","사람이 만들지 않았어요.","자연환경이에요."],"asset":{"type":"passage","lines":["가로 ① 자연 그대로 생겨난 환경","가로 ② 산의 바위나 흙이 갑자기 무너져 내리는 일","세로 ③ 야생 동물이 다니도록 마련한 길","세로 ④ 일정 기간 사람의 출입을 막는 제도"],"title":"낱말 퍼즐 문제(줄여 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#2','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',1,'sa','auto','산에 있던 바위나 흙이 갑자기 무너져 내리는 일을 무엇이라고 하나요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C6","difficulty":1,"kind":"sa","stem":"산에 있던 바위나 흙이 갑자기 무너져 내리는 일을 무엇이라고 하나요? 세 글자로 쓰세요.","answer":["산사태"],"explanation":["산에서 일어나요.","산◯◯예요.","산사태예요."],"asset":{"type":"passage","lines":["가로 ① 자연 그대로 생겨난 환경","가로 ② 산의 바위나 흙이 갑자기 무너져 내리는 일","세로 ③ 야생 동물이 다니도록 마련한 길","세로 ④ 일정 기간 사람의 출입을 막는 제도"],"title":"낱말 퍼즐 문제(줄여 옮김)"},"mis":"SO4-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#3','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',1,'ox','auto','「지역의 환경과 변화」에서 공부한 내용은 그림, 편지, 낱말 퍼즐처럼 여러 방법으로 정리할 수 있어요.',ARRAY['SO4-2-u3-X16']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C6","difficulty":1,"kind":"ox","stem":"「지역의 환경과 변화」에서 공부한 내용은 그림, 편지, 낱말 퍼즐처럼 여러 방법으로 정리할 수 있어요.","answer":"O","reason_options":[{"t":"정리하는 방법은 하나가 아니기 때문에","correct":true},{"t":"정리는 글로만 해야 하기 때문에","mis":"SO4-2-u3-X16"}],"mis":"SO4-2-u3-X16","explanation":["방법을 떠올려요.","그림·편지·퍼즐이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#4','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',1,'mc','auto','들이 펼쳐진 지역에 도로와 철도가 생겨나면 무엇이 발달하나요? (주제 정리)',ARRAY['SO4-2-u3-X17','SO4-2-u3-X09']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C6","difficulty":1,"kind":"mc","stem":"들이 펼쳐진 지역에 도로와 철도가 생겨나면 무엇이 발달하나요? (주제 정리)","options":[{"t":"교통","correct":true},{"t":"산사태","mis":"SO4-2-u3-X17"},{"t":"양식","mis":"SO4-2-u3-X09"},{"t":"간척","mis":"SO4-2-u3-X17"}],"explanation":["길이 생겨요.","오가기 쉬워요.","교통이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#5','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',2,'mc','auto','「지역의 환경과 변화」에서 공부한 내용을 차례대로 늘어놓은 것은 무엇인가요?',ARRAY['SO4-2-u3-X16']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"mc","stem":"「지역의 환경과 변화」에서 공부한 내용을 차례대로 늘어놓은 것은 무엇인가요?","options":[{"t":"① 뜻 → ② 세 지역 → ③ 좋은 점과 문제점 → ④ 조화를 이루는 방법","correct":true},{"t":"④ → ③ → ② → ①","mis":"SO4-2-u3-X16"},{"t":"② → ① → ④ → ③","mis":"SO4-2-u3-X16"},{"t":"③ → ④ → ① → ②","mis":"SO4-2-u3-X16"}],"explanation":["뜻부터 배웠어요.","세 지역을 봤어요.","영향과 조화예요."],"asset":{"type":"passage","lines":["① 자연환경과 인문환경의 뜻","② 산 · 들 · 바다가 있는 지역의 특징과 변화","③ 환경의 이용과 개발에 따른 좋은 점과 문제점","④ 인간과 환경의 조화를 이루는 방법"],"title":"「지역의 환경과 변화」에서 공부한 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#6','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',2,'match','auto','낱말 퍼즐 문제와 답을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"match","stem":"낱말 퍼즐 문제와 답을 알맞게 이으세요.","pairs":[{"l":"가로 ①","r":"자연환경"},{"l":"가로 ②","r":"산사태"},{"l":"세로 ③","r":"생태 통로"},{"l":"세로 ④","r":"자연 휴식년제"}],"mis":"SO4-2-u3-X17","explanation":["①은 자연 그대로예요.","②는 무너져요.","③④는 조화 노력이에요."],"asset":{"type":"passage","lines":["가로 ① 자연 그대로 생겨난 환경","가로 ② 산의 바위나 흙이 갑자기 무너져 내리는 일","세로 ③ 야생 동물이 다니도록 마련한 길","세로 ④ 일정 기간 사람의 출입을 막는 제도"],"title":"낱말 퍼즐 문제(줄여 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#7','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',2,'ox','auto','산의 편지는 많은 사람이 찾아오면서 산에 살던 친구들이 사라졌다고 말해요.',ARRAY['SO4-2-u3-X16']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"ox","stem":"산의 편지는 많은 사람이 찾아오면서 산에 살던 친구들이 사라졌다고 말해요.","answer":"O","reason_options":[{"t":"둘째 줄에 그 내용이 적혀 있기 때문에","correct":true},{"t":"편지에는 산의 좋은 점만 적혀 있기 때문에","mis":"SO4-2-u3-X16"}],"mis":"SO4-2-u3-X16","explanation":["둘째 줄을 읽어요.","친구들이 사라졌어요.","그래서 O예요."],"asset":{"type":"passage","lines":["안녕! 나는 산이야.","많은 사람이 찾아오면서 나에게 살던 친구들이 많이 사라졌어.","나에게 쉬는 기간을 준다면 친구들이 다시 건강하게 살 수 있을 거야."],"title":"산이 사람에게 쓴 편지(줄여 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#8','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',2,'mc','auto','산의 편지에서 산이 바라는 노력과 가장 가까운 것은 무엇인가요?',ARRAY['SO4-2-u3-X17','SO4-2-u3-X11']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"mc","stem":"산의 편지에서 산이 바라는 노력과 가장 가까운 것은 무엇인가요?","options":[{"t":"자연 휴식년제","correct":true},{"t":"간척","mis":"SO4-2-u3-X17"},{"t":"케이블카 놓기","mis":"SO4-2-u3-X11"},{"t":"골프장 짓기","mis":"SO4-2-u3-X11"}],"explanation":["셋째 줄을 읽어요.","쉬는 기간이에요.","자연 휴식년제예요."],"asset":{"type":"passage","lines":["안녕! 나는 산이야.","많은 사람이 찾아오면서 나에게 살던 친구들이 많이 사라졌어.","나에게 쉬는 기간을 준다면 친구들이 다시 건강하게 살 수 있을 거야."],"title":"산이 사람에게 쓴 편지(줄여 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#9','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',2,'blank','auto','생태 통로와 자연 휴식년제는 둘 다 인간과 환경의 (    )를 이루려는 노력이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u3-X17']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"blank","stem":"생태 통로와 자연 휴식년제는 둘 다 인간과 환경의 (    )를 이루려는 노력이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"조화","correct":true},{"t":"개발","mis":"SO4-2-u3-X17"},{"t":"경쟁","mis":"SO4-2-u3-X17"},{"t":"교통","mis":"SO4-2-u3-X17"}],"explanation":["함께 살아가요.","어울리게 해요.","조화예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_basic#10','soc',4,2,'u3','L06','g4_2_soc_u3_L06_basic','lesson_basic','SO4-2-u3-C6',3,'mc','auto','인간과 환경의 조화를 이루는 방법을 그림으로 그릴 때 담을 내용으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X14','SO4-2-u3-X16']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C6","difficulty":3,"kind":"mc","stem":"인간과 환경의 조화를 이루는 방법을 그림으로 그릴 때 담을 내용으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"바닷가에 버려진 쓰레기를 쓰레기통에 넣는 모습","correct":true},{"t":"산을 깎아 골프장을 짓는 모습","mis":"SO4-2-u3-X14"},{"t":"하천에 폐수를 흘려보내는 모습","mis":"SO4-2-u3-X14"},{"t":"색칠만 화려하게 한 모습","mis":"SO4-2-u3-X16"}],"explanation":["조화를 그려요.","자연을 지켜요.","쓰레기를 치워요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#1','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',2,'mc','auto','산의 편지처럼 자연환경이 되어 편지를 쓸 때 고를 자연환경으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X01','SO4-2-u3-X16','SO4-2-u3-X10']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"mc","stem":"산의 편지처럼 자연환경이 되어 편지를 쓸 때 고를 자연환경으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"이용과 개발로 훼손되거나 오염된 자연환경","correct":true},{"t":"사람들이 새로 지은 아파트","mis":"SO4-2-u3-X01"},{"t":"아무 일도 없던 자연환경만","mis":"SO4-2-u3-X16"},{"t":"공장에서 만든 제품","mis":"SO4-2-u3-X10"}],"explanation":["누가 되어 쓰나요?","다친 자연이에요.","훼손되거나 오염된 곳이에요."],"asset":{"type":"passage","lines":["안녕! 나는 산이야.","많은 사람이 찾아오면서 나에게 살던 친구들이 많이 사라졌어.","나에게 쉬는 기간을 준다면 친구들이 다시 건강하게 살 수 있을 거야."],"title":"산이 사람에게 쓴 편지(줄여 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#2','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',2,'ox','auto','산의 편지는 글씨를 예쁘게 쓰는 것이 가장 중요해요.',ARRAY['SO4-2-u3-X16']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"ox","stem":"산의 편지는 글씨를 예쁘게 쓰는 것이 가장 중요해요.","answer":"X","reason_options":[{"t":"자연환경이 사람에게 하고 싶은 말을 담는 것이 중요하기 때문에","correct":true},{"t":"편지는 꾸밈만 보면 되기 때문에","mis":"SO4-2-u3-X16"}],"mis":"SO4-2-u3-X16","explanation":["편지에 무엇을 담나요?","하고 싶은 말이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["안녕! 나는 산이야.","많은 사람이 찾아오면서 나에게 살던 친구들이 많이 사라졌어.","나에게 쉬는 기간을 준다면 친구들이 다시 건강하게 살 수 있을 거야."],"title":"산이 사람에게 쓴 편지(줄여 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#3','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',3,'error','auto','「지역의 환경과 변화」를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X17','SO4-2-u3-X14']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C6","difficulty":3,"kind":"error","stem":"「지역의 환경과 변화」를 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「산사태는 바다를 땅으로 만드는 일이야.」","correct":true,"mis_target":"SO4-2-u3-X17"},{"t":"친구 나 — 「간척은 갯벌을 새 땅으로 만드는 일이야.」","mis":"SO4-2-u3-X17"},{"t":"친구 다 — 「자연 휴식년제는 쉬는 기간을 주는 거야.」","mis":"SO4-2-u3-X14"}],"explanation":["산사태는 무엇이었나요?","흙이 무너지는 일이에요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["가로 ① 자연 그대로 생겨난 환경","가로 ② 산의 바위나 흙이 갑자기 무너져 내리는 일","세로 ③ 야생 동물이 다니도록 마련한 길","세로 ④ 일정 기간 사람의 출입을 막는 제도"],"title":"낱말 퍼즐 문제(줄여 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#4','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',3,'mc','auto','낱말 퍼즐에서 세로 ③과 세로 ④의 같은 점은 무엇인가요?',ARRAY['SO4-2-u3-X17']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C6","difficulty":3,"kind":"mc","stem":"낱말 퍼즐에서 세로 ③과 세로 ④의 같은 점은 무엇인가요?","options":[{"t":"둘 다 개발로 생긴 문제를 해결해 인간과 환경의 조화를 이루려는 노력이에요","correct":true},{"t":"둘 다 산에서 일어나는 위험이에요","mis":"SO4-2-u3-X17"},{"t":"둘 다 새 땅을 만드는 일이에요","mis":"SO4-2-u3-X17"},{"t":"둘 다 교통을 발달시키는 일이에요","mis":"SO4-2-u3-X17"}],"explanation":["③은 동물의 길이에요.","④는 쉬는 기간이에요.","둘 다 조화예요."],"asset":{"type":"passage","lines":["가로 ① 자연 그대로 생겨난 환경","가로 ② 산의 바위나 흙이 갑자기 무너져 내리는 일","세로 ③ 야생 동물이 다니도록 마련한 길","세로 ④ 일정 기간 사람의 출입을 막는 제도"],"title":"낱말 퍼즐 문제(줄여 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#5','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',3,'mc','auto','그림에 담을 「인간과 환경의 조화를 이루는 방법」이 아닌 것은 무엇인가요?',ARRAY['SO4-2-u3-X14']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C6","difficulty":3,"kind":"mc","stem":"그림에 담을 「인간과 환경의 조화를 이루는 방법」이 아닌 것은 무엇인가요?","options":[{"t":"갯벌을 모두 메워 공장을 더 짓는 모습","correct":true},{"t":"생태 통로를 만드는 모습","mis":"SO4-2-u3-X14"},{"t":"자연 휴식년제를 하는 모습","mis":"SO4-2-u3-X14"},{"t":"산에 캠핑장을 만들어 여가를 즐기는 모습","mis":"SO4-2-u3-X14"}],"explanation":["조화를 찾아요.","자연을 해치는 것은요?","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#6','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',3,'ox','auto','공부한 내용의 ③과 ④는 서로 이어져 있어요.',ARRAY['SO4-2-u3-X13']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C6","difficulty":3,"kind":"ox","stem":"공부한 내용의 ③과 ④는 서로 이어져 있어요.","answer":"O","reason_options":[{"t":"개발로 생긴 문제점을 해결하려고 조화를 이루는 방법을 찾기 때문에","correct":true},{"t":"③과 ④는 아무 관계가 없기 때문에","mis":"SO4-2-u3-X13"}],"mis":"SO4-2-u3-X13","explanation":["③은 문제점이에요.","④는 해결 방법이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 자연환경과 인문환경의 뜻","② 산 · 들 · 바다가 있는 지역의 특징과 변화","③ 환경의 이용과 개발에 따른 좋은 점과 문제점","④ 인간과 환경의 조화를 이루는 방법"],"title":"「지역의 환경과 변화」에서 공부한 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#7','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',3,'mc','auto','산의 편지에 이어 쓸 문장으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X14','SO4-2-u3-X13','SO4-2-u3-X01']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C6","difficulty":3,"kind":"mc","stem":"산의 편지에 이어 쓸 문장으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「나를 찾을 때는 쓰레기를 꼭 가져가 줄래?」","correct":true},{"t":"「나를 더 많이 깎아서 길을 내 줘.」","mis":"SO4-2-u3-X14"},{"t":"「내 친구들은 없어도 괜찮아.」","mis":"SO4-2-u3-X13"},{"t":"「나는 사람이 만든 인문환경이야.」","mis":"SO4-2-u3-X01"}],"explanation":["산이 바라는 것이에요.","자연을 지켜 줘요.","그 문장이에요."],"asset":{"type":"passage","lines":["안녕! 나는 산이야.","많은 사람이 찾아오면서 나에게 살던 친구들이 많이 사라졌어.","나에게 쉬는 기간을 준다면 친구들이 다시 건강하게 살 수 있을 거야."],"title":"산이 사람에게 쓴 편지(줄여 옮김)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#8','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',4,'mc','auto','공부한 내용 ①~④를 함께 볼 때 「지역의 환경과 변화」를 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u3-X04','SO4-2-u3-X11','SO4-2-u3-X13']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C6","difficulty":4,"kind":"mc","stem":"공부한 내용 ①~④를 함께 볼 때 「지역의 환경과 변화」를 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"지역마다 환경이 다르고 사람들은 환경을 이용·개발하며, 그 영향을 살펴 조화를 이루려고 노력해요","correct":true},{"t":"지역마다 환경은 모두 같아요","mis":"SO4-2-u3-X04"},{"t":"개발에는 좋은 점만 있어요","mis":"SO4-2-u3-X11"},{"t":"조화를 이루려면 개발을 모두 멈춰야 해요","mis":"SO4-2-u3-X13"}],"explanation":["①②는 환경이에요.","③은 영향이에요.","④는 노력이에요."],"asset":{"type":"passage","lines":["① 자연환경과 인문환경의 뜻","② 산 · 들 · 바다가 있는 지역의 특징과 변화","③ 환경의 이용과 개발에 따른 좋은 점과 문제점","④ 인간과 환경의 조화를 이루는 방법"],"title":"「지역의 환경과 변화」에서 공부한 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#9','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',4,'mc','auto','그림, 편지, 낱말 퍼즐 가운데 하나를 골라 정리할 때 가장 알맞은 생각은 무엇인가요?',ARRAY['SO4-2-u3-X16','SO4-2-u3-X17']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C6","difficulty":4,"kind":"mc","stem":"그림, 편지, 낱말 퍼즐 가운데 하나를 골라 정리할 때 가장 알맞은 생각은 무엇인가요?","options":[{"t":"어떤 방법이든 공부한 내용을 바르게 담으면 돼요","correct":true},{"t":"셋을 모두 똑같이 해야 해요","mis":"SO4-2-u3-X16"},{"t":"그림 솜씨가 좋은 사람만 그림을 그려요","mis":"SO4-2-u3-X16"},{"t":"낱말 퍼즐은 답을 몰라도 돼요","mis":"SO4-2-u3-X17"}],"explanation":["방법은 여럿이에요.","담는 내용이 중요해요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L06_challenge#10','soc',4,2,'u3','L06','g4_2_soc_u3_L06_challenge','lesson_challenge','SO4-2-u3-C6',4,'essay','teacher','이용과 개발로 훼손되거나 오염된 자연환경 하나가 되어 사람에게 편지를 쓰세요. 무엇 때문에 힘든지와 사람에게 바라는 노력을 함께 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C6","difficulty":4,"kind":"essay","stem":"이용과 개발로 훼손되거나 오염된 자연환경 하나가 되어 사람에게 편지를 쓰세요. 무엇 때문에 힘든지와 사람에게 바라는 노력을 함께 쓰세요.","answer_guide":{"answer":"예: 안녕! 나는 하천이야. 공장에서 흘러온 더러운 물 때문에 내 안에 살던 물고기들이 떠나 버렸어. 나를 생태 하천으로 되살려 준다면 물고기와 새들이 다시 돌아올 거야.","scoring_points":["자연환경 하나가 되어 썼는가","힘든 까닭을 썼는가","바라는 노력을 썼는가"]},"explanation":["하나를 골라요.","힘든 까닭을 써요.","바라는 노력을 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#1','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',1,'mc','auto','많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 되는 곳을 무엇이라고 하나요?',ARRAY['SO4-2-u3-X18']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C7","difficulty":1,"kind":"mc","stem":"많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 되는 곳을 무엇이라고 하나요?","options":[{"t":"도시","correct":true},{"t":"산골","mis":"SO4-2-u3-X18"},{"t":"들판","mis":"SO4-2-u3-X18"},{"t":"갯벌","mis":"SO4-2-u3-X18"}],"explanation":["사람이 많아요.","활동의 중심이에요.","도시예요."],"asset":{"type":"passage","lines":["도시는 사람들이 살아가는 삶의 터전이에요.","각종 공공 기관이 자리 잡고 있어요.","병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.","많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 돼요."],"title":"도시는 어떤 곳일까요(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#2','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',1,'sa','auto','도시에는 각종 ○○ 기관이 자리 잡고 있어요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C7","difficulty":1,"kind":"sa","stem":"도시에는 각종 ○○ 기관이 자리 잡고 있어요. ○○에 알맞은 두 글자를 쓰세요.","answer":["공공"],"explanation":["여러 사람을 위해요.","공◯ 기관이에요.","공공이에요."],"asset":{"type":"passage","lines":["도시는 사람들이 살아가는 삶의 터전이에요.","각종 공공 기관이 자리 잡고 있어요.","병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.","많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 돼요."],"title":"도시는 어떤 곳일까요(내 말로)"},"mis":"SO4-2-u3-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#3','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',1,'ox','auto','도시에는 병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.',ARRAY['SO4-2-u3-X19']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C7","difficulty":1,"kind":"ox","stem":"도시에는 병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.","answer":"O","reason_options":[{"t":"많은 사람이 모여 살아 생활에 필요한 시설이 많기 때문에","correct":true},{"t":"도시에는 편의 시설이 거의 없기 때문에","mis":"SO4-2-u3-X19"}],"mis":"SO4-2-u3-X19","explanation":["셋째 줄을 읽어요.","병원과 상점이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["도시는 사람들이 살아가는 삶의 터전이에요.","각종 공공 기관이 자리 잡고 있어요.","병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.","많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 돼요."],"title":"도시는 어떤 곳일까요(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#4','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',1,'mc','auto','밤하늘에서 찍은 우리나라 사진에서 밝게 빛나는 곳은 어떤 곳일까요?',ARRAY['SO4-2-u3-X19']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C7","difficulty":1,"kind":"mc","stem":"밤하늘에서 찍은 우리나라 사진에서 밝게 빛나는 곳은 어떤 곳일까요?","options":[{"t":"밤에도 불이 켜진 곳이 많은 도시","correct":true},{"t":"사람이 살지 않는 깊은 산","mis":"SO4-2-u3-X19"},{"t":"불빛이 없는 바다 한가운데","mis":"SO4-2-u3-X19"},{"t":"넓은 논만 있는 들판","mis":"SO4-2-u3-X19"}],"explanation":["밝은 곳을 봐요.","불이 켜져 있어요.","도시예요."],"asset":{"type":"passage","lines":["밤하늘에서 찍은 우리나라 사진이에요.","몇몇 곳은 유난히 밝게 빛나고, 어두운 곳도 많아요.","밝은 곳에는 밤에도 불이 켜진 건물과 거리가 많아요."],"title":"밤하늘에서 본 우리나라(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#5','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',2,'mc','auto','밤하늘 사진에서 도시가 밝게 빛나는 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X19','SO4-2-u3-X18']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C7","difficulty":2,"kind":"mc","stem":"밤하늘 사진에서 도시가 밝게 빛나는 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"도시에 사는 사람들이 밤늦게까지 활동하기 때문이에요","correct":true},{"t":"도시에는 별이 더 많기 때문이에요","mis":"SO4-2-u3-X19"},{"t":"도시는 낮이 더 길기 때문이에요","mis":"SO4-2-u3-X19"},{"t":"도시에는 사람이 거의 없기 때문이에요","mis":"SO4-2-u3-X18"}],"explanation":["불을 누가 켜나요?","사람들이에요.","밤늦게 활동해요."],"asset":{"type":"passage","lines":["밤하늘에서 찍은 우리나라 사진이에요.","몇몇 곳은 유난히 밝게 빛나고, 어두운 곳도 많아요.","밝은 곳에는 밤에도 불이 켜진 건물과 거리가 많아요."],"title":"밤하늘에서 본 우리나라(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#6','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',2,'match','auto','「도시」 하면 떠오르는 낱말과 까닭을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u3-C7","difficulty":2,"kind":"match","stem":"「도시」 하면 떠오르는 낱말과 까닭을 알맞게 이으세요.","pairs":[{"l":"복잡하다","r":"거리에 사람도 상점도 많아서요"},{"l":"빠르다","r":"자동차와 기차가 빠르게 다녀서요"},{"l":"바쁘다","r":"사람들이 이곳저곳을 오가서요"}],"mis":"SO4-2-u3-X20","explanation":["복잡함은 많아서예요.","빠름은 탈것이에요.","바쁨은 오가서예요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"「복잡하다」 — 거리에 사람도 상점도 많아서요."},{"who":"친구 나","text":"「빠르다」 — 자동차와 기차가 빠르게 다녀서요."},{"who":"친구 다","text":"「바쁘다」 — 사람들이 이곳저곳을 오가며 움직여서요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#7','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',2,'ox','auto','높은 건물이 하나 있기만 하면 그곳은 도시예요.',ARRAY['SO4-2-u3-X18']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C7","difficulty":2,"kind":"ox","stem":"높은 건물이 하나 있기만 하면 그곳은 도시예요.","answer":"X","reason_options":[{"t":"많은 인구가 모여 살며 정치·경제·사회 활동의 중심이 되어야 도시이기 때문에","correct":true},{"t":"건물이 높으면 언제나 도시이기 때문에","mis":"SO4-2-u3-X18"}],"mis":"SO4-2-u3-X18","explanation":["뜻을 떠올려요.","인구와 활동의 중심이에요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#8','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',2,'mc','auto','「도시」 하면 떠오르는 낱말과 까닭이 알맞게 이어지지 않은 것은 무엇인가요?',ARRAY['SO4-2-u3-X20','SO4-2-u3-X19']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C7","difficulty":2,"kind":"mc","stem":"「도시」 하면 떠오르는 낱말과 까닭이 알맞게 이어지지 않은 것은 무엇인가요?","options":[{"t":"「조용하다」 — 거리에 사람과 차가 아주 많아서요","correct":true},{"t":"「복잡하다」 — 사람과 상점이 많아서요","mis":"SO4-2-u3-X20"},{"t":"「빠르다」 — 기차가 빠르게 다녀서요","mis":"SO4-2-u3-X20"},{"t":"「밝다」 — 밤에도 불이 켜져 있어서요","mis":"SO4-2-u3-X19"}],"explanation":["낱말과 까닭이 맞나요?","많으면 조용할까요?","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#9','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',2,'blank','auto','도시는 사람들이 살아가는 삶의 (    )이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u3-X18']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C7","difficulty":2,"kind":"blank","stem":"도시는 사람들이 살아가는 삶의 (    )이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"터전","correct":true},{"t":"가장자리","mis":"SO4-2-u3-X18"},{"t":"바깥","mis":"SO4-2-u3-X18"},{"t":"끝","mis":"SO4-2-u3-X18"}],"explanation":["첫째 줄을 읽어요.","사람이 사는 곳이에요.","터전이에요."],"asset":{"type":"passage","lines":["도시는 사람들이 살아가는 삶의 터전이에요.","각종 공공 기관이 자리 잡고 있어요.","병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.","많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 돼요."],"title":"도시는 어떤 곳일까요(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_basic#10','soc',4,2,'u3','L07','g4_2_soc_u3_L07_basic','lesson_basic','SO4-2-u3-C7',3,'mc','auto','가 본 도시의 모습 가운데 도시가 어떤 곳인지 가장 잘 드러난 것은 무엇인가요?',ARRAY['SO4-2-u3-X18']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C7","difficulty":3,"kind":"mc","stem":"가 본 도시의 모습 가운데 도시가 어떤 곳인지 가장 잘 드러난 것은 무엇인가요?","options":[{"t":"공공 기관과 상점이 많고 많은 사람이 오가는 모습","correct":true},{"t":"사람이 없는 조용한 숲길","mis":"SO4-2-u3-X18"},{"t":"넓은 논에서 벼가 자라는 모습","mis":"SO4-2-u3-X18"},{"t":"바다에서 김을 기르는 모습","mis":"SO4-2-u3-X18"}],"explanation":["도시의 뜻을 떠올려요.","사람과 시설이 많아요.","그 모습이에요."],"asset":{"type":"passage","lines":["도시는 사람들이 살아가는 삶의 터전이에요.","각종 공공 기관이 자리 잡고 있어요.","병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.","많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 돼요."],"title":"도시는 어떤 곳일까요(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#1','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',2,'mc','auto','도시에서 볼 수 있는 모습으로 알맞지 않은 것은 무엇인가요?',ARRAY['SO4-2-u3-X18','SO4-2-u3-X19']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C7","difficulty":2,"kind":"mc","stem":"도시에서 볼 수 있는 모습으로 알맞지 않은 것은 무엇인가요?","options":[{"t":"사람이 거의 오가지 않는 텅 빈 거리","correct":true},{"t":"높은 빌딩이 늘어선 거리","mis":"SO4-2-u3-X18"},{"t":"버스 정류장과 지하철역","mis":"SO4-2-u3-X19"},{"t":"물건을 사고파는 시장","mis":"SO4-2-u3-X19"}],"explanation":["도시를 떠올려요.","사람이 많아요.","텅 빈 거리를 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#2','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',2,'ox','auto','「도시」 하면 떠오르는 낱말을 말할 때는 까닭도 함께 말하는 것이 좋아요.',ARRAY['SO4-2-u3-X20']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C7","difficulty":2,"kind":"ox","stem":"「도시」 하면 떠오르는 낱말을 말할 때는 까닭도 함께 말하는 것이 좋아요.","answer":"O","reason_options":[{"t":"왜 그 낱말이 떠올랐는지 알아야 도시의 모습을 함께 나눌 수 있기 때문에","correct":true},{"t":"낱말만 말하면 충분하기 때문에","mis":"SO4-2-u3-X20"}],"mis":"SO4-2-u3-X20","explanation":["친구들의 말을 봐요.","까닭이 있어요.","그래서 O예요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"「복잡하다」 — 거리에 사람도 상점도 많아서요."},{"who":"친구 나","text":"「빠르다」 — 자동차와 기차가 빠르게 다녀서요."},{"who":"친구 다","text":"「바쁘다」 — 사람들이 이곳저곳을 오가며 움직여서요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#3','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',3,'error','auto','도시를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X18','SO4-2-u3-X19']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C7","difficulty":3,"kind":"error","stem":"도시를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「사람만 많으면 어디든 도시야.」","correct":true,"mis_target":"SO4-2-u3-X18"},{"t":"친구 가 — 「도시에는 공공 기관이 있어.」","mis":"SO4-2-u3-X19"},{"t":"친구 다 — 「도시는 활동의 중심이 돼.」","mis":"SO4-2-u3-X18"}],"explanation":["사람만 많으면 될까요?","활동의 중심이어야 해요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["도시는 사람들이 살아가는 삶의 터전이에요.","각종 공공 기관이 자리 잡고 있어요.","병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.","많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 돼요."],"title":"도시는 어떤 곳일까요(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#4','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',3,'mc','auto','밤하늘 사진에서 밝은 곳과 어두운 곳을 견주어 알 수 있는 것으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X19']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C7","difficulty":3,"kind":"mc","stem":"밤하늘 사진에서 밝은 곳과 어두운 곳을 견주어 알 수 있는 것으로 알맞은 것은 무엇인가요?","options":[{"t":"사람이 많이 모여 사는 곳일수록 밤에도 밝아요","correct":true},{"t":"어두운 곳에 사람이 더 많이 살아요","mis":"SO4-2-u3-X19"},{"t":"밝기는 사람 수와 관계없어요","mis":"SO4-2-u3-X19"},{"t":"밝은 곳은 모두 바다예요","mis":"SO4-2-u3-X19"}],"explanation":["밝은 곳은 도시예요.","사람이 많아요.","많을수록 밝아요."],"asset":{"type":"passage","lines":["밤하늘에서 찍은 우리나라 사진이에요.","몇몇 곳은 유난히 밝게 빛나고, 어두운 곳도 많아요.","밝은 곳에는 밤에도 불이 켜진 건물과 거리가 많아요."],"title":"밤하늘에서 본 우리나라(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#5','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',3,'mc','auto','사람들이 모두 떠난 곳은 밤에 어떻게 보일까요?',ARRAY['SO4-2-u3-X19']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C7","difficulty":3,"kind":"mc","stem":"사람들이 모두 떠난 곳은 밤에 어떻게 보일까요?","options":[{"t":"불빛이 꺼져 어둡게 보여요","correct":true},{"t":"더 밝게 빛나요","mis":"SO4-2-u3-X19"},{"t":"공공 기관이 새로 생겨요","mis":"SO4-2-u3-X19"},{"t":"편의 시설이 늘어나요","mis":"SO4-2-u3-X19"}],"explanation":["불은 누가 켜나요?","사람이 떠났어요.","어두워져요."],"asset":{"type":"passage","lines":["밤하늘에서 찍은 우리나라 사진이에요.","몇몇 곳은 유난히 밝게 빛나고, 어두운 곳도 많아요.","밝은 곳에는 밤에도 불이 켜진 건물과 거리가 많아요."],"title":"밤하늘에서 본 우리나라(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#6','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',3,'ox','auto','도시에 공공 기관과 편의 시설이 많은 것은 많은 사람이 모여 살기 때문이에요.',ARRAY['SO4-2-u3-X19']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C7","difficulty":3,"kind":"ox","stem":"도시에 공공 기관과 편의 시설이 많은 것은 많은 사람이 모여 살기 때문이에요.","answer":"O","reason_options":[{"t":"사람이 많을수록 필요한 시설과 일이 늘어나기 때문에","correct":true},{"t":"시설은 사람 수와 관계없이 생기기 때문에","mis":"SO4-2-u3-X19"}],"mis":"SO4-2-u3-X19","explanation":["사람이 모였어요.","필요한 것이 늘어요.","그래서 O예요."],"asset":{"type":"passage","lines":["도시는 사람들이 살아가는 삶의 터전이에요.","각종 공공 기관이 자리 잡고 있어요.","병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.","많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 돼요."],"title":"도시는 어떤 곳일까요(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#7','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',3,'mc','auto','친구 다가 「바쁘다」를 떠올린 까닭과 가장 가까운 도시의 모습은 무엇인가요?',ARRAY['SO4-2-u3-X20','SO4-2-u3-X18']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C7","difficulty":3,"kind":"mc","stem":"친구 다가 「바쁘다」를 떠올린 까닭과 가장 가까운 도시의 모습은 무엇인가요?","options":[{"t":"출근 시간에 많은 사람이 이곳저곳으로 서둘러 움직이는 모습","correct":true},{"t":"밤에 거리의 불빛이 모두 꺼진 모습","mis":"SO4-2-u3-X20"},{"t":"넓은 논에 벼가 자라는 모습","mis":"SO4-2-u3-X18"},{"t":"숲속에서 새가 우는 모습","mis":"SO4-2-u3-X18"}],"explanation":["친구 다의 까닭을 봐요.","오가며 움직여요.","그 모습이에요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"「복잡하다」 — 거리에 사람도 상점도 많아서요."},{"who":"친구 나","text":"「빠르다」 — 자동차와 기차가 빠르게 다녀서요."},{"who":"친구 다","text":"「바쁘다」 — 사람들이 이곳저곳을 오가며 움직여서요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#8','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',4,'mc','auto','밤하늘 사진과 도시에 대한 글을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X19','SO4-2-u3-X18']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C7","difficulty":4,"kind":"mc","stem":"밤하늘 사진과 도시에 대한 글을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"많은 사람이 모여 살며 활동하는 도시는 시설이 많고 밤에도 밝게 빛나요","correct":true},{"t":"도시는 사람이 적어 밤에 어두워요","mis":"SO4-2-u3-X19"},{"t":"도시에는 공공 기관이 없어요","mis":"SO4-2-u3-X19"},{"t":"밤에 밝은 곳은 도시가 아니에요","mis":"SO4-2-u3-X18"}],"explanation":["사진은 밝은 곳이에요.","글은 시설과 사람이에요.","둘을 합쳐요."],"asset":{"type":"passage","lines":["도시는 사람들이 살아가는 삶의 터전이에요.","각종 공공 기관이 자리 잡고 있어요.","병원, 상점 같은 편의 시설이 잘 갖춰져 있어요.","많은 인구가 모여 살면서 정치, 경제, 사회 활동의 중심이 돼요."],"title":"도시는 어떤 곳일까요(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#9','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',4,'mc','auto','도시의 뜻을 가장 바르게 말한 것은 무엇인가요?',ARRAY['SO4-2-u3-X18','SO4-2-u3-X19']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C7","difficulty":4,"kind":"mc","stem":"도시의 뜻을 가장 바르게 말한 것은 무엇인가요?","options":[{"t":"많은 사람이 모여 살고 정치·경제·사회 활동의 중심이 되며, 공공 기관과 편의 시설이 갖춰진 곳","correct":true},{"t":"높은 건물이 한 채 있는 곳","mis":"SO4-2-u3-X18"},{"t":"밤에 불을 하나 켠 곳","mis":"SO4-2-u3-X19"},{"t":"사람이 거의 살지 않는 조용한 곳","mis":"SO4-2-u3-X18"}],"explanation":["사람이 많아요.","활동의 중심이에요.","시설도 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L07_challenge#10','soc',4,2,'u3','L07','g4_2_soc_u3_L07_challenge','lesson_challenge','SO4-2-u3-C7',4,'essay','teacher','「도시」 하면 떠오르는 낱말을 하나 쓰고 그 까닭을 쓰세요. 그리고 그 낱말이 도시의 뜻과 어떻게 이어지는지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C7","difficulty":4,"kind":"essay","stem":"「도시」 하면 떠오르는 낱말을 하나 쓰고 그 까닭을 쓰세요. 그리고 그 낱말이 도시의 뜻과 어떻게 이어지는지 쓰세요.","answer_guide":{"answer":"예: 「북적이다」가 떠올라요. 시장과 지하철역에 사람이 아주 많기 때문이에요. 도시는 많은 인구가 모여 사는 곳이라 이런 모습을 자주 볼 수 있어요.","scoring_points":["낱말을 하나 썼는가","까닭을 썼는가","도시의 뜻과 이었는가"]},"explanation":["낱말을 골라요.","까닭을 써요.","뜻과 이어요."],"asset":{"type":"speech","turns":[{"who":"친구 가","text":"「복잡하다」 — 거리에 사람도 상점도 많아서요."},{"who":"친구 나","text":"「빠르다」 — 자동차와 기차가 빠르게 다녀서요."},{"who":"친구 다","text":"「바쁘다」 — 사람들이 이곳저곳을 오가며 움직여서요."}]}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_basic#1','soc',4,2,'u3','L08','g4_2_soc_u3_L08_basic','lesson_basic','SO4-2-u3-C8',1,'mc','auto','우리나라 인구 10명 가운데 도시에 사는 사람은 몇 명 정도인가요?',ARRAY['SO4-2-u3-X21']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C8","difficulty":1,"kind":"mc","stem":"우리나라 인구 10명 가운데 도시에 사는 사람은 몇 명 정도인가요?","options":[{"t":"9명 정도","correct":true},{"t":"1명 정도","mis":"SO4-2-u3-X21"},{"t":"3명 정도","mis":"SO4-2-u3-X21"},{"t":"5명 정도","mis":"SO4-2-u3-X21"}],"explanation":["●을 세어요.","아홉 개예요.","9명 정도예요."],"asset":{"type":"passage","lines":["● ● ● ● ● ● ● ● ● ○","● = 도시에 사는 사람  ○ = 도시가 아닌 곳에 사는 사람"],"title":"우리나라 인구 10명을 그림으로 나타내면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_basic#2','soc',4,2,'u3','L08','g4_2_soc_u3_L08_basic','lesson_basic','SO4-2-u3-C8',1,'sa','auto','시장이나 대형 할인점에서 물건을 사고파는 산업은 무엇인가요? 두 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C8","difficulty":1,"kind":"sa","stem":"시장이나 대형 할인점에서 물건을 사고파는 산업은 무엇인가요? 두 글자로 쓰세요.","answer":["상업"],"explanation":["사고파는 일이에요.","상◯이에요.","상업이에요."],"asset":{"type":"passage","lines":["㉠ 사람들이 필요로 하는 물건을 한 번에 많이 만들어요.","㉡ 시장이나 대형 할인점에서 물건을 사고팔아요.","㉢ 개인이나 회사의 돈을 맡아 주거나 빌려줘요.","㉣ 다양한 행사가 열려 관광객이 찾아와요."],"title":"◇◇시에 발달한 산업(지어낸 자료)"},"mis":"SO4-2-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_basic#3','soc',4,2,'u3','L08','g4_2_soc_u3_L08_basic','lesson_basic','SO4-2-u3-C8',1,'ox','auto','도시에는 많은 사람이 살 수 있는 아파트나 연립주택이 많아요.',ARRAY['SO4-2-u3-X21']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C8","difficulty":1,"kind":"ox","stem":"도시에는 많은 사람이 살 수 있는 아파트나 연립주택이 많아요.","answer":"O","reason_options":[{"t":"좁은 땅에 많은 사람이 살 수 있도록 지은 집이기 때문에","correct":true},{"t":"도시 사람들은 모두 단독 주택에만 살기 때문에","mis":"SO4-2-u3-X21"}],"mis":"SO4-2-u3-X21","explanation":["사람이 많아요.","여러 가구가 살아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_basic#4','soc',4,2,'u3','L08','g4_2_soc_u3_L08_basic','lesson_basic','SO4-2-u3-C8',1,'mc','auto','◇◇시 지도에 있는 곳 가운데 교통과 관련 있는 곳은 무엇인가요?',ARRAY['SO4-2-u3-X23']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C8","difficulty":1,"kind":"mc","stem":"◇◇시 지도에 있는 곳 가운데 교통과 관련 있는 곳은 무엇인가요?","options":[{"t":"지하철역","correct":true},{"t":"시청","mis":"SO4-2-u3-X23"},{"t":"미술관","mis":"SO4-2-u3-X23"},{"t":"공원","mis":"SO4-2-u3-X23"}],"explanation":["타고 다니는 곳이에요.","역이 있어요.","지하철역이에요."],"asset":{"type":"passage","lines":["시청 · 지하철역 · 기차역 · 미술관","버스 터미널 · 공원 · 공항 · 항구"],"title":"◇◇시 지도에 있는 곳(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_basic#5','soc',4,2,'u3','L08','g4_2_soc_u3_L08_basic','lesson_basic','SO4-2-u3-C8',2,'match','auto','◇◇시에 발달한 산업과 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"match","stem":"◇◇시에 발달한 산업과 이름을 알맞게 이으세요.","pairs":[{"l":"㉠","r":"제조업"},{"l":"㉡","r":"상업"},{"l":"㉢","r":"금융업"},{"l":"㉣","r":"관광 산업"}],"mis":"SO4-2-u3-X22","explanation":["㉠은 만들어요.","㉡은 사고팔아요.","㉢은 돈, ㉣은 관광이에요."],"asset":{"type":"passage","lines":["㉠ 사람들이 필요로 하는 물건을 한 번에 많이 만들어요.","㉡ 시장이나 대형 할인점에서 물건을 사고팔아요.","㉢ 개인이나 회사의 돈을 맡아 주거나 빌려줘요.","㉣ 다양한 행사가 열려 관광객이 찾아와요."],"title":"◇◇시에 발달한 산업(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_basic#6','soc',4,2,'u3','L08','g4_2_soc_u3_L08_basic','lesson_basic','SO4-2-u3-C8',2,'mc','auto','도시에 교통이 발달하면 어떤 점이 좋은가요?',ARRAY['SO4-2-u3-X23']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"mc","stem":"도시에 교통이 발달하면 어떤 점이 좋은가요?","options":[{"t":"많은 사람과 물건이 빠르고 편리하게 이동할 수 있어요","correct":true},{"t":"물건을 옮길 수 없게 돼요","mis":"SO4-2-u3-X23"},{"t":"사람들이 걸어서만 다녀요","mis":"SO4-2-u3-X23"},{"t":"다른 곳과 더 멀어져요","mis":"SO4-2-u3-X23"}],"explanation":["길과 탈것이 많아요.","빠르게 오가요.","편리하게 이동해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_basic#7','soc',4,2,'u3','L08','g4_2_soc_u3_L08_basic','lesson_basic','SO4-2-u3-C8',2,'ox','auto','도시에는 한 가지 산업만 발달해요.',ARRAY['SO4-2-u3-X22']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"ox","stem":"도시에는 한 가지 산업만 발달해요.","answer":"X","reason_options":[{"t":"제조업, 상업, 금융업, 관광 산업처럼 다양한 산업이 발달하기 때문에","correct":true},{"t":"도시는 물건을 만드는 일만 하기 때문에","mis":"SO4-2-u3-X22"}],"mis":"SO4-2-u3-X22","explanation":["◇◇시를 봐요.","네 가지가 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["㉠ 사람들이 필요로 하는 물건을 한 번에 많이 만들어요.","㉡ 시장이나 대형 할인점에서 물건을 사고팔아요.","㉢ 개인이나 회사의 돈을 맡아 주거나 빌려줘요.","㉣ 다양한 행사가 열려 관광객이 찾아와요."],"title":"◇◇시에 발달한 산업(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_basic#8','soc',4,2,'u3','L08','g4_2_soc_u3_L08_basic','lesson_basic','SO4-2-u3-C8',2,'mc','auto','오늘날 우리나라 사람들이 많이 모여 사는 곳은 어디인가요?',ARRAY['SO4-2-u3-X21']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"mc","stem":"오늘날 우리나라 사람들이 많이 모여 사는 곳은 어디인가요?","options":[{"t":"대부분 도시에 살아요","correct":true},{"t":"대부분 산골에 살아요","mis":"SO4-2-u3-X21"},{"t":"대부분 바닷가 섬에 살아요","mis":"SO4-2-u3-X21"},{"t":"도시와 시골에 똑같이 나뉘어 살아요","mis":"SO4-2-u3-X21"}],"explanation":["10명 가운데 9명이에요.","거의 다예요.","도시예요."],"asset":{"type":"passage","lines":["● ● ● ● ● ● ● ● ● ○","● = 도시에 사는 사람  ○ = 도시가 아닌 곳에 사는 사람"],"title":"우리나라 인구 10명을 그림으로 나타내면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
