INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_basic#10','soc',4,2,'u3','L08','g4_2_soc_u3_L08_basic','lesson_basic','SO4-2-u3-C8',3,'mc','auto','많은 사람이 도시로 모여든 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X22','SO4-2-u3-X23','SO4-2-u3-X21']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C8","difficulty":3,"kind":"mc","stem":"많은 사람이 도시로 모여든 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"일자리가 많고 생활하기 편리하기 때문이에요","correct":true},{"t":"도시에는 공장이 하나도 없기 때문이에요","mis":"SO4-2-u3-X22"},{"t":"도시는 교통이 불편하기 때문이에요","mis":"SO4-2-u3-X23"},{"t":"도시에는 집이 없기 때문이에요","mis":"SO4-2-u3-X21"}],"explanation":["일할 곳이 있어요.","생활도 편해요.","그래서 모여요."],"asset":{"type":"passage","lines":["● ● ● ● ● ● ● ● ● ○","● = 도시에 사는 사람  ○ = 도시가 아닌 곳에 사는 사람"],"title":"우리나라 인구 10명을 그림으로 나타내면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#1','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',2,'mc','auto','◇◇시 지도에 있는 곳 가운데 교통과 관련 있는 곳을 모두 고른 것은 무엇인가요?',ARRAY['SO4-2-u3-X23']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"mc","stem":"◇◇시 지도에 있는 곳 가운데 교통과 관련 있는 곳을 모두 고른 것은 무엇인가요?","options":[{"t":"지하철역 · 기차역 · 버스 터미널 · 공항 · 항구","correct":true},{"t":"시청 · 미술관 · 공원","mis":"SO4-2-u3-X23"},{"t":"지하철역 · 시청 · 공원","mis":"SO4-2-u3-X23"},{"t":"기차역 · 미술관 · 공항","mis":"SO4-2-u3-X23"}],"explanation":["타고 다니는 곳이에요.","다섯 곳이에요.","그것을 골라요."],"asset":{"type":"passage","lines":["시청 · 지하철역 · 기차역 · 미술관","버스 터미널 · 공원 · 공항 · 항구"],"title":"◇◇시 지도에 있는 곳(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#2','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',2,'ox','auto','도시의 두 곳 사이에 길을 하나 더 놓으면 두 곳은 더 가까워지거나 그대로예요.',ARRAY['SO4-2-u3-X23']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"ox","stem":"도시의 두 곳 사이에 길을 하나 더 놓으면 두 곳은 더 가까워지거나 그대로예요.","answer":"O","reason_options":[{"t":"길이 늘면 돌아가지 않고 더 빨리 닿을 수 있기 때문에","correct":true},{"t":"길을 놓을수록 언제나 더 멀어지기 때문에","mis":"SO4-2-u3-X23"}],"mis":"SO4-2-u3-X23","explanation":["길이 하나 늘었어요.","더 빨리 닿아요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#3','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',3,'error','auto','도시의 특징을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X22','SO4-2-u3-X21','SO4-2-u3-X23']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C8","difficulty":3,"kind":"error","stem":"도시의 특징을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「물건을 많이 만드는 산업은 금융업이야.」","correct":true,"mis_target":"SO4-2-u3-X22"},{"t":"친구 가 — 「도시에 우리나라 사람 대부분이 살아.」","mis":"SO4-2-u3-X21"},{"t":"친구 나 — 「도시는 교통이 발달했어.」","mis":"SO4-2-u3-X23"}],"explanation":["물건을 만드는 산업은요?","제조업이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["㉠ 사람들이 필요로 하는 물건을 한 번에 많이 만들어요.","㉡ 시장이나 대형 할인점에서 물건을 사고팔아요.","㉢ 개인이나 회사의 돈을 맡아 주거나 빌려줘요.","㉣ 다양한 행사가 열려 관광객이 찾아와요."],"title":"◇◇시에 발달한 산업(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#4','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',3,'mc','auto','지도 애플리케이션으로 도시의 산업이 발달한 모습을 살펴보려면 어느 곳을 찾아보면 좋을까요?',ARRAY['SO4-2-u3-X23','SO4-2-u3-X19','SO4-2-u3-X22']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C8","difficulty":3,"kind":"mc","stem":"지도 애플리케이션으로 도시의 산업이 발달한 모습을 살펴보려면 어느 곳을 찾아보면 좋을까요?","options":[{"t":"산업 단지나 공업 단지","correct":true},{"t":"기차역과 버스 터미널","mis":"SO4-2-u3-X23"},{"t":"시청 주변","mis":"SO4-2-u3-X19"},{"t":"동네 놀이터","mis":"SO4-2-u3-X22"}],"explanation":["산업을 살펴요.","공장이 모인 곳이에요.","산업 단지예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#5','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',3,'mc','auto','우리나라 인구 10명을 나타낸 그림에서 ○은 몇 명을 나타내나요?',ARRAY['SO4-2-u3-X21']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C8","difficulty":3,"kind":"mc","stem":"우리나라 인구 10명을 나타낸 그림에서 ○은 몇 명을 나타내나요?","options":[{"t":"1명","correct":true},{"t":"9명","mis":"SO4-2-u3-X21"},{"t":"5명","mis":"SO4-2-u3-X21"},{"t":"0명","mis":"SO4-2-u3-X21"}],"explanation":["○을 세어요.","하나예요.","1명이에요."],"asset":{"type":"passage","lines":["● ● ● ● ● ● ● ● ● ○","● = 도시에 사는 사람  ○ = 도시가 아닌 곳에 사는 사람"],"title":"우리나라 인구 10명을 그림으로 나타내면"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#6','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',3,'ox','auto','◇◇시의 ㉣처럼 다양한 행사가 열려 관광객이 찾아오는 것도 도시에 발달한 산업이에요.',ARRAY['SO4-2-u3-X22']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C8","difficulty":3,"kind":"ox","stem":"◇◇시의 ㉣처럼 다양한 행사가 열려 관광객이 찾아오는 것도 도시에 발달한 산업이에요.","answer":"O","reason_options":[{"t":"관광 산업으로 사람들이 일하고 돈을 벌기 때문에","correct":true},{"t":"관광은 산업이 아니기 때문에","mis":"SO4-2-u3-X22"}],"mis":"SO4-2-u3-X22","explanation":["㉣을 봐요.","관광 산업이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉠ 사람들이 필요로 하는 물건을 한 번에 많이 만들어요.","㉡ 시장이나 대형 할인점에서 물건을 사고팔아요.","㉢ 개인이나 회사의 돈을 맡아 주거나 빌려줘요.","㉣ 다양한 행사가 열려 관광객이 찾아와요."],"title":"◇◇시에 발달한 산업(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#7','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',3,'mc','auto','도시의 여섯 곳을 모두 이으려면 길이 적어도 몇 개 있어야 하나요?',ARRAY['SO4-2-u3-X23']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C8","difficulty":3,"kind":"mc","stem":"도시의 여섯 곳을 모두 이으려면 길이 적어도 몇 개 있어야 하나요?","options":[{"t":"5개","correct":true},{"t":"1개","mis":"SO4-2-u3-X23"},{"t":"2개","mis":"SO4-2-u3-X23"},{"t":"15개","mis":"SO4-2-u3-X23"}],"explanation":["곳이 여섯이에요.","하나씩 이어요.","적어도 5개예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#8','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',4,'mc','auto','도시의 특징을 인구·산업·교통으로 바르게 정리한 것은 무엇인가요?',ARRAY['SO4-2-u3-X21','SO4-2-u3-X22']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C8","difficulty":4,"kind":"mc","stem":"도시의 특징을 인구·산업·교통으로 바르게 정리한 것은 무엇인가요?","options":[{"t":"많은 사람이 모여 살고, 다양한 산업이 발달했으며, 교통이 발달해 빠르게 이동해요","correct":true},{"t":"사람이 적고, 산업은 하나뿐이며, 교통이 불편해요","mis":"SO4-2-u3-X21"},{"t":"사람이 많지만 산업과 교통은 발달하지 않았어요","mis":"SO4-2-u3-X22"},{"t":"교통만 발달하고 사람은 모두 시골에 살아요","mis":"SO4-2-u3-X21"}],"explanation":["인구를 떠올려요.","산업을 떠올려요.","교통도 떠올려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#9','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',4,'mc','auto','◇◇시의 산업 ㉠~㉣과 지도에 있는 곳을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X22','SO4-2-u3-X23']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C8","difficulty":4,"kind":"mc","stem":"◇◇시의 산업 ㉠~㉣과 지도에 있는 곳을 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"◇◇시는 여러 산업이 발달하고 사람과 물건이 오가는 교통 시설도 많은 도시예요","correct":true},{"t":"◇◇시는 산업 없이 공원만 많아요","mis":"SO4-2-u3-X22"},{"t":"◇◇시는 교통 시설이 하나도 없어요","mis":"SO4-2-u3-X23"},{"t":"◇◇시는 물건을 사고팔지 않아요","mis":"SO4-2-u3-X22"}],"explanation":["산업이 넷이에요.","역과 공항이 있어요.","둘을 합쳐요."],"asset":{"type":"passage","lines":["시청 · 지하철역 · 기차역 · 미술관","버스 터미널 · 공원 · 공항 · 항구"],"title":"◇◇시 지도에 있는 곳(지어낸 자료)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L08_challenge#10','soc',4,2,'u3','L08','g4_2_soc_u3_L08_challenge','lesson_challenge','SO4-2-u3-C8',4,'essay','teacher','도시에 많은 사람이 모여 사는 까닭을 산업이나 교통과 이어 쓰세요. 그리고 지도 애플리케이션으로 그 모습을 확인하려면 어디를 찾아볼지 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C8","difficulty":4,"kind":"essay","stem":"도시에 많은 사람이 모여 사는 까닭을 산업이나 교통과 이어 쓰세요. 그리고 지도 애플리케이션으로 그 모습을 확인하려면 어디를 찾아볼지 쓰세요.","answer_guide":{"answer":"예: 도시에는 제조업, 상업, 금융업처럼 다양한 산업이 발달해 일자리가 많고, 교통이 발달해 오가기 편리해서 많은 사람이 모여 살아요. 지도 애플리케이션에서는 산업 단지와 기차역, 지하철역을 찾아볼 거예요.","scoring_points":["산업이나 교통과 이어 까닭을 썼는가","찾아볼 곳을 썼는가","찾아볼 곳이 까닭과 맞는가"]},"explanation":["까닭을 써요.","찾아볼 곳을 써요.","둘을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#1','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',1,'mc','auto','도시에 사는 사람들은 주로 어떤 곳에서 사나요?',ARRAY['SO4-2-u3-X24']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C9","difficulty":1,"kind":"mc","stem":"도시에 사는 사람들은 주로 어떤 곳에서 사나요?","options":[{"t":"아파트나 주택","correct":true},{"t":"목장의 축사","mis":"SO4-2-u3-X24"},{"t":"양식장 옆 배","mis":"SO4-2-u3-X24"},{"t":"산비탈의 밭","mis":"SO4-2-u3-X24"}],"explanation":["첫째 줄을 봐요.","아파트에서 나와요.","아파트나 주택이에요."],"asset":{"type":"passage","lines":["아침 — 아파트에서 나와 지하철을 타고 회사로 가요.","낮 — 사무실에서 회의를 하거나 공장에서 자동차를 조립해요.","낮 — 은행이나 우체국에서 손님을 도와요.","저녁·주말 — 미술관에 가거나 공원에서 자전거를 타요."],"title":"도시에 사는 사람들의 하루(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#2','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',1,'sa','auto','대사 없이 몸짓과 표정만으로 내용을 전달하는 연극은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C9","difficulty":1,"kind":"sa","stem":"대사 없이 몸짓과 표정만으로 내용을 전달하는 연극은 무엇인가요? 세 글자로 쓰세요.","answer":["무언극"],"explanation":["말이 없어요.","무◯◯이에요.","무언극이에요."],"asset":{"type":"passage","lines":["무언극은 대사 없이 몸짓과 표정만으로 내용을 전달하는 연극이에요.","사는 곳 · 하는 일 · 여가 생활에서 몸짓을 하나씩 골라 짜요.","말을 하지 않으니 어떤 표정과 몸짓을 할지가 중요해요."],"title":"무언극으로 표현해요"},"mis":"SO4-2-u3-X26"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#3','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',1,'ox','auto','도시 사람들은 상점과 아파트가 함께 있는 건물에서 살기도 해요.',ARRAY['SO4-2-u3-X24']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C9","difficulty":1,"kind":"ox","stem":"도시 사람들은 상점과 아파트가 함께 있는 건물에서 살기도 해요.","answer":"O","reason_options":[{"t":"아래층은 상점, 위층은 집인 건물이 도시에 있기 때문에","correct":true},{"t":"도시 사람들은 모두 단독 주택에만 살기 때문에","mis":"SO4-2-u3-X24"}],"mis":"SO4-2-u3-X24","explanation":["사는 곳을 떠올려요.","여러 가지예요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#4','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',1,'mc','auto','도시에 사는 사람들이 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X24']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C9","difficulty":1,"kind":"mc","stem":"도시에 사는 사람들이 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"회사나 공장에서 물건을 만들거나 서비스를 제공해요","correct":true},{"t":"양식장에서 김을 길러요","mis":"SO4-2-u3-X24"},{"t":"목장에서 양을 길러요","mis":"SO4-2-u3-X24"},{"t":"산비탈에서 약초를 캐요","mis":"SO4-2-u3-X24"}],"explanation":["둘째·셋째 줄이에요.","회사·공장·은행이에요.","그것을 골라요."],"asset":{"type":"passage","lines":["아침 — 아파트에서 나와 지하철을 타고 회사로 가요.","낮 — 사무실에서 회의를 하거나 공장에서 자동차를 조립해요.","낮 — 은행이나 우체국에서 손님을 도와요.","저녁·주말 — 미술관에 가거나 공원에서 자전거를 타요."],"title":"도시에 사는 사람들의 하루(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#5','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',2,'mc','auto','출근할 때 지하철을 이용하면 좋은 점은 무엇인가요?',ARRAY['SO4-2-u3-X25']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C9","difficulty":2,"kind":"mc","stem":"출근할 때 지하철을 이용하면 좋은 점은 무엇인가요?","options":[{"t":"막히지 않아 예상한 시간에 도착할 수 있어요","correct":true},{"t":"출근 시간에도 늘 텅 비어 있어요","mis":"SO4-2-u3-X25"},{"t":"도로가 막힐까 봐 걱정해야 해요","mis":"SO4-2-u3-X25"},{"t":"지하철은 일터에 갈 수 없어요","mis":"SO4-2-u3-X25"}],"explanation":["지하철은 땅 밑으로 가요.","막히지 않아요.","시간을 맞춰요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#6','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',2,'match','auto','도시 사람들의 하루와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u3-C9","difficulty":2,"kind":"match","stem":"도시 사람들의 하루와 하는 일을 알맞게 이으세요.","pairs":[{"l":"사무실","r":"회의를 준비해요"},{"l":"공장","r":"자동차를 조립해요"},{"l":"은행이나 우체국","r":"서비스를 제공해요"},{"l":"미술관","r":"그림을 감상해요"}],"mis":"SO4-2-u3-X24","explanation":["사무실은 회의예요.","공장은 조립이에요.","은행과 미술관도 이어요."],"asset":{"type":"passage","lines":["아침 — 아파트에서 나와 지하철을 타고 회사로 가요.","낮 — 사무실에서 회의를 하거나 공장에서 자동차를 조립해요.","낮 — 은행이나 우체국에서 손님을 도와요.","저녁·주말 — 미술관에 가거나 공원에서 자전거를 타요."],"title":"도시에 사는 사람들의 하루(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#7','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',2,'ox','auto','지하철은 막히지 않으니 출근 시간에도 언제나 한가해요.',ARRAY['SO4-2-u3-X25']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C9","difficulty":2,"kind":"ox","stem":"지하철은 막히지 않으니 출근 시간에도 언제나 한가해요.","answer":"X","reason_options":[{"t":"막히지는 않지만 출근 시간에는 타는 사람이 많기 때문에","correct":true},{"t":"지하철에는 아무도 타지 않기 때문에","mis":"SO4-2-u3-X25"}],"mis":"SO4-2-u3-X25","explanation":["막히지는 않아요.","그런데 사람이 많아요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#8','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',2,'mc','auto','도시 사람들이 퇴근한 뒤나 주말에 즐기는 여가 생활로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X25']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C9","difficulty":2,"kind":"mc","stem":"도시 사람들이 퇴근한 뒤나 주말에 즐기는 여가 생활로 알맞은 것은 무엇인가요?","options":[{"t":"공원에서 자전거를 타요","correct":true},{"t":"회사에서 회의를 해요","mis":"SO4-2-u3-X25"},{"t":"공장에서 자동차를 조립해요","mis":"SO4-2-u3-X25"},{"t":"은행에서 손님을 도와요","mis":"SO4-2-u3-X25"}],"explanation":["넷째 줄을 봐요.","쉬는 때예요.","자전거를 타요."],"asset":{"type":"passage","lines":["아침 — 아파트에서 나와 지하철을 타고 회사로 가요.","낮 — 사무실에서 회의를 하거나 공장에서 자동차를 조립해요.","낮 — 은행이나 우체국에서 손님을 도와요.","저녁·주말 — 미술관에 가거나 공원에서 자전거를 타요."],"title":"도시에 사는 사람들의 하루(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#9','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',2,'blank','auto','무언극은 대사가 없으니 어떤 (    )과 몸짓을 할지가 중요해요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u3-X26']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C9","difficulty":2,"kind":"blank","stem":"무언극은 대사가 없으니 어떤 (    )과 몸짓을 할지가 중요해요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"표정","correct":true},{"t":"노래","mis":"SO4-2-u3-X26"},{"t":"대사","mis":"SO4-2-u3-X26"},{"t":"글씨","mis":"SO4-2-u3-X26"}],"explanation":["셋째 줄을 읽어요.","얼굴로 나타내요.","표정이에요."],"asset":{"type":"passage","lines":["무언극은 대사 없이 몸짓과 표정만으로 내용을 전달하는 연극이에요.","사는 곳 · 하는 일 · 여가 생활에서 몸짓을 하나씩 골라 짜요.","말을 하지 않으니 어떤 표정과 몸짓을 할지가 중요해요."],"title":"무언극으로 표현해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_basic#10','soc',4,2,'u3','L09','g4_2_soc_u3_L09_basic','lesson_basic','SO4-2-u3-C9',3,'mc','auto','무언극을 말없이 발표했는데도 무엇을 표현했는지 알 수 있었던 까닭은 무엇인가요?',ARRAY['SO4-2-u3-X26']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"mc","stem":"무언극을 말없이 발표했는데도 무엇을 표현했는지 알 수 있었던 까닭은 무엇인가요?","options":[{"t":"몸짓과 표정만으로도 내용을 전달할 수 있기 때문이에요","correct":true},{"t":"몰래 대사를 했기 때문이에요","mis":"SO4-2-u3-X26"},{"t":"정답이 미리 적혀 있었기 때문이에요","mis":"SO4-2-u3-X26"},{"t":"무언극은 글자를 보여 주기 때문이에요","mis":"SO4-2-u3-X26"}],"explanation":["말이 없었어요.","몸짓이 있었어요.","그것으로 알아요."],"asset":{"type":"passage","lines":["무언극은 대사 없이 몸짓과 표정만으로 내용을 전달하는 연극이에요.","사는 곳 · 하는 일 · 여가 생활에서 몸짓을 하나씩 골라 짜요.","말을 하지 않으니 어떤 표정과 몸짓을 할지가 중요해요."],"title":"무언극으로 표현해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#1','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',2,'mc','auto','무언극을 짤 때 몸짓을 고르는 세 갈래는 무엇인가요?',ARRAY['SO4-2-u3-X26','SO4-2-u3-X22']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C9","difficulty":2,"kind":"mc","stem":"무언극을 짤 때 몸짓을 고르는 세 갈래는 무엇인가요?","options":[{"t":"사는 곳 · 하는 일 · 여가 생활","correct":true},{"t":"산 · 들 · 바다","mis":"SO4-2-u3-X26"},{"t":"인구 · 산업 · 교통","mis":"SO4-2-u3-X22"},{"t":"좋은 점 · 문제점 · 노력","mis":"SO4-2-u3-X26"}],"explanation":["둘째 줄을 읽어요.","도시 사람의 생활이에요.","세 갈래예요."],"asset":{"type":"passage","lines":["무언극은 대사 없이 몸짓과 표정만으로 내용을 전달하는 연극이에요.","사는 곳 · 하는 일 · 여가 생활에서 몸짓을 하나씩 골라 짜요.","말을 하지 않으니 어떤 표정과 몸짓을 할지가 중요해요."],"title":"무언극으로 표현해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#2','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',2,'ox','auto','단독 주택은 관리는 어렵지만 우리 가족만 살아 마음이 편하다고 말하는 사람도 있어요.',ARRAY['SO4-2-u3-X25']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C9","difficulty":2,"kind":"ox","stem":"단독 주택은 관리는 어렵지만 우리 가족만 살아 마음이 편하다고 말하는 사람도 있어요.","answer":"O","reason_options":[{"t":"사는 곳마다 좋은 점과 불편한 점이 함께 있기 때문에","correct":true},{"t":"단독 주택은 관리가 가장 쉽기 때문에","mis":"SO4-2-u3-X25"}],"mis":"SO4-2-u3-X25","explanation":["관리는 어려워요.","그래도 편해요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#3','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',3,'error','auto','도시 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X24','SO4-2-u3-X25']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"error","stem":"도시 사람들의 생활을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「도시 사람들은 대부분 양식장에서 김을 길러.」","correct":true,"mis_target":"SO4-2-u3-X24"},{"t":"친구 나 — 「회사나 공장에서 일해.」","mis":"SO4-2-u3-X24"},{"t":"친구 다 — 「주말에 미술관에 가기도 해.」","mis":"SO4-2-u3-X25"}],"explanation":["도시에서 하는 일이에요.","양식장은 바다예요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["아침 — 아파트에서 나와 지하철을 타고 회사로 가요.","낮 — 사무실에서 회의를 하거나 공장에서 자동차를 조립해요.","낮 — 은행이나 우체국에서 손님을 도와요.","저녁·주말 — 미술관에 가거나 공원에서 자전거를 타요."],"title":"도시에 사는 사람들의 하루(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#4','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',3,'mc','auto','자동차로 출근하는 사람이 걱정하는 점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X25']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"mc","stem":"자동차로 출근하는 사람이 걱정하는 점으로 알맞은 것은 무엇인가요?","options":[{"t":"도로가 막혀 늦을까 봐 걱정해요","correct":true},{"t":"땅 밑이라 하늘을 못 볼까 봐 걱정해요","mis":"SO4-2-u3-X25"},{"t":"배가 늦게 올까 봐 걱정해요","mis":"SO4-2-u3-X25"},{"t":"자동차는 걱정할 점이 하나도 없어요","mis":"SO4-2-u3-X25"}],"explanation":["자동차는 도로로 가요.","도로가 막혀요.","늦을까 봐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#5','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',3,'mc','auto','무언극으로 「은행에서 손님을 돕는 모습」을 나타낼 때 가장 알맞은 몸짓은 무엇인가요?',ARRAY['SO4-2-u3-X26']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"mc","stem":"무언극으로 「은행에서 손님을 돕는 모습」을 나타낼 때 가장 알맞은 몸짓은 무엇인가요?","options":[{"t":"웃는 얼굴로 손님에게 종이를 건네고 고개를 끄덕여요","correct":true},{"t":"「어서 오세요」라고 크게 말해요","mis":"SO4-2-u3-X26"},{"t":"칠판에 「은행」이라고 써요","mis":"SO4-2-u3-X26"},{"t":"아무 몸짓도 하지 않고 서 있어요","mis":"SO4-2-u3-X26"}],"explanation":["말과 글이 없어요.","몸짓과 표정이에요.","그것을 골라요."],"asset":{"type":"passage","lines":["무언극은 대사 없이 몸짓과 표정만으로 내용을 전달하는 연극이에요.","사는 곳 · 하는 일 · 여가 생활에서 몸짓을 하나씩 골라 짜요.","말을 하지 않으니 어떤 표정과 몸짓을 할지가 중요해요."],"title":"무언극으로 표현해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#6','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',3,'ox','auto','스마트 도시 전문가는 도시의 문제를 분석해 해결 방법을 찾기도 해요.',ARRAY['SO4-2-u3-X24']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"ox","stem":"스마트 도시 전문가는 도시의 문제를 분석해 해결 방법을 찾기도 해요.","answer":"O","reason_options":[{"t":"정보 통신 기술로 모은 정보로 도시를 더 살기 좋게 만들기 때문에","correct":true},{"t":"스마트 도시 전문가는 도시와 관계없는 일만 하기 때문에","mis":"SO4-2-u3-X24"}],"mis":"SO4-2-u3-X24","explanation":["둘째 줄을 읽어요.","문제를 분석해요.","그래서 O예요."],"asset":{"type":"passage","lines":["정보 통신 기술로 모은 정보로 똑똑하고 효율적인 도시를 만들어요.","도시의 문제를 분석해 해결 방법을 찾아요.","새로운 도시를 생각해 내는 창의력, 깊이 파고드는 집중력이 필요해요."],"title":"스마트 도시 전문가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#7','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',3,'mc','auto','스마트 도시 전문가에게 필요한 힘으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X24','SO4-2-u3-X26']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"mc","stem":"스마트 도시 전문가에게 필요한 힘으로 알맞은 것은 무엇인가요?","options":[{"t":"새 도시를 생각해 내는 창의력과 깊이 파고드는 집중력","correct":true},{"t":"무거운 짐을 드는 힘","mis":"SO4-2-u3-X24"},{"t":"물고기를 잡는 솜씨","mis":"SO4-2-u3-X24"},{"t":"대사를 크게 외치는 목소리","mis":"SO4-2-u3-X26"}],"explanation":["셋째 줄을 읽어요.","두 가지 힘이에요.","창의력과 집중력이에요."],"asset":{"type":"passage","lines":["정보 통신 기술로 모은 정보로 똑똑하고 효율적인 도시를 만들어요.","도시의 문제를 분석해 해결 방법을 찾아요.","새로운 도시를 생각해 내는 창의력, 깊이 파고드는 집중력이 필요해요."],"title":"스마트 도시 전문가"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#8','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',4,'mc','auto','도시에 사는 사람들의 하루를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X25','SO4-2-u3-X24']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C9","difficulty":4,"kind":"mc","stem":"도시에 사는 사람들의 하루를 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"편리한 교통으로 일터에 가서 여러 가지 일을 하고, 쉬는 때에는 다양한 여가 생활을 즐겨요","correct":true},{"t":"도시 사람들은 일만 하고 쉬지 않아요","mis":"SO4-2-u3-X25"},{"t":"도시 사람들은 주로 농사를 지어요","mis":"SO4-2-u3-X24"},{"t":"도시 사람들은 교통을 쓰지 않아요","mis":"SO4-2-u3-X25"}],"explanation":["아침은 출근이에요.","낮은 일이에요.","저녁은 여가예요."],"asset":{"type":"passage","lines":["아침 — 아파트에서 나와 지하철을 타고 회사로 가요.","낮 — 사무실에서 회의를 하거나 공장에서 자동차를 조립해요.","낮 — 은행이나 우체국에서 손님을 도와요.","저녁·주말 — 미술관에 가거나 공원에서 자전거를 타요."],"title":"도시에 사는 사람들의 하루(내 말로)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#9','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',4,'mc','auto','도시 사람들의 생활 모습과 산이 많은 지역 사람들의 생활 모습을 바르게 견준 것은 무엇인가요?',ARRAY['SO4-2-u3-X24']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C9","difficulty":4,"kind":"mc","stem":"도시 사람들의 생활 모습과 산이 많은 지역 사람들의 생활 모습을 바르게 견준 것은 무엇인가요?","options":[{"t":"도시 사람은 회사나 공장에서, 산이 많은 지역 사람은 산비탈 밭이나 목장에서 일하기도 해요","correct":true},{"t":"두 곳 사람 모두 양식장에서 일해요","mis":"SO4-2-u3-X24"},{"t":"도시 사람은 목장에서, 산 지역 사람은 은행에서 일해요","mis":"SO4-2-u3-X24"},{"t":"두 곳 사람의 생활은 똑같아요","mis":"SO4-2-u3-X24"}],"explanation":["도시를 떠올려요.","산이 많은 지역을 떠올려요.","견주어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L09_challenge#10','soc',4,2,'u3','L09','g4_2_soc_u3_L09_challenge','lesson_challenge','SO4-2-u3-C9',4,'essay','teacher','도시에 사는 사람의 「사는 곳」, 「하는 일」, 「여가 생활」에서 하나씩 골라 무언극을 짜세요. 각 장면의 몸짓을 한 문장씩 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C9","difficulty":4,"kind":"essay","stem":"도시에 사는 사람의 「사는 곳」, 「하는 일」, 「여가 생활」에서 하나씩 골라 무언극을 짜세요. 각 장면의 몸짓을 한 문장씩 쓰세요.","answer_guide":{"answer":"예: 사는 곳 — 아파트 엘리베이터 단추를 누르는 몸짓을 해요. 하는 일 — 공장에서 공구로 자동차를 조립하는 몸짓을 해요. 여가 생활 — 공원에서 자전거 손잡이를 잡고 페달을 밟는 몸짓을 해요.","scoring_points":["세 갈래에서 하나씩 골랐는가","말이 아니라 몸짓으로 썼는가","도시 생활에 맞는 장면인가"]},"explanation":["셋을 골라요.","몸짓을 써요.","말은 빼요."],"asset":{"type":"passage","lines":["무언극은 대사 없이 몸짓과 표정만으로 내용을 전달하는 연극이에요.","사는 곳 · 하는 일 · 여가 생활에서 몸짓을 하나씩 골라 짜요.","말을 하지 않으니 어떤 표정과 몸짓을 할지가 중요해요."],"title":"무언극으로 표현해요"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#1','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',1,'mc','auto','도시에 산업이 발달하면 어떤 점이 좋은가요?',ARRAY['SO4-2-u3-X27']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C10","difficulty":1,"kind":"mc","stem":"도시에 산업이 발달하면 어떤 점이 좋은가요?","options":[{"t":"다양한 일자리가 있어요","correct":true},{"t":"집값이 비싸져요","mis":"SO4-2-u3-X27"},{"t":"쓰레기가 늘어요","mis":"SO4-2-u3-X27"},{"t":"교통이 혼잡해져요","mis":"SO4-2-u3-X27"}],"explanation":["산업 줄을 봐요.","앞쪽이 좋은 점이에요.","일자리예요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#2','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',1,'sa','auto','바람이 다니는 길을 따라 나무를 심어 외곽 숲의 맑은 공기를 끌어들이는 노력은 바람길 ○이에요. ○에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C10","difficulty":1,"kind":"sa","stem":"바람이 다니는 길을 따라 나무를 심어 외곽 숲의 맑은 공기를 끌어들이는 노력은 바람길 ○이에요. ○에 알맞은 한 글자를 쓰세요.","answer":["숲"],"explanation":["나무를 심었어요.","바람길 ◯이에요.","숲이에요."],"asset":{"type":"passage","lines":["기사 가 — ◇◇시는 바람이 다니는 길을 따라 나무를 심었어요.","기사 가 — 외곽 숲의 맑은 공기가 들어와 미세 먼지가 줄었어요.","기사 나 — 한 달 동안 생활 쓰레기를 최소한으로 줄이는 캠페인을 열어요.","기사 나 — 주민들은 물건을 다시 쓰는 재사용을 실천해요."],"title":"도시 문제를 해결하려는 노력(지어낸 기사)"},"mis":"SO4-2-u3-X29"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#3','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',1,'ox','auto','도시에는 공공 기관, 영화관, 병원 같은 편의 시설이 많아요.',ARRAY['SO4-2-u3-X27']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C10","difficulty":1,"kind":"ox","stem":"도시에는 공공 기관, 영화관, 병원 같은 편의 시설이 많아요.","answer":"O","reason_options":[{"t":"많은 사람이 모여 살아 생활에 필요한 시설이 많이 생겼기 때문에","correct":true},{"t":"도시에는 편의 시설이 생길 수 없기 때문에","mis":"SO4-2-u3-X27"}],"mis":"SO4-2-u3-X27","explanation":["편의 시설 줄을 봐요.","앞쪽이 좋은 점이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#4','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',1,'mc','auto','도시 생활의 문제점으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X27']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C10","difficulty":1,"kind":"mc","stem":"도시 생활의 문제점으로 알맞은 것은 무엇인가요?","options":[{"t":"특정 시간에 자동차가 몰려 교통이 혼잡해요","correct":true},{"t":"다양한 일자리가 있어요","mis":"SO4-2-u3-X27"},{"t":"쾌적한 새 아파트가 생겨요","mis":"SO4-2-u3-X27"},{"t":"이동이 빠르고 편리해요","mis":"SO4-2-u3-X27"}],"explanation":["뒤쪽을 봐요.","불편한 점이에요.","교통 혼잡이에요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#5','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',2,'match','auto','도시 생활의 갈래와 문제점을 알맞게 이으세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"match","stem":"도시 생활의 갈래와 문제점을 알맞게 이으세요.","pairs":[{"l":"교통","r":"주차할 공간이 부족해요"},{"l":"주택","r":"집값이 비싸고 낡은 집이 많아요"},{"l":"산업","r":"대기·수질·토양 오염이 생겨요"},{"l":"편의 시설","r":"버린 쓰레기의 양이 늘어요"}],"mis":"SO4-2-u3-X28","explanation":["교통은 주차예요.","주택은 집값이에요.","산업과 편의 시설도 이어요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#6','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',2,'mc','auto','기사 나의 노력은 어떤 도시 문제를 해결하려는 것인가요?',ARRAY['SO4-2-u3-X29']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"mc","stem":"기사 나의 노력은 어떤 도시 문제를 해결하려는 것인가요?","options":[{"t":"생활 쓰레기가 늘어나는 문제","correct":true},{"t":"미세 먼지가 많은 문제","mis":"SO4-2-u3-X29"},{"t":"집값이 비싼 문제","mis":"SO4-2-u3-X29"},{"t":"지하철이 붐비는 문제","mis":"SO4-2-u3-X29"}],"explanation":["기사 나를 읽어요.","쓰레기를 줄여요.","쓰레기 문제예요."],"asset":{"type":"passage","lines":["기사 가 — ◇◇시는 바람이 다니는 길을 따라 나무를 심었어요.","기사 가 — 외곽 숲의 맑은 공기가 들어와 미세 먼지가 줄었어요.","기사 나 — 한 달 동안 생활 쓰레기를 최소한으로 줄이는 캠페인을 열어요.","기사 나 — 주민들은 물건을 다시 쓰는 재사용을 실천해요."],"title":"도시 문제를 해결하려는 노력(지어낸 기사)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#7','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',2,'ox','auto','도시 생활에는 좋은 점만 있어요.',ARRAY['SO4-2-u3-X27']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"ox","stem":"도시 생활에는 좋은 점만 있어요.","answer":"X","reason_options":[{"t":"교통 혼잡, 비싼 집값, 환경 오염, 쓰레기 같은 문제점도 있기 때문에","correct":true},{"t":"도시는 모든 것이 편리하기 때문에","mis":"SO4-2-u3-X27"}],"mis":"SO4-2-u3-X27","explanation":["뒤쪽을 봐요.","문제점이 있어요.","그래서 X예요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#8','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',2,'mc','auto','도시에 새 주택이나 아파트가 지어지면 좋은 점은 무엇인가요?',ARRAY['SO4-2-u3-X28']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"mc","stem":"도시에 새 주택이나 아파트가 지어지면 좋은 점은 무엇인가요?","options":[{"t":"쾌적한 주거 공간이 생겨요","correct":true},{"t":"낡은 주택이 많아져요","mis":"SO4-2-u3-X28"},{"t":"집값이 비싸져요","mis":"SO4-2-u3-X28"},{"t":"쓰레기 양이 늘어요","mis":"SO4-2-u3-X28"}],"explanation":["주택 줄을 봐요.","앞쪽이에요.","쾌적한 집이에요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#9','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',2,'blank','auto','도시 생활에 문제점이 생기는 것은 좁은 지역에 많은 (    )이 모여 살기 때문이에요. 빈칸에 알맞은 말은 무엇인가요?',ARRAY['SO4-2-u3-X28']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"blank","stem":"도시 생활에 문제점이 생기는 것은 좁은 지역에 많은 (    )이 모여 살기 때문이에요. 빈칸에 알맞은 말은 무엇인가요?","options":[{"t":"사람","correct":true},{"t":"나무","mis":"SO4-2-u3-X28"},{"t":"바람","mis":"SO4-2-u3-X28"},{"t":"강물","mis":"SO4-2-u3-X28"}],"explanation":["도시는 좁아요.","누가 모였나요?","사람이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_basic#10','soc',4,2,'u3','L10','g4_2_soc_u3_L10_basic','lesson_basic','SO4-2-u3-C10',3,'mc','auto','기사 가의 바람길 숲은 어떤 문제를 줄였나요?',ARRAY['SO4-2-u3-X29']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"mc","stem":"기사 가의 바람길 숲은 어떤 문제를 줄였나요?","options":[{"t":"미세 먼지와 대기의 오염 물질","correct":true},{"t":"생활 쓰레기","mis":"SO4-2-u3-X29"},{"t":"주차 공간 부족","mis":"SO4-2-u3-X29"},{"t":"낡은 주택","mis":"SO4-2-u3-X29"}],"explanation":["맑은 공기가 들어와요.","공기 문제예요.","미세 먼지예요."],"asset":{"type":"passage","lines":["기사 가 — ◇◇시는 바람이 다니는 길을 따라 나무를 심었어요.","기사 가 — 외곽 숲의 맑은 공기가 들어와 미세 먼지가 줄었어요.","기사 나 — 한 달 동안 생활 쓰레기를 최소한으로 줄이는 캠페인을 열어요.","기사 나 — 주민들은 물건을 다시 쓰는 재사용을 실천해요."],"title":"도시 문제를 해결하려는 노력(지어낸 기사)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#1','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',2,'mc','auto','도시 생활의 좋은 점과 문제점 표에서 알 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u3-X27','SO4-2-u3-X28']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"mc","stem":"도시 생활의 좋은 점과 문제점 표에서 알 수 있는 것은 무엇인가요?","options":[{"t":"네 갈래 모두 좋은 점과 문제점이 나란히 있어요","correct":true},{"t":"교통에는 좋은 점만 있어요","mis":"SO4-2-u3-X27"},{"t":"주택에는 문제점만 있어요","mis":"SO4-2-u3-X27"},{"t":"좋은 점과 문제점은 서로 다른 갈래에만 있어요","mis":"SO4-2-u3-X28"}],"explanation":["줄을 하나씩 봐요.","앞뒤가 다 있어요.","네 갈래 모두예요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#2','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',2,'ox','auto','도로가 놓여 편리해도 좁은 곳에 자동차가 한꺼번에 몰리면 교통 혼잡이라는 문제점이 될 수 있어요.',ARRAY['SO4-2-u3-X28']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"ox","stem":"도로가 놓여 편리해도 좁은 곳에 자동차가 한꺼번에 몰리면 교통 혼잡이라는 문제점이 될 수 있어요.","answer":"O","reason_options":[{"t":"좋은 점도 상황이 달라지면 문제점이 되기도 하기 때문에","correct":true},{"t":"도로는 언제나 좋은 점만 주기 때문에","mis":"SO4-2-u3-X28"}],"mis":"SO4-2-u3-X28","explanation":["도로는 편리해요.","그런데 몰리면요?","그래서 O예요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#3','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',3,'error','auto','도시 문제와 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X29','SO4-2-u3-X27']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"error","stem":"도시 문제와 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「바람길 숲은 생활 쓰레기를 줄이려는 노력이야.」","correct":true,"mis_target":"SO4-2-u3-X29"},{"t":"친구 가 — 「쓰레기 줄이기 캠페인으로 재사용을 실천해.」","mis":"SO4-2-u3-X29"},{"t":"친구 다 — 「도시에는 좋은 점과 문제점이 함께 있어.」","mis":"SO4-2-u3-X27"}],"explanation":["바람길 숲은 무엇을 줄였나요?","공기 오염이에요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["기사 가 — ◇◇시는 바람이 다니는 길을 따라 나무를 심었어요.","기사 가 — 외곽 숲의 맑은 공기가 들어와 미세 먼지가 줄었어요.","기사 나 — 한 달 동안 생활 쓰레기를 최소한으로 줄이는 캠페인을 열어요.","기사 나 — 주민들은 물건을 다시 쓰는 재사용을 실천해요."],"title":"도시 문제를 해결하려는 노력(지어낸 기사)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#4','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',3,'mc','auto','캠페인 문구를 만드는 차례 ②에 들어갈 생각으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X29','SO4-2-u3-X27']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"mc","stem":"캠페인 문구를 만드는 차례 ②에 들어갈 생각으로 알맞은 것은 무엇인가요?","options":[{"t":"「쓰레기를 줄이려면 장바구니를 쓰면 좋겠어.」","correct":true},{"t":"「캠페인 문구는 길수록 좋아.」","mis":"SO4-2-u3-X29"},{"t":"「도시 문제는 하나도 없어.」","mis":"SO4-2-u3-X27"},{"t":"「문구를 먼저 정하고 문제는 나중에 골라.」","mis":"SO4-2-u3-X29"}],"explanation":["②는 할 일이에요.","문제를 줄이는 방법이에요.","장바구니예요."],"asset":{"type":"passage","lines":["① 풀고 싶은 도시 문제를 하나 골라요.","② 그 문제를 줄이려면 무엇을 하면 좋을지 적어요.","③ 짧고 기억에 남는 문구로 다듬어요."],"title":"캠페인 문구를 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#5','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',3,'mc','auto','「주택」 갈래의 좋은 점과 문제점을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-2-u3-X27','SO4-2-u3-X28']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"mc","stem":"「주택」 갈래의 좋은 점과 문제점을 바르게 말한 것은 무엇인가요?","options":[{"t":"새 아파트로 쾌적한 집이 생기지만, 집값이 비싸고 낡은 집도 많아요","correct":true},{"t":"주택에는 문제점이 없어요","mis":"SO4-2-u3-X27"},{"t":"집값이 싸고 낡은 집이 없어요","mis":"SO4-2-u3-X28"},{"t":"주택은 쓰레기와만 관련 있어요","mis":"SO4-2-u3-X28"}],"explanation":["주택 줄을 봐요.","앞은 좋은 점이에요.","뒤는 문제점이에요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#6','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',3,'ox','auto','쓰레기 줄이기 캠페인에서 물건을 다시 쓰는 것도 쓰레기를 줄이는 노력이에요.',ARRAY['SO4-2-u3-X29']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"ox","stem":"쓰레기 줄이기 캠페인에서 물건을 다시 쓰는 것도 쓰레기를 줄이는 노력이에요.","answer":"O","reason_options":[{"t":"다시 쓰면 버리는 물건이 줄어들기 때문에","correct":true},{"t":"다시 쓰면 쓰레기가 더 늘기 때문에","mis":"SO4-2-u3-X29"}],"mis":"SO4-2-u3-X29","explanation":["기사 나를 읽어요.","재사용이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["기사 가 — ◇◇시는 바람이 다니는 길을 따라 나무를 심었어요.","기사 가 — 외곽 숲의 맑은 공기가 들어와 미세 먼지가 줄었어요.","기사 나 — 한 달 동안 생활 쓰레기를 최소한으로 줄이는 캠페인을 열어요.","기사 나 — 주민들은 물건을 다시 쓰는 재사용을 실천해요."],"title":"도시 문제를 해결하려는 노력(지어낸 기사)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#7','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',3,'mc','auto','캠페인 문구로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X29','SO4-2-u3-X27']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"mc","stem":"캠페인 문구로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「한 번 더 쓰면 도시가 가벼워져요!」","correct":true},{"t":"「쓰레기는 아무 데나 버려도 돼요!」","mis":"SO4-2-u3-X29"},{"t":"「도시는 문제가 하나도 없어요!」","mis":"SO4-2-u3-X27"},{"t":"「길고 어려운 문장으로 쓴 문구」","mis":"SO4-2-u3-X29"}],"explanation":["짧아야 해요.","문제를 줄여요.","그것을 골라요."],"asset":{"type":"passage","lines":["① 풀고 싶은 도시 문제를 하나 골라요.","② 그 문제를 줄이려면 무엇을 하면 좋을지 적어요.","③ 짧고 기억에 남는 문구로 다듬어요."],"title":"캠페인 문구를 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#8','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',4,'mc','auto','표와 기사를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X29','SO4-2-u3-X27']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C10","difficulty":4,"kind":"mc","stem":"표와 기사를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"도시 생활에는 좋은 점과 문제점이 함께 있고, 사람들은 문제를 줄이려고 여러 노력을 해요","correct":true},{"t":"도시 문제는 그냥 두면 저절로 사라져요","mis":"SO4-2-u3-X29"},{"t":"도시 생활에는 문제점만 있어요","mis":"SO4-2-u3-X27"},{"t":"바람길 숲은 집값을 낮추는 노력이에요","mis":"SO4-2-u3-X29"}],"explanation":["표는 좋은 점과 문제점이에요.","기사는 노력이에요.","함께 보아요."],"asset":{"type":"passage","lines":["기사 가 — ◇◇시는 바람이 다니는 길을 따라 나무를 심었어요.","기사 가 — 외곽 숲의 맑은 공기가 들어와 미세 먼지가 줄었어요.","기사 나 — 한 달 동안 생활 쓰레기를 최소한으로 줄이는 캠페인을 열어요.","기사 나 — 주민들은 물건을 다시 쓰는 재사용을 실천해요."],"title":"도시 문제를 해결하려는 노력(지어낸 기사)"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#9','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',4,'mc','auto','도시 생활의 좋은 점이 문제점이 되기도 하는 까닭으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X28']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C10","difficulty":4,"kind":"mc","stem":"도시 생활의 좋은 점이 문제점이 되기도 하는 까닭으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"좁은 지역에 많은 사람이 모여 살아 같은 것도 지나치게 몰리기 때문이에요","correct":true},{"t":"도시에는 사람이 거의 살지 않기 때문이에요","mis":"SO4-2-u3-X28"},{"t":"좋은 점과 문제점은 아무 관계가 없기 때문이에요","mis":"SO4-2-u3-X28"},{"t":"도시에는 교통 시설이 없기 때문이에요","mis":"SO4-2-u3-X28"}],"explanation":["도시는 좁아요.","사람이 많아요.","지나치게 몰려요."],"asset":{"type":"passage","lines":["교통 — 이동이 빠르고 편리해요. / 특정 시간에 몹시 혼잡해요.","주택 — 쾌적한 새 아파트가 생겨요. / 집값이 비싸고 낡은 집도 많아요.","산업 — 다양한 일자리가 있어요. / 대기·수질·토양 오염이 생겨요.","편의 시설 — 병원과 영화관이 많아요. / 버린 쓰레기가 늘어요."],"title":"도시 생활의 좋은 점 / 문제점"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L10_challenge#10','soc',4,2,'u3','L10','g4_2_soc_u3_L10_challenge','lesson_challenge','SO4-2-u3-C10',4,'essay','teacher','도시 문제 하나를 골라 그 문제가 생기는 까닭을 쓰고, 캠페인 문구를 만드는 차례에 맞추어 문구 하나를 만드세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C10","difficulty":4,"kind":"essay","stem":"도시 문제 하나를 골라 그 문제가 생기는 까닭을 쓰고, 캠페인 문구를 만드는 차례에 맞추어 문구 하나를 만드세요.","answer_guide":{"answer":"예: 교통 혼잡 문제를 골랐어요. 출근 시간에 자동차가 한꺼번에 몰리기 때문이에요. 버스나 지하철을 타면 도로가 덜 막혀요. 문구는 「버스 타고 가면 도시가 숨을 쉬어요!」예요.","scoring_points":["도시 문제를 골랐는가","문제가 생기는 까닭을 썼는가","짧고 기억에 남는 문구를 만들었는가"]},"explanation":["문제를 골라요.","까닭을 써요.","문구를 만들어요."],"asset":{"type":"passage","lines":["① 풀고 싶은 도시 문제를 하나 골라요.","② 그 문제를 줄이려면 무엇을 하면 좋을지 적어요.","③ 짧고 기억에 남는 문구로 다듬어요."],"title":"캠페인 문구를 만드는 차례"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_basic#1','soc',4,2,'u3','L11','g4_2_soc_u3_L11_basic','lesson_basic','SO4-2-u3-C11',1,'mc','auto','도시의 특징을 알아볼 때 무엇을 살펴봤나요?',ARRAY['SO4-2-u3-X32']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C11","difficulty":1,"kind":"mc","stem":"도시의 특징을 알아볼 때 무엇을 살펴봤나요?","options":[{"t":"도시의 인구, 산업, 교통","correct":true},{"t":"산봉우리와 계곡","mis":"SO4-2-u3-X32"},{"t":"갯벌과 양식장","mis":"SO4-2-u3-X32"},{"t":"논과 저수지","mis":"SO4-2-u3-X32"}],"explanation":["②를 봐요.","세 가지예요.","인구·산업·교통이에요."],"asset":{"type":"passage","lines":["① 도시가 무엇인지","② 도시의 인구 · 산업 · 교통","③ 도시 사람들이 사는 집 · 하는 일 · 여가 생활","④ 도시 생활의 좋은 점과 문제점","⑤ 도시 문제를 해결하려는 노력"],"title":"「도시의 특징과 생활 모습」에서 공부한 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_basic#2','soc',4,2,'u3','L11','g4_2_soc_u3_L11_basic','lesson_basic','SO4-2-u3-C11',1,'sa','auto','이야기책을 만들 때 가장 먼저 도화지로 만드는 것은 작은 ○ 모양이에요. ○에 알맞은 한 글자를 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C11","difficulty":1,"kind":"sa","stem":"이야기책을 만들 때 가장 먼저 도화지로 만드는 것은 작은 ○ 모양이에요. ○에 알맞은 한 글자를 쓰세요.","answer":["책"],"explanation":["셋째 줄을 읽어요.","작은 ◯ 모양이에요.","책이에요."],"asset":{"type":"passage","lines":["배경 — 자연과 조화를 이룬 도시","주인공 — 그 도시에 사는 나","만드는 법 — 도화지로 작은 책 모양을 먼저 만들고, 글을 쓰고 그림을 그려요.","한 쪽에는 도시의 모습, 마주 보는 쪽에는 그 속에서 사는 나의 모습"],"title":"이야기책 만들기"},"mis":"SO4-2-u3-X30"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_basic#3','soc',4,2,'u3','L11','g4_2_soc_u3_L11_basic','lesson_basic','SO4-2-u3-C11',1,'ox','auto','「도시의 특징과 생활 모습」에서 공부한 내용은 그림이나 이야기책처럼 여러 방법으로 정리할 수 있어요.',ARRAY['SO4-2-u3-X30']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C11","difficulty":1,"kind":"ox","stem":"「도시의 특징과 생활 모습」에서 공부한 내용은 그림이나 이야기책처럼 여러 방법으로 정리할 수 있어요.","answer":"O","reason_options":[{"t":"정리하는 방법은 하나가 아니기 때문에","correct":true},{"t":"정리는 한 가지 방법으로만 해야 하기 때문에","mis":"SO4-2-u3-X30"}],"mis":"SO4-2-u3-X30","explanation":["방법을 떠올려요.","그림과 이야기책이에요.","그래서 O예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_basic#4','soc',4,2,'u3','L11','g4_2_soc_u3_L11_basic','lesson_basic','SO4-2-u3-C11',1,'mc','auto','도시 사람들의 생활 모습은 무엇을 통해 살펴봤나요?',ARRAY['SO4-2-u3-X32']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C11","difficulty":1,"kind":"mc","stem":"도시 사람들의 생활 모습은 무엇을 통해 살펴봤나요?","options":[{"t":"사는 집, 하는 일, 여가 생활","correct":true},{"t":"인구, 산업, 교통","mis":"SO4-2-u3-X32"},{"t":"좋은 점과 문제점","mis":"SO4-2-u3-X32"},{"t":"밤하늘 사진","mis":"SO4-2-u3-X32"}],"explanation":["③을 봐요.","생활 모습이에요.","집·일·여가예요."],"asset":{"type":"passage","lines":["① 도시가 무엇인지","② 도시의 인구 · 산업 · 교통","③ 도시 사람들이 사는 집 · 하는 일 · 여가 생활","④ 도시 생활의 좋은 점과 문제점","⑤ 도시 문제를 해결하려는 노력"],"title":"「도시의 특징과 생활 모습」에서 공부한 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_basic#5','soc',4,2,'u3','L11','g4_2_soc_u3_L11_basic','lesson_basic','SO4-2-u3-C11',2,'mc','auto','자연과 조화를 이룬 도시의 모습으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X31']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"mc","stem":"자연과 조화를 이룬 도시의 모습으로 알맞은 것은 무엇인가요?","options":[{"t":"햇빛으로 전기를 만드는 지붕과 가로등이 있어요","correct":true},{"t":"굴뚝마다 검은 연기가 나요","mis":"SO4-2-u3-X31"},{"t":"하천에 쓰레기가 떠다녀요","mis":"SO4-2-u3-X31"},{"t":"나무를 모두 베어 주차장을 만들었어요","mis":"SO4-2-u3-X31"}],"explanation":["㉯를 봐요.","자연을 해치지 않아요.","햇빛 에너지예요."],"asset":{"type":"passage","lines":["㉮ 체육관 · 영화관 · 도서관이 가까이 있어요.","㉯ 햇빛으로 전기를 만드는 지붕과 가로등이 있어요.","㉰ 나무가 우거지고 물이 흐르는 공원이 있어요."],"title":"내가 살고 싶은 도시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_basic#6','soc',4,2,'u3','L11','g4_2_soc_u3_L11_basic','lesson_basic','SO4-2-u3-C11',2,'match','auto','이야기책에 담을 것을 알맞게 이으세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"match","stem":"이야기책에 담을 것을 알맞게 이으세요.","pairs":[{"l":"배경","r":"자연과 조화를 이룬 도시"},{"l":"주인공","r":"그 도시에 사는 나"},{"l":"마주 보는 두 쪽","r":"도시의 모습과 그 속의 나"}],"mis":"SO4-2-u3-X30","explanation":["배경은 도시예요.","주인공은 나예요.","두 쪽을 나란히 이어요."],"asset":{"type":"passage","lines":["배경 — 자연과 조화를 이룬 도시","주인공 — 그 도시에 사는 나","만드는 법 — 도화지로 작은 책 모양을 먼저 만들고, 글을 쓰고 그림을 그려요.","한 쪽에는 도시의 모습, 마주 보는 쪽에는 그 속에서 사는 나의 모습"],"title":"이야기책 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_basic#7','soc',4,2,'u3','L11','g4_2_soc_u3_L11_basic','lesson_basic','SO4-2-u3-C11',2,'ox','auto','이야기책은 글과 그림을 먼저 그린 뒤에 책 모양을 만들어요.',ARRAY['SO4-2-u3-X30']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"ox","stem":"이야기책은 글과 그림을 먼저 그린 뒤에 책 모양을 만들어요.","answer":"X","reason_options":[{"t":"도화지로 작은 책 모양을 먼저 만든 다음 글을 쓰고 그림을 그리기 때문에","correct":true},{"t":"책 모양은 마지막에 아무렇게나 만들기 때문에","mis":"SO4-2-u3-X30"}],"mis":"SO4-2-u3-X30","explanation":["셋째 줄을 읽어요.","책 모양이 먼저예요.","그래서 X예요."],"asset":{"type":"passage","lines":["배경 — 자연과 조화를 이룬 도시","주인공 — 그 도시에 사는 나","만드는 법 — 도화지로 작은 책 모양을 먼저 만들고, 글을 쓰고 그림을 그려요.","한 쪽에는 도시의 모습, 마주 보는 쪽에는 그 속에서 사는 나의 모습"],"title":"이야기책 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_basic#8','soc',4,2,'u3','L11','g4_2_soc_u3_L11_basic','lesson_basic','SO4-2-u3-C11',2,'mc','auto','도시 그리기로 정리할 때 하는 일로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X31','SO4-2-u3-X30']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"mc","stem":"도시 그리기로 정리할 때 하는 일로 알맞은 것은 무엇인가요?","options":[{"t":"살고 싶은 도시를 상상하고 만들고 싶은 시설을 정해 도시의 특징이 드러나게 그려요","correct":true},{"t":"산과 바다만 그리고 시설은 빼요","mis":"SO4-2-u3-X31"},{"t":"공부한 내용과 관계없는 그림을 그려요","mis":"SO4-2-u3-X30"},{"t":"친구 그림을 그대로 따라 그려요","mis":"SO4-2-u3-X30"}],"explanation":["살고 싶은 도시예요.","시설을 정해요.","특징이 드러나요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
