INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_basic#10','soc',4,2,'u3','L11','g4_2_soc_u3_L11_basic','lesson_basic','SO4-2-u3-C11',3,'mc','auto','「도시의 특징과 생활 모습」에서 공부한 것을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-2-u3-X27','SO4-2-u3-X32']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C11","difficulty":3,"kind":"mc","stem":"「도시의 특징과 생활 모습」에서 공부한 것을 바르게 말한 것은 무엇인가요?","options":[{"t":"도시 생활에는 좋은 점과 문제점이 있어 문제를 해결하려는 노력도 함께 살펴봤어요","correct":true},{"t":"도시 생활에는 좋은 점만 있다고 배웠어요","mis":"SO4-2-u3-X27"},{"t":"산과 들과 바다의 특징만 배웠어요","mis":"SO4-2-u3-X32"},{"t":"도시의 인구만 살펴봤어요","mis":"SO4-2-u3-X32"}],"explanation":["④와 ⑤를 봐요.","좋은 점과 문제점이에요.","노력도 있어요."],"asset":{"type":"passage","lines":["① 도시가 무엇인지","② 도시의 인구 · 산업 · 교통","③ 도시 사람들이 사는 집 · 하는 일 · 여가 생활","④ 도시 생활의 좋은 점과 문제점","⑤ 도시 문제를 해결하려는 노력"],"title":"「도시의 특징과 생활 모습」에서 공부한 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#1','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',2,'mc','auto','내가 살고 싶은 도시 ㉮~㉰ 가운데 「자연을 해치지 않는 에너지를 쓰는 도시」는 무엇인가요?',ARRAY['SO4-2-u3-X31']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"mc","stem":"내가 살고 싶은 도시 ㉮~㉰ 가운데 「자연을 해치지 않는 에너지를 쓰는 도시」는 무엇인가요?","options":[{"t":"㉯","correct":true},{"t":"㉮","mis":"SO4-2-u3-X31"},{"t":"㉰","mis":"SO4-2-u3-X31"},{"t":"셋 다 아니에요","mis":"SO4-2-u3-X31"}],"explanation":["에너지를 찾아요.","햇빛으로 전기를 만들어요.","㉯예요."],"asset":{"type":"passage","lines":["㉮ 체육관 · 영화관 · 도서관이 가까이 있어요.","㉯ 햇빛으로 전기를 만드는 지붕과 가로등이 있어요.","㉰ 나무가 우거지고 물이 흐르는 공원이 있어요."],"title":"내가 살고 싶은 도시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#2','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',2,'ox','auto','이야기책의 마주 보는 두 쪽에 도시의 모습만 두 장 놓아도 이야기가 이어져요.',ARRAY['SO4-2-u3-X30']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"ox","stem":"이야기책의 마주 보는 두 쪽에 도시의 모습만 두 장 놓아도 이야기가 이어져요.","answer":"X","reason_options":[{"t":"도시의 모습과 그 속에서 사는 나의 모습이 마주 놓여야 이야기가 서기 때문에","correct":true},{"t":"같은 갈래끼리 놓아야 이야기가 이어지기 때문에","mis":"SO4-2-u3-X30"}],"mis":"SO4-2-u3-X30","explanation":["넷째 줄을 읽어요.","도시와 나예요.","그래서 X예요."],"asset":{"type":"passage","lines":["배경 — 자연과 조화를 이룬 도시","주인공 — 그 도시에 사는 나","만드는 법 — 도화지로 작은 책 모양을 먼저 만들고, 글을 쓰고 그림을 그려요.","한 쪽에는 도시의 모습, 마주 보는 쪽에는 그 속에서 사는 나의 모습"],"title":"이야기책 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#3','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',3,'error','auto','「도시의 특징과 생활 모습」을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X30','SO4-2-u3-X31']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C11","difficulty":3,"kind":"error","stem":"「도시의 특징과 생활 모습」을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「이야기책의 주인공은 꼭 유명한 사람이어야 해.」","correct":true,"mis_target":"SO4-2-u3-X30"},{"t":"친구 가 — 「배경은 자연과 조화를 이룬 도시야.」","mis":"SO4-2-u3-X31"},{"t":"친구 나 — 「도화지로 책 모양을 먼저 만들어.」","mis":"SO4-2-u3-X30"}],"explanation":["주인공은 누구였나요?","그 도시에 사는 나예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["배경 — 자연과 조화를 이룬 도시","주인공 — 그 도시에 사는 나","만드는 법 — 도화지로 작은 책 모양을 먼저 만들고, 글을 쓰고 그림을 그려요.","한 쪽에는 도시의 모습, 마주 보는 쪽에는 그 속에서 사는 나의 모습"],"title":"이야기책 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#4','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',3,'mc','auto','도시 그리기로 「도시의 특징」이 잘 드러나게 하려면 무엇을 그려 넣으면 좋을까요?',ARRAY['SO4-2-u3-X32']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C11","difficulty":3,"kind":"mc","stem":"도시 그리기로 「도시의 특징」이 잘 드러나게 하려면 무엇을 그려 넣으면 좋을까요?","options":[{"t":"많은 사람이 사는 아파트와 지하철역, 회사와 시장","correct":true},{"t":"사람이 없는 들판 하나","mis":"SO4-2-u3-X32"},{"t":"바닷속 물고기만","mis":"SO4-2-u3-X32"},{"t":"산봉우리 하나만","mis":"SO4-2-u3-X32"}],"explanation":["도시의 특징이에요.","인구·교통·산업이에요.","그것을 그려요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#5','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',3,'mc','auto','공부한 것 ①~⑤를 이야기책에 담을 때 「⑤ 해결 노력」과 이어 쓸 장면으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X25','SO4-2-u3-X29','SO4-2-u3-X24']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C11","difficulty":3,"kind":"mc","stem":"공부한 것 ①~⑤를 이야기책에 담을 때 「⑤ 해결 노력」과 이어 쓸 장면으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"나는 주말마다 이웃과 함께 바람길 숲에 나무를 심어요","correct":true},{"t":"나는 아침마다 텅 빈 지하철을 타요","mis":"SO4-2-u3-X25"},{"t":"나는 쓰레기를 길에 버려요","mis":"SO4-2-u3-X29"},{"t":"나는 바다에서 김을 길러요","mis":"SO4-2-u3-X24"}],"explanation":["⑤는 노력이에요.","문제를 줄여요.","나무를 심어요."],"asset":{"type":"passage","lines":["① 도시가 무엇인지","② 도시의 인구 · 산업 · 교통","③ 도시 사람들이 사는 집 · 하는 일 · 여가 생활","④ 도시 생활의 좋은 점과 문제점","⑤ 도시 문제를 해결하려는 노력"],"title":"「도시의 특징과 생활 모습」에서 공부한 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#6','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',3,'ox','auto','㉰처럼 나무가 우거지고 물이 흐르는 공원이 있는 도시는 자연과 조화를 이룬 도시예요.',ARRAY['SO4-2-u3-X31']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C11","difficulty":3,"kind":"ox","stem":"㉰처럼 나무가 우거지고 물이 흐르는 공원이 있는 도시는 자연과 조화를 이룬 도시예요.","answer":"O","reason_options":[{"t":"사람이 사는 도시 안에서 자연을 지키고 가까이하기 때문에","correct":true},{"t":"공원이 있으면 도시가 아니기 때문에","mis":"SO4-2-u3-X31"}],"mis":"SO4-2-u3-X31","explanation":["㉰를 봐요.","숲과 물이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["㉮ 체육관 · 영화관 · 도서관이 가까이 있어요.","㉯ 햇빛으로 전기를 만드는 지붕과 가로등이 있어요.","㉰ 나무가 우거지고 물이 흐르는 공원이 있어요."],"title":"내가 살고 싶은 도시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#7','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',3,'mc','auto','도시 그리기와 이야기책 만들기 가운데 무엇으로 정리해야 하나요?',ARRAY['SO4-2-u3-X30']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C11","difficulty":3,"kind":"mc","stem":"도시 그리기와 이야기책 만들기 가운데 무엇으로 정리해야 하나요?","options":[{"t":"둘 가운데 하나를 골라 정리해도 돼요","correct":true},{"t":"도시 그리기만 해야 해요","mis":"SO4-2-u3-X30"},{"t":"이야기책 만들기만 해야 해요","mis":"SO4-2-u3-X30"},{"t":"둘 다 하지 않아도 돼요","mis":"SO4-2-u3-X30"}],"explanation":["방법은 둘이에요.","하나를 골라요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#8','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',4,'mc','auto','공부한 것 ①~⑤를 함께 볼 때 「도시의 특징과 생활 모습」을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u3-X18','SO4-2-u3-X27','SO4-2-u3-X32']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C11","difficulty":4,"kind":"mc","stem":"공부한 것 ①~⑤를 함께 볼 때 「도시의 특징과 생활 모습」을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"도시는 많은 사람이 모여 사는 활동의 중심이고, 그 생활에는 좋은 점과 문제점이 있어 해결하려고 노력해요","correct":true},{"t":"도시에는 사람이 거의 살지 않아요","mis":"SO4-2-u3-X18"},{"t":"도시 생활에는 문제점이 없어요","mis":"SO4-2-u3-X27"},{"t":"도시는 산과 바다로만 이루어져요","mis":"SO4-2-u3-X32"}],"explanation":["①②는 도시예요.","③은 생활이에요.","④⑤는 좋은 점·문제점·노력이에요."],"asset":{"type":"passage","lines":["① 도시가 무엇인지","② 도시의 인구 · 산업 · 교통","③ 도시 사람들이 사는 집 · 하는 일 · 여가 생활","④ 도시 생활의 좋은 점과 문제점","⑤ 도시 문제를 해결하려는 노력"],"title":"「도시의 특징과 생활 모습」에서 공부한 것"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#9','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',4,'mc','auto','내가 살고 싶은 도시 ㉮~㉰를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X31','SO4-2-u3-X30']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C11","difficulty":4,"kind":"mc","stem":"내가 살고 싶은 도시 ㉮~㉰를 함께 보고 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"편리한 시설을 누리면서 자연을 지키는 도시를 꿈꿀 수 있어요","correct":true},{"t":"살기 좋은 도시에는 자연이 없어야 해요","mis":"SO4-2-u3-X31"},{"t":"도시에는 여가 시설이 필요 없어요","mis":"SO4-2-u3-X31"},{"t":"살고 싶은 도시는 하나로 정해져 있어요","mis":"SO4-2-u3-X30"}],"explanation":["㉮는 시설이에요.","㉯㉰는 자연이에요.","함께 누려요."],"asset":{"type":"passage","lines":["㉮ 체육관 · 영화관 · 도서관이 가까이 있어요.","㉯ 햇빛으로 전기를 만드는 지붕과 가로등이 있어요.","㉰ 나무가 우거지고 물이 흐르는 공원이 있어요."],"title":"내가 살고 싶은 도시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_L11_challenge#10','soc',4,2,'u3','L11','g4_2_soc_u3_L11_challenge','lesson_challenge','SO4-2-u3-C11',4,'essay','teacher','자연과 조화를 이룬 도시에 사는 나를 주인공으로 이야기책의 한 쪽을 쓰세요. 도시의 모습 한 문장과 그 속에서 사는 나의 모습 한 문장을 나란히 쓰세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C11","difficulty":4,"kind":"essay","stem":"자연과 조화를 이룬 도시에 사는 나를 주인공으로 이야기책의 한 쪽을 쓰세요. 도시의 모습 한 문장과 그 속에서 사는 나의 모습 한 문장을 나란히 쓰세요.","answer_guide":{"answer":"예: 도시의 모습 — 우리 도시의 집 지붕에는 햇빛으로 전기를 만드는 판이 있고, 길가에는 나무가 우거져 있어요. 나의 모습 — 나는 학교가 끝나면 숲길 옆 자전거 길로 집에 가요.","scoring_points":["자연과 조화를 이룬 도시의 모습을 썼는가","그 속에서 사는 나의 모습을 썼는가","두 문장이 서로 이어지는가"]},"explanation":["도시를 써요.","나를 써요.","나란히 이어요."],"asset":{"type":"passage","lines":["배경 — 자연과 조화를 이룬 도시","주인공 — 그 도시에 사는 나","만드는 법 — 도화지로 작은 책 모양을 먼저 만들고, 글을 쓰고 그림을 그려요.","한 쪽에는 도시의 모습, 마주 보는 쪽에는 그 속에서 사는 나의 모습"],"title":"이야기책 만들기"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#1','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C1',1,'mc','auto','신문 ①의 ○○군에서 볼 수 있는 것 가운데 자연환경은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C1","difficulty":1,"kind":"mc","stem":"신문 ①의 ○○군에서 볼 수 있는 것 가운데 자연환경은 무엇인가요?","options":[{"t":"계곡","correct":true},{"t":"목장","mis":"SO4-2-u3-X01"},{"t":"풍력 발전기","mis":"SO4-2-u3-X01"},{"t":"스키장","mis":"SO4-2-u3-X01"}],"explanation":["사람이 만들지 않았어요.","계곡은 자연이에요.","계곡이에요."],"asset":{"type":"passage","lines":["① 산골 ○○군 — 울창한 숲과 맑은 계곡이 있어요.","언덕 목장에서 양을 기르고, 산꼭대기에는 풍력 발전기가 돌아요.","옛날에는 산비탈 밭에서 감자를 길렀어요.","스키장이 생긴 뒤로 관광객이 늘어 식당과 숙박 시설이 많아졌어요."],"title":"□□도 여행 신문 ① 산골 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#2','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C2',1,'mc','auto','신문 ①에서 ○○군 사람들이 옛날에 산비탈 밭에서 기른 것은 무엇인가요?',ARRAY['SO4-2-u3-X04']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C2","difficulty":1,"kind":"mc","stem":"신문 ①에서 ○○군 사람들이 옛날에 산비탈 밭에서 기른 것은 무엇인가요?","options":[{"t":"감자","correct":true},{"t":"딸기","mis":"SO4-2-u3-X04"},{"t":"김","mis":"SO4-2-u3-X04"},{"t":"벼","mis":"SO4-2-u3-X04"}],"explanation":["셋째 줄을 읽어요.","산비탈 밭이에요.","감자예요."],"asset":{"type":"passage","lines":["① 산골 ○○군 — 울창한 숲과 맑은 계곡이 있어요.","언덕 목장에서 양을 기르고, 산꼭대기에는 풍력 발전기가 돌아요.","옛날에는 산비탈 밭에서 감자를 길렀어요.","스키장이 생긴 뒤로 관광객이 늘어 식당과 숙박 시설이 많아졌어요."],"title":"□□도 여행 신문 ① 산골 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#3','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C3',1,'mc','auto','신문 ②에서 △△군의 논은 어디 가까이에 펼쳐져 있나요?',ARRAY['SO4-2-u3-X06']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C3","difficulty":1,"kind":"mc","stem":"신문 ②에서 △△군의 논은 어디 가까이에 펼쳐져 있나요?","options":[{"t":"저수지","correct":true},{"t":"산비탈","mis":"SO4-2-u3-X06"},{"t":"갯벌","mis":"SO4-2-u3-X06"},{"t":"모래사장","mis":"SO4-2-u3-X06"}],"explanation":["첫째 줄을 읽어요.","물이 있는 곳이에요.","저수지예요."],"asset":{"type":"passage","lines":["② 들판 △△군 — 저수지 가까이에 논이 넓게 펼쳐져 있어요.","비닐하우스에서는 딸기를 기르고, 축사에서는 소를 키워요.","옛 지도에는 논과 밭뿐이었는데, 요즘 지도에는 아파트가 많아요.","요즘에는 대형 할인점과 기차역, 박물관도 생겼어요."],"title":"□□도 여행 신문 ② 들판 △△군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#4','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C4',1,'mc','auto','신문 ③에서 ◇◇군 앞바다 양식장에서 기르는 것은 무엇인가요?',ARRAY['SO4-2-u3-X09']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C4","difficulty":1,"kind":"mc","stem":"신문 ③에서 ◇◇군 앞바다 양식장에서 기르는 것은 무엇인가요?","options":[{"t":"김","correct":true},{"t":"딸기","mis":"SO4-2-u3-X09"},{"t":"양","mis":"SO4-2-u3-X09"},{"t":"감자","mis":"SO4-2-u3-X09"}],"explanation":["둘째 줄을 읽어요.","바다에서 길러요.","김이에요."],"asset":{"type":"passage","lines":["③ 바닷가 ◇◇군 — 넓은 갯벌과 하얀 모래사장이 있어요.","앞바다 양식장에서는 김을 기르고, 수산물 직판장에서는 생선을 팔아요.","큰 항구에 배가 원료를 싣고 들어오면 바닷가 공장이 제품을 만들어요.","공장이 생긴 뒤로 일하러 오는 사람이 늘었어요."],"title":"□□도 여행 신문 ③ 바닷가 ◇◇군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#5','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C5',1,'mc','auto','신문 ④에서 ◇◇군이 갯벌을 새 땅으로 만든 일은 무엇인가요?',ARRAY['SO4-2-u3-X12','SO4-2-u3-X14']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C5","difficulty":1,"kind":"mc","stem":"신문 ④에서 ◇◇군이 갯벌을 새 땅으로 만든 일은 무엇인가요?","options":[{"t":"간척","correct":true},{"t":"케이블카","mis":"SO4-2-u3-X12"},{"t":"생태 통로","mis":"SO4-2-u3-X14"},{"t":"휴식","mis":"SO4-2-u3-X14"}],"explanation":["둘째 줄을 읽어요.","갯벌을 땅으로 바꿔요.","간척이에요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#6','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C7',1,'mc','auto','신문 ⑤의 □□시처럼 많은 인구가 모여 살며 활동의 중심이 되는 곳을 무엇이라고 하나요?',ARRAY['SO4-2-u3-X18']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C7","difficulty":1,"kind":"mc","stem":"신문 ⑤의 □□시처럼 많은 인구가 모여 살며 활동의 중심이 되는 곳을 무엇이라고 하나요?","options":[{"t":"도시","correct":true},{"t":"산골","mis":"SO4-2-u3-X18"},{"t":"어촌","mis":"SO4-2-u3-X18"},{"t":"들판","mis":"SO4-2-u3-X18"}],"explanation":["넷째 줄을 읽어요.","활동의 중심이에요.","도시예요."],"asset":{"type":"passage","lines":["⑤ □□시 — 밤에도 거리와 건물에 불이 환하게 켜져 있어요.","시청과 법원 같은 공공 기관, 큰 병원과 상점이 많아요.","□□도에 사는 사람 대부분이 □□시에 모여 살아요.","□□도의 정치, 경제, 사회 활동의 중심이에요."],"title":"□□도 여행 신문 ⑤ □□시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#7','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C8',1,'mc','auto','신문 ⑥에서 □□시의 은행은 어떤 산업에 속하나요?',ARRAY['SO4-2-u3-X22']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C8","difficulty":1,"kind":"mc","stem":"신문 ⑥에서 □□시의 은행은 어떤 산업에 속하나요?","options":[{"t":"금융업","correct":true},{"t":"제조업","mis":"SO4-2-u3-X22"},{"t":"상업","mis":"SO4-2-u3-X22"},{"t":"관광 산업","mis":"SO4-2-u3-X22"}],"explanation":["은행은 돈을 다뤄요.","맡아 주고 빌려줘요.","금융업이에요."],"asset":{"type":"passage","lines":["⑥ □□시의 산업 — 자동차 공장, 전통 시장, 은행, 불꽃 축제가 유명해요.","□□시의 교통 — 지하철역과 기차역, 버스 터미널, 공항이 있어요.","길과 탈것이 이어져 사람과 물건이 빠르게 오가요."],"title":"□□도 여행 신문 ⑥ □□시의 산업과 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#8','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C9',1,'mc','auto','신문 ⑦에서 □□시 사람들이 아침에 타는 교통수단은 무엇인가요?',ARRAY['SO4-2-u3-X25','SO4-2-u3-X24']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C9","difficulty":1,"kind":"mc","stem":"신문 ⑦에서 □□시 사람들이 아침에 타는 교통수단은 무엇인가요?","options":[{"t":"지하철","correct":true},{"t":"배","mis":"SO4-2-u3-X25"},{"t":"케이블카","mis":"SO4-2-u3-X25"},{"t":"경운기","mis":"SO4-2-u3-X24"}],"explanation":["첫째 줄을 읽어요.","땅 밑으로 다녀요.","지하철이에요."],"asset":{"type":"passage","lines":["⑦ □□시 사람의 하루 — 아침에 아파트에서 나와 지하철을 타요.","낮에는 회사 사무실, 자동차 공장, 우체국에서 일해요.","저녁에는 공원에서 달리기를 하거나 미술관에 가요."],"title":"□□도 여행 신문 ⑦ □□시 사람의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#9','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C1',2,'mc','auto','신문 ①의 ○○군에서 볼 수 있는 것을 자연환경과 인문환경으로 바르게 나눈 것은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C1","difficulty":2,"kind":"mc","stem":"신문 ①의 ○○군에서 볼 수 있는 것을 자연환경과 인문환경으로 바르게 나눈 것은 무엇인가요?","options":[{"t":"숲 · 계곡 / 목장 · 풍력 발전기 · 스키장","correct":true},{"t":"숲 · 목장 / 계곡 · 스키장","mis":"SO4-2-u3-X01"},{"t":"계곡 · 스키장 / 숲 · 목장","mis":"SO4-2-u3-X01"},{"t":"모두 자연환경이에요","mis":"SO4-2-u3-X01"}],"explanation":["자연 그대로를 찾아요.","사람이 만든 것을 찾아요.","나누어요."],"asset":{"type":"passage","lines":["① 산골 ○○군 — 울창한 숲과 맑은 계곡이 있어요.","언덕 목장에서 양을 기르고, 산꼭대기에는 풍력 발전기가 돌아요.","옛날에는 산비탈 밭에서 감자를 길렀어요.","스키장이 생긴 뒤로 관광객이 늘어 식당과 숙박 시설이 많아졌어요."],"title":"□□도 여행 신문 ① 산골 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#10','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C3',2,'mc','auto','신문 ②에서 △△군의 옛 지도와 요즘 지도를 견주어 알 수 있는 것은 무엇인가요?',ARRAY['SO4-2-u3-X08']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"mc","stem":"신문 ②에서 △△군의 옛 지도와 요즘 지도를 견주어 알 수 있는 것은 무엇인가요?","options":[{"t":"논과 밭이 있던 곳에 아파트가 생겨 사는 사람이 많아졌어요","correct":true},{"t":"아파트가 사라지고 논이 늘었어요","mis":"SO4-2-u3-X08"},{"t":"사람이 모두 떠났어요","mis":"SO4-2-u3-X08"},{"t":"달라진 것이 없어요","mis":"SO4-2-u3-X08"}],"explanation":["옛 지도는 논밭이에요.","요즘 지도는 아파트예요.","사람이 늘었어요."],"asset":{"type":"passage","lines":["② 들판 △△군 — 저수지 가까이에 논이 넓게 펼쳐져 있어요.","비닐하우스에서는 딸기를 기르고, 축사에서는 소를 키워요.","옛 지도에는 논과 밭뿐이었는데, 요즘 지도에는 아파트가 많아요.","요즘에는 대형 할인점과 기차역, 박물관도 생겼어요."],"title":"□□도 여행 신문 ② 들판 △△군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#11','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C4',2,'mc','auto','신문 ③에서 ◇◇군에 공장이 들어설 수 있었던 까닭으로 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X10','SO4-2-u3-X09']::text[],false,'{"seq":11,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"mc","stem":"신문 ③에서 ◇◇군에 공장이 들어설 수 있었던 까닭으로 알맞은 것은 무엇인가요?","options":[{"t":"큰 항구가 있어 배로 원료와 제품을 실어 나를 수 있어서요","correct":true},{"t":"갯벌에서 제품이 저절로 나와서요","mis":"SO4-2-u3-X10"},{"t":"모래사장이 넓어서요","mis":"SO4-2-u3-X09"},{"t":"사람이 하나도 없어서요","mis":"SO4-2-u3-X10"}],"explanation":["셋째 줄을 읽어요.","배가 실어 날라요.","항구 덕분이에요."],"asset":{"type":"passage","lines":["③ 바닷가 ◇◇군 — 넓은 갯벌과 하얀 모래사장이 있어요.","앞바다 양식장에서는 김을 기르고, 수산물 직판장에서는 생선을 팔아요.","큰 항구에 배가 원료를 싣고 들어오면 바닷가 공장이 제품을 만들어요.","공장이 생긴 뒤로 일하러 오는 사람이 늘었어요."],"title":"□□도 여행 신문 ③ 바닷가 ◇◇군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#12','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C5',2,'mc','auto','신문 ④에서 ◇◇군 간척의 좋은 점과 문제점을 바르게 짝지은 것은 무엇인가요?',ARRAY['SO4-2-u3-X11','SO4-2-u3-X12']::text[],false,'{"seq":12,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"mc","stem":"신문 ④에서 ◇◇군 간척의 좋은 점과 문제점을 바르게 짝지은 것은 무엇인가요?","options":[{"t":"일자리가 늘었어요 / 폐수가 생겼어요","correct":true},{"t":"폐수가 생겼어요 / 일자리가 늘었어요","mis":"SO4-2-u3-X11"},{"t":"숲이 훼손됐어요 / 관광객이 늘었어요","mis":"SO4-2-u3-X12"},{"t":"좋은 점만 있어요 / 문제점은 없어요","mis":"SO4-2-u3-X11"}],"explanation":["둘째 줄을 읽어요.","앞은 좋은 점이에요.","뒤는 문제점이에요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#13','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C6',2,'mc','auto','「지역의 환경과 변화」를 정리하는 방법으로 알맞은 것은 무엇인가요? (단원 정리)',ARRAY['SO4-2-u3-X16']::text[],false,'{"seq":13,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"mc","stem":"「지역의 환경과 변화」를 정리하는 방법으로 알맞은 것은 무엇인가요? (단원 정리)","options":[{"t":"그림, 편지, 낱말 퍼즐처럼 여러 방법 가운데 골라 정리해요","correct":true},{"t":"한 가지 방법으로만 정리해요","mis":"SO4-2-u3-X16"},{"t":"꾸밈만 예쁘게 하면 돼요","mis":"SO4-2-u3-X16"},{"t":"정리하지 않아도 돼요","mis":"SO4-2-u3-X16"}],"explanation":["방법을 떠올려요.","여러 가지예요.","골라서 정리해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#14','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C8',2,'mc','auto','신문 ⑥에서 □□시에 발달한 산업을 바르게 말한 것은 무엇인가요?',ARRAY['SO4-2-u3-X22']::text[],false,'{"seq":14,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"mc","stem":"신문 ⑥에서 □□시에 발달한 산업을 바르게 말한 것은 무엇인가요?","options":[{"t":"제조업 · 상업 · 금융업 · 관광 산업이 모두 발달했어요","correct":true},{"t":"제조업 하나만 발달했어요","mis":"SO4-2-u3-X22"},{"t":"산업이 하나도 없어요","mis":"SO4-2-u3-X22"},{"t":"상업과 농업만 발달했어요","mis":"SO4-2-u3-X22"}],"explanation":["첫째 줄을 읽어요.","공장·시장·은행·축제예요.","네 가지예요."],"asset":{"type":"passage","lines":["⑥ □□시의 산업 — 자동차 공장, 전통 시장, 은행, 불꽃 축제가 유명해요.","□□시의 교통 — 지하철역과 기차역, 버스 터미널, 공항이 있어요.","길과 탈것이 이어져 사람과 물건이 빠르게 오가요."],"title":"□□도 여행 신문 ⑥ □□시의 산업과 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#15','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C10',2,'mc','auto','신문 ⑧에서 □□시 생활의 좋은 점은 무엇인가요?',ARRAY['SO4-2-u3-X27']::text[],false,'{"seq":15,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"mc","stem":"신문 ⑧에서 □□시 생활의 좋은 점은 무엇인가요?","options":[{"t":"일자리가 많고 병원과 영화관이 가까워요","correct":true},{"t":"도로가 꽉 막혀요","mis":"SO4-2-u3-X27"},{"t":"쓰레기가 늘어요","mis":"SO4-2-u3-X27"},{"t":"미세 먼지가 많아요","mis":"SO4-2-u3-X27"}],"explanation":["첫째 줄을 읽어요.","편리한 점이에요.","일자리와 병원이에요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#16','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C11',2,'mc','auto','이야기책 만들기에서 배경과 주인공을 바르게 정한 것은 무엇인가요? (단원 정리)',ARRAY['SO4-2-u3-X30','SO4-2-u3-X31']::text[],false,'{"seq":16,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"mc","stem":"이야기책 만들기에서 배경과 주인공을 바르게 정한 것은 무엇인가요? (단원 정리)","options":[{"t":"배경 — 자연과 조화를 이룬 도시 / 주인공 — 그 도시에 사는 나","correct":true},{"t":"배경 — 산골 마을 / 주인공 — 산","mis":"SO4-2-u3-X30"},{"t":"배경 — 쓰레기가 쌓인 도시 / 주인공 — 자동차","mis":"SO4-2-u3-X31"},{"t":"배경도 주인공도 없어요","mis":"SO4-2-u3-X30"}],"explanation":["배경은 도시예요.","주인공은 나예요.","그것을 골라요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#17','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C5',3,'mc','auto','신문 ④를 보고 개발에 대해 가장 알맞게 생각한 것은 무엇인가요?',ARRAY['SO4-2-u3-X13','SO4-2-u3-X11']::text[],false,'{"seq":17,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"mc","stem":"신문 ④를 보고 개발에 대해 가장 알맞게 생각한 것은 무엇인가요?","options":[{"t":"개발의 좋은 점을 누리면서 생태 통로처럼 문제를 줄이는 노력을 함께 해요","correct":true},{"t":"개발은 모두 되돌려야 해요","mis":"SO4-2-u3-X13"},{"t":"문제점은 생각하지 않아도 돼요","mis":"SO4-2-u3-X11"},{"t":"좋은 점만 쏙 골라 가질 수 있어요","mis":"SO4-2-u3-X13"}],"explanation":["개발에는 두 얼굴이 있어요.","노력도 있어요.","함께 해요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#18','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C4',3,'mc','auto','신문 ①~③의 세 지역에서 사람들이 하는 일을 바르게 견준 것은 무엇인가요?',ARRAY['SO4-2-u3-X04','SO4-2-u3-X06','SO4-2-u3-X09']::text[],false,'{"seq":18,"concept":"SO4-2-u3-C4","difficulty":3,"kind":"mc","stem":"신문 ①~③의 세 지역에서 사람들이 하는 일을 바르게 견준 것은 무엇인가요?","options":[{"t":"○○군은 양 기르기, △△군은 딸기 재배, ◇◇군은 김 양식을 해요","correct":true},{"t":"○○군은 김 양식, △△군은 양 기르기, ◇◇군은 딸기 재배를 해요","mis":"SO4-2-u3-X04"},{"t":"세 지역 모두 같은 일을 해요","mis":"SO4-2-u3-X06"},{"t":"○○군은 딸기 재배, △△군은 김 양식, ◇◇군은 양 기르기를 해요","mis":"SO4-2-u3-X09"}],"explanation":["①은 산이에요.","②는 들이에요.","③은 바다예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#19','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C7',3,'mc','auto','신문 ⑤를 보고 □□시가 도시인 까닭을 가장 잘 말한 것은 무엇인가요?',ARRAY['SO4-2-u3-X19','SO4-2-u3-X18']::text[],false,'{"seq":19,"concept":"SO4-2-u3-C7","difficulty":3,"kind":"mc","stem":"신문 ⑤를 보고 □□시가 도시인 까닭을 가장 잘 말한 것은 무엇인가요?","options":[{"t":"많은 사람이 모여 살고 공공 기관과 편의 시설이 많아 활동의 중심이 되기 때문이에요","correct":true},{"t":"밤에 불이 하나 켜져 있기 때문이에요","mis":"SO4-2-u3-X19"},{"t":"높은 건물이 한 채 있기 때문이에요","mis":"SO4-2-u3-X18"},{"t":"사는 사람이 적기 때문이에요","mis":"SO4-2-u3-X18"}],"explanation":["사람이 많아요.","시설이 많아요.","활동의 중심이에요."],"asset":{"type":"passage","lines":["⑤ □□시 — 밤에도 거리와 건물에 불이 환하게 켜져 있어요.","시청과 법원 같은 공공 기관, 큰 병원과 상점이 많아요.","□□도에 사는 사람 대부분이 □□시에 모여 살아요.","□□도의 정치, 경제, 사회 활동의 중심이에요."],"title":"□□도 여행 신문 ⑤ □□시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#20','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C9',3,'mc','auto','신문 ⑦의 하루를 무언극으로 나타낼 때 「낮」 장면에 알맞은 몸짓은 무엇인가요?',ARRAY['SO4-2-u3-X24','SO4-2-u3-X26']::text[],false,'{"seq":20,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"mc","stem":"신문 ⑦의 하루를 무언극으로 나타낼 때 「낮」 장면에 알맞은 몸짓은 무엇인가요?","options":[{"t":"공구를 들고 자동차를 조립하는 몸짓","correct":true},{"t":"배에서 그물을 던지는 몸짓","mis":"SO4-2-u3-X24"},{"t":"「안녕하세요」라고 말하기","mis":"SO4-2-u3-X26"},{"t":"산비탈에서 감자를 캐는 몸짓","mis":"SO4-2-u3-X24"}],"explanation":["둘째 줄을 읽어요.","자동차 공장이에요.","조립하는 몸짓이에요."],"asset":{"type":"passage","lines":["⑦ □□시 사람의 하루 — 아침에 아파트에서 나와 지하철을 타요.","낮에는 회사 사무실, 자동차 공장, 우체국에서 일해요.","저녁에는 공원에서 달리기를 하거나 미술관에 가요."],"title":"□□도 여행 신문 ⑦ □□시 사람의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#21','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C10',3,'mc','auto','신문 ⑧에서 좋은 점이 문제점으로 바뀐 예로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X28','SO4-2-u3-X29']::text[],false,'{"seq":21,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"mc","stem":"신문 ⑧에서 좋은 점이 문제점으로 바뀐 예로 가장 알맞은 것은 무엇인가요?","options":[{"t":"편리한 도로에 출퇴근 시간 자동차가 몰려 꽉 막혀요","correct":true},{"t":"병원이 가까워 편리해요","mis":"SO4-2-u3-X28"},{"t":"바람길 숲을 만들었어요","mis":"SO4-2-u3-X29"},{"t":"장바구니 캠페인을 열었어요","mis":"SO4-2-u3-X29"}],"explanation":["도로는 편리했어요.","몰리면요?","꽉 막혀요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#22','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C11',3,'mc','auto','단원 내용을 두 갈래로 묶을 때 「도시의 특징과 생활 모습」 갈래에 붙일 것은 무엇인가요?',ARRAY['SO4-2-u3-X32']::text[],false,'{"seq":22,"concept":"SO4-2-u3-C11","difficulty":3,"kind":"mc","stem":"단원 내용을 두 갈래로 묶을 때 「도시의 특징과 생활 모습」 갈래에 붙일 것은 무엇인가요?","options":[{"t":"신문 ⑤~⑧의 내용","correct":true},{"t":"신문 ①~③의 내용","mis":"SO4-2-u3-X32"},{"t":"신문 ④의 내용","mis":"SO4-2-u3-X32"},{"t":"어느 갈래에도 붙이지 않아요","mis":"SO4-2-u3-X32"}],"explanation":["⑤부터 도시예요.","⑧까지 이어져요.","⑤~⑧이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#23','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C6',4,'mc','auto','신문 ①~④를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X04','SO4-2-u3-X11','SO4-2-u3-X13']::text[],false,'{"seq":23,"concept":"SO4-2-u3-C6","difficulty":4,"kind":"mc","stem":"신문 ①~④를 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"지역마다 환경과 하는 일이 다르고, 환경을 이용·개발하면 좋은 점과 문제점이 함께 생겨 조화를 이루려 노력해요","correct":true},{"t":"세 지역의 환경은 모두 같아요","mis":"SO4-2-u3-X04"},{"t":"개발에는 좋은 점만 있어요","mis":"SO4-2-u3-X11"},{"t":"조화를 이루려면 모든 개발을 되돌려야 해요","mis":"SO4-2-u3-X13"}],"explanation":["①~③은 세 지역이에요.","④는 개발이에요.","함께 보아요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#24','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C2',4,'essay','teacher','신문 ①~③ 가운데 한 지역을 골라 그 지역의 자연환경과 사람들이 하는 일을 쓰고, 그 지역이 어떻게 달라졌는지 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u3-C2","difficulty":4,"kind":"essay","stem":"신문 ①~③ 가운데 한 지역을 골라 그 지역의 자연환경과 사람들이 하는 일을 쓰고, 그 지역이 어떻게 달라졌는지 쓰세요.","answer_guide":{"answer":"예: 바닷가 ◇◇군을 골랐어요. 넓은 갯벌과 모래사장이 있고, 사람들은 양식장에서 김을 기르고 수산물 직판장에서 생선을 팔아요. 큰 항구로 원료가 들어와 공장이 생기면서 일하러 오는 사람이 늘었어요.","scoring_points":["지역을 하나 골랐는가","자연환경과 하는 일을 썼는가","달라진 모습을 썼는가"]},"explanation":["하나를 골라요.","환경과 일을 써요.","변화를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_a#25','soc',4,2,'u3','','g4_2_soc_u3_review_a','unit_review','SO4-2-u3-C10',4,'essay','teacher','신문 ⑧에서 □□시 생활의 좋은 점과 문제점을 하나씩 쓰고, 좋은 점이 문제점이 되기도 하는 까닭을 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u3-C10","difficulty":4,"kind":"essay","stem":"신문 ⑧에서 □□시 생활의 좋은 점과 문제점을 하나씩 쓰고, 좋은 점이 문제점이 되기도 하는 까닭을 쓰세요.","answer_guide":{"answer":"예: 좋은 점은 일자리가 많고 병원이 가까운 것이에요. 문제점은 출퇴근 시간에 도로가 꽉 막히는 것이에요. 도로는 편리하지만 좁은 지역에 많은 사람과 자동차가 한꺼번에 몰리면 막히는 문제가 되기 때문이에요.","scoring_points":["좋은 점을 썼는가","문제점을 썼는가","좁은 지역에 많은 사람이라는 까닭을 썼는가"]},"explanation":["좋은 점을 써요.","문제점을 써요.","까닭을 써요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#1','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C1',1,'sa','auto','자연 그대로 생겨난 환경을 ○○환경이라고 해요. ○○에 알맞은 두 글자를 쓰세요. (단원 정리)','{}'::text[],false,'{"seq":1,"concept":"SO4-2-u3-C1","difficulty":1,"kind":"sa","stem":"자연 그대로 생겨난 환경을 ○○환경이라고 해요. ○○에 알맞은 두 글자를 쓰세요. (단원 정리)","answer":["자연"],"explanation":["자연 그대로예요.","자◯환경이에요.","자연이에요."],"mis":"SO4-2-u3-X03"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#2','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C2',1,'sa','auto','신문 ①에서 산꼭대기에서 바람으로 전기를 만드는 시설은 무엇인가요? 다섯 글자로 쓰세요.','{}'::text[],false,'{"seq":2,"concept":"SO4-2-u3-C2","difficulty":1,"kind":"sa","stem":"신문 ①에서 산꼭대기에서 바람으로 전기를 만드는 시설은 무엇인가요? 다섯 글자로 쓰세요.","answer":["풍력 발전기","풍력발전기"],"explanation":["둘째 줄이에요.","풍력 ◯◯◯예요.","풍력 발전기예요."],"asset":{"type":"passage","lines":["① 산골 ○○군 — 울창한 숲과 맑은 계곡이 있어요.","언덕 목장에서 양을 기르고, 산꼭대기에는 풍력 발전기가 돌아요.","옛날에는 산비탈 밭에서 감자를 길렀어요.","스키장이 생긴 뒤로 관광객이 늘어 식당과 숙박 시설이 많아졌어요."],"title":"□□도 여행 신문 ① 산골 ○○군"},"mis":"SO4-2-u3-X04"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#3','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C3',1,'sa','auto','신문 ②에서 △△군 축사에서 키우는 동물은 무엇인가요? 한 글자로 쓰세요.','{}'::text[],false,'{"seq":3,"concept":"SO4-2-u3-C3","difficulty":1,"kind":"sa","stem":"신문 ②에서 △△군 축사에서 키우는 동물은 무엇인가요? 한 글자로 쓰세요.","answer":["소"],"explanation":["둘째 줄이에요.","축사예요.","소예요."],"asset":{"type":"passage","lines":["② 들판 △△군 — 저수지 가까이에 논이 넓게 펼쳐져 있어요.","비닐하우스에서는 딸기를 기르고, 축사에서는 소를 키워요.","옛 지도에는 논과 밭뿐이었는데, 요즘 지도에는 아파트가 많아요.","요즘에는 대형 할인점과 기차역, 박물관도 생겼어요."],"title":"□□도 여행 신문 ② 들판 △△군"},"mis":"SO4-2-u3-X06"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#4','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C4',1,'sa','auto','신문 ③에서 생선을 파는 곳은 수산물 ○○○이에요. ○○○에 알맞은 세 글자를 쓰세요.','{}'::text[],false,'{"seq":4,"concept":"SO4-2-u3-C4","difficulty":1,"kind":"sa","stem":"신문 ③에서 생선을 파는 곳은 수산물 ○○○이에요. ○○○에 알맞은 세 글자를 쓰세요.","answer":["직판장"],"explanation":["둘째 줄이에요.","수산물 직◯◯이에요.","직판장이에요."],"asset":{"type":"passage","lines":["③ 바닷가 ◇◇군 — 넓은 갯벌과 하얀 모래사장이 있어요.","앞바다 양식장에서는 김을 기르고, 수산물 직판장에서는 생선을 팔아요.","큰 항구에 배가 원료를 싣고 들어오면 바닷가 공장이 제품을 만들어요.","공장이 생긴 뒤로 일하러 오는 사람이 늘었어요."],"title":"□□도 여행 신문 ③ 바닷가 ◇◇군"},"mis":"SO4-2-u3-X09"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#5','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C5',1,'sa','auto','신문 ④에서 고라니가 고속도로를 건너도록 만든 것은 무엇인가요? 네 글자로 쓰세요.','{}'::text[],false,'{"seq":5,"concept":"SO4-2-u3-C5","difficulty":1,"kind":"sa","stem":"신문 ④에서 고라니가 고속도로를 건너도록 만든 것은 무엇인가요? 네 글자로 쓰세요.","answer":["생태 통로","생태통로"],"explanation":["셋째 줄이에요.","생태 ◯◯예요.","생태 통로예요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"},"mis":"SO4-2-u3-X14"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#6','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C7',1,'sa','auto','신문 ⑤에서 시청이나 법원처럼 여러 사람을 위해 일하는 곳을 ○○ 기관이라고 해요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":6,"concept":"SO4-2-u3-C7","difficulty":1,"kind":"sa","stem":"신문 ⑤에서 시청이나 법원처럼 여러 사람을 위해 일하는 곳을 ○○ 기관이라고 해요. ○○에 알맞은 두 글자를 쓰세요.","answer":["공공"],"explanation":["둘째 줄이에요.","공◯ 기관이에요.","공공이에요."],"asset":{"type":"passage","lines":["⑤ □□시 — 밤에도 거리와 건물에 불이 환하게 켜져 있어요.","시청과 법원 같은 공공 기관, 큰 병원과 상점이 많아요.","□□도에 사는 사람 대부분이 □□시에 모여 살아요.","□□도의 정치, 경제, 사회 활동의 중심이에요."],"title":"□□도 여행 신문 ⑤ □□시"},"mis":"SO4-2-u3-X19"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#7','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C8',1,'sa','auto','신문 ⑥에서 □□시의 자동차 공장은 물건을 한 번에 많이 만드는 ○○업이에요. ○○에 알맞은 두 글자를 쓰세요.','{}'::text[],false,'{"seq":7,"concept":"SO4-2-u3-C8","difficulty":1,"kind":"sa","stem":"신문 ⑥에서 □□시의 자동차 공장은 물건을 한 번에 많이 만드는 ○○업이에요. ○○에 알맞은 두 글자를 쓰세요.","answer":["제조"],"explanation":["물건을 만들어요.","◯◯업이에요.","제조예요."],"asset":{"type":"passage","lines":["⑥ □□시의 산업 — 자동차 공장, 전통 시장, 은행, 불꽃 축제가 유명해요.","□□시의 교통 — 지하철역과 기차역, 버스 터미널, 공항이 있어요.","길과 탈것이 이어져 사람과 물건이 빠르게 오가요."],"title":"□□도 여행 신문 ⑥ □□시의 산업과 교통"},"mis":"SO4-2-u3-X22"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#8','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C9',1,'sa','auto','신문 ⑦에서 □□시 사람들이 사는 곳은 어디인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":8,"concept":"SO4-2-u3-C9","difficulty":1,"kind":"sa","stem":"신문 ⑦에서 □□시 사람들이 사는 곳은 어디인가요? 세 글자로 쓰세요.","answer":["아파트"],"explanation":["첫째 줄이에요.","아◯◯예요.","아파트예요."],"asset":{"type":"passage","lines":["⑦ □□시 사람의 하루 — 아침에 아파트에서 나와 지하철을 타요.","낮에는 회사 사무실, 자동차 공장, 우체국에서 일해요.","저녁에는 공원에서 달리기를 하거나 미술관에 가요."],"title":"□□도 여행 신문 ⑦ □□시 사람의 하루"},"mis":"SO4-2-u3-X24"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#9','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C2',2,'ox','auto','신문 ①에서 ○○군의 옛날과 지금은 사람들이 하는 일이 달라졌어요.',ARRAY['SO4-2-u3-X05']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C2","difficulty":2,"kind":"ox","stem":"신문 ①에서 ○○군의 옛날과 지금은 사람들이 하는 일이 달라졌어요.","answer":"O","reason_options":[{"t":"옛날엔 감자 농사, 지금은 관광객을 위한 식당과 숙박 시설 일이 생겼기 때문에","correct":true},{"t":"산이 많은 지역은 바뀌지 않기 때문에","mis":"SO4-2-u3-X05"}],"mis":"SO4-2-u3-X05","explanation":["셋째 줄은 옛날이에요.","넷째 줄은 지금이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 산골 ○○군 — 울창한 숲과 맑은 계곡이 있어요.","언덕 목장에서 양을 기르고, 산꼭대기에는 풍력 발전기가 돌아요.","옛날에는 산비탈 밭에서 감자를 길렀어요.","스키장이 생긴 뒤로 관광객이 늘어 식당과 숙박 시설이 많아졌어요."],"title":"□□도 여행 신문 ① 산골 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#10','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C3',2,'ox','auto','신문 ②의 대형 할인점과 박물관은 △△군에 많은 사람이 모여 살면서 생긴 것이에요.',ARRAY['SO4-2-u3-X07']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"ox","stem":"신문 ②의 대형 할인점과 박물관은 △△군에 많은 사람이 모여 살면서 생긴 것이에요.","answer":"O","reason_options":[{"t":"사람이 많아지면 상점과 문화 시설이 필요해지기 때문에","correct":true},{"t":"사람이 줄어들수록 상점이 생기기 때문에","mis":"SO4-2-u3-X07"}],"mis":"SO4-2-u3-X07","explanation":["넷째 줄을 읽어요.","사람이 모였어요.","그래서 O예요."],"asset":{"type":"passage","lines":["② 들판 △△군 — 저수지 가까이에 논이 넓게 펼쳐져 있어요.","비닐하우스에서는 딸기를 기르고, 축사에서는 소를 키워요.","옛 지도에는 논과 밭뿐이었는데, 요즘 지도에는 아파트가 많아요.","요즘에는 대형 할인점과 기차역, 박물관도 생겼어요."],"title":"□□도 여행 신문 ② 들판 △△군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#11','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C4',2,'ox','auto','신문 ③의 양식장에서 김을 기르는 일과 수산물 직판장에서 생선을 파는 일은 같은 일이에요.',ARRAY['SO4-2-u3-X09']::text[],false,'{"seq":11,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"ox","stem":"신문 ③의 양식장에서 김을 기르는 일과 수산물 직판장에서 생선을 파는 일은 같은 일이에요.","answer":"X","reason_options":[{"t":"양식장은 기르는 일이고 직판장은 사고파는 일이기 때문에","correct":true},{"t":"바다와 관련 있는 일은 모두 같기 때문에","mis":"SO4-2-u3-X09"}],"mis":"SO4-2-u3-X09","explanation":["둘째 줄을 읽어요.","기르기와 팔기예요.","그래서 X예요."],"asset":{"type":"passage","lines":["③ 바닷가 ◇◇군 — 넓은 갯벌과 하얀 모래사장이 있어요.","앞바다 양식장에서는 김을 기르고, 수산물 직판장에서는 생선을 팔아요.","큰 항구에 배가 원료를 싣고 들어오면 바닷가 공장이 제품을 만들어요.","공장이 생긴 뒤로 일하러 오는 사람이 늘었어요."],"title":"□□도 여행 신문 ③ 바닷가 ◇◇군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#12','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C5',2,'ox','auto','신문 ④의 생태 통로와 쉬게 하는 산길은 인간과 환경의 조화를 이루려는 노력이에요.',ARRAY['SO4-2-u3-X14']::text[],false,'{"seq":12,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"ox","stem":"신문 ④의 생태 통로와 쉬게 하는 산길은 인간과 환경의 조화를 이루려는 노력이에요.","answer":"O","reason_options":[{"t":"개발로 생긴 문제를 줄여 동식물과 사람이 함께 살게 하기 때문에","correct":true},{"t":"둘 다 개발을 더 늘리는 일이기 때문에","mis":"SO4-2-u3-X14"}],"mis":"SO4-2-u3-X14","explanation":["셋째·넷째 줄이에요.","자연을 지켜요.","그래서 O예요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#13','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C6',2,'ox','auto','신문 ④의 숲이 훼손된 산이 되어 편지를 쓴다면, 사람에게 바라는 노력을 담을 수 있어요.',ARRAY['SO4-2-u3-X16']::text[],false,'{"seq":13,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"ox","stem":"신문 ④의 숲이 훼손된 산이 되어 편지를 쓴다면, 사람에게 바라는 노력을 담을 수 있어요.","answer":"O","reason_options":[{"t":"훼손된 자연환경이 하고 싶은 말을 쓰는 편지이기 때문에","correct":true},{"t":"편지에는 바라는 것을 쓰면 안 되기 때문에","mis":"SO4-2-u3-X16"}],"mis":"SO4-2-u3-X16","explanation":["숲이 훼손됐어요.","산이 되어 써요.","그래서 O예요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#14','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C8',2,'ox','auto','신문 ⑤에서 □□도 사람 대부분이 □□시에 사는 것은 우리나라 사람 대부분이 도시에 사는 것과 닮았어요.',ARRAY['SO4-2-u3-X21']::text[],false,'{"seq":14,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"ox","stem":"신문 ⑤에서 □□도 사람 대부분이 □□시에 사는 것은 우리나라 사람 대부분이 도시에 사는 것과 닮았어요.","answer":"O","reason_options":[{"t":"우리나라 인구 10명 가운데 9명 정도가 도시에 살기 때문에","correct":true},{"t":"우리나라 사람은 대부분 시골에 살기 때문에","mis":"SO4-2-u3-X21"}],"mis":"SO4-2-u3-X21","explanation":["셋째 줄을 읽어요.","대부분이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑤ □□시 — 밤에도 거리와 건물에 불이 환하게 켜져 있어요.","시청과 법원 같은 공공 기관, 큰 병원과 상점이 많아요.","□□도에 사는 사람 대부분이 □□시에 모여 살아요.","□□도의 정치, 경제, 사회 활동의 중심이에요."],"title":"□□도 여행 신문 ⑤ □□시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#15','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C10',2,'ox','auto','신문 ⑧의 바람길 숲은 미세 먼지를 줄이려는 노력이에요.',ARRAY['SO4-2-u3-X29']::text[],false,'{"seq":15,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"ox","stem":"신문 ⑧의 바람길 숲은 미세 먼지를 줄이려는 노력이에요.","answer":"O","reason_options":[{"t":"외곽 숲의 맑은 공기를 도시로 끌어들이기 때문에","correct":true},{"t":"바람길 숲은 쓰레기를 줄이는 노력이기 때문에","mis":"SO4-2-u3-X29"}],"mis":"SO4-2-u3-X29","explanation":["넷째 줄을 읽어요.","맑은 공기예요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#16','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C11',2,'ox','auto','자연과 조화를 이룬 도시에는 굴뚝 연기가 가득해야 해요.',ARRAY['SO4-2-u3-X31']::text[],false,'{"seq":16,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"ox","stem":"자연과 조화를 이룬 도시에는 굴뚝 연기가 가득해야 해요.","answer":"X","reason_options":[{"t":"자연을 해치지 않는 에너지를 쓰고 숲과 물이 가까운 도시이기 때문에","correct":true},{"t":"공장이 많을수록 자연과 조화를 이루기 때문에","mis":"SO4-2-u3-X31"}],"mis":"SO4-2-u3-X31","explanation":["조화를 떠올려요.","자연을 지켜요.","그래서 X예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#17','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C5',3,'ox','auto','신문 ④에서 케이블카를 없애기만 하면 관광객은 그대로 많고 숲만 되살아나요.',ARRAY['SO4-2-u3-X13']::text[],false,'{"seq":17,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"ox","stem":"신문 ④에서 케이블카를 없애기만 하면 관광객은 그대로 많고 숲만 되살아나요.","answer":"X","reason_options":[{"t":"좋은 점과 문제점은 같은 개발에서 함께 생겨 되돌리면 좋은 점도 사라지기 때문에","correct":true},{"t":"문제점만 따로 없앨 수 있기 때문에","mis":"SO4-2-u3-X13"}],"mis":"SO4-2-u3-X13","explanation":["되돌리면 어떻게 될까요?","둘 다 사라져요.","그래서 X예요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#18','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C3',3,'ox','auto','신문 ①~③의 세 지역은 모두 사람들이 환경을 이용하며 모습이 달라졌어요.',ARRAY['SO4-2-u3-X07']::text[],false,'{"seq":18,"concept":"SO4-2-u3-C3","difficulty":3,"kind":"ox","stem":"신문 ①~③의 세 지역은 모두 사람들이 환경을 이용하며 모습이 달라졌어요.","answer":"O","reason_options":[{"t":"스키장, 아파트와 할인점, 공장처럼 새로 생긴 것이 있기 때문에","correct":true},{"t":"세 지역 모두 옛날 그대로이기 때문에","mis":"SO4-2-u3-X07"}],"mis":"SO4-2-u3-X07","explanation":["①은 스키장이에요.","②는 아파트예요.","③은 공장이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#19','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C8',3,'ox','auto','신문 ⑥의 □□시에서 지하철역과 기차역이 이어지면 사람과 물건이 더 빠르게 오갈 수 있어요.',ARRAY['SO4-2-u3-X23']::text[],false,'{"seq":19,"concept":"SO4-2-u3-C8","difficulty":3,"kind":"ox","stem":"신문 ⑥의 □□시에서 지하철역과 기차역이 이어지면 사람과 물건이 더 빠르게 오갈 수 있어요.","answer":"O","reason_options":[{"t":"길과 탈것이 이어질수록 곳과 곳 사이가 가까워지기 때문에","correct":true},{"t":"역이 많을수록 더 멀어지기 때문에","mis":"SO4-2-u3-X23"}],"mis":"SO4-2-u3-X23","explanation":["셋째 줄을 읽어요.","빠르게 오가요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑥ □□시의 산업 — 자동차 공장, 전통 시장, 은행, 불꽃 축제가 유명해요.","□□시의 교통 — 지하철역과 기차역, 버스 터미널, 공항이 있어요.","길과 탈것이 이어져 사람과 물건이 빠르게 오가요."],"title":"□□도 여행 신문 ⑥ □□시의 산업과 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#20','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C9',3,'ox','auto','신문 ⑦에서 지하철을 타면 막히지 않지만 출근 시간에는 붐빌 수 있어요.',ARRAY['SO4-2-u3-X25']::text[],false,'{"seq":20,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"ox","stem":"신문 ⑦에서 지하철을 타면 막히지 않지만 출근 시간에는 붐빌 수 있어요.","answer":"O","reason_options":[{"t":"지하철은 막히지 않아도 출근하는 사람이 한꺼번에 많이 타기 때문에","correct":true},{"t":"지하철은 언제나 텅 비어 있기 때문에","mis":"SO4-2-u3-X25"}],"mis":"SO4-2-u3-X25","explanation":["아침에 타요.","사람이 많아요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑦ □□시 사람의 하루 — 아침에 아파트에서 나와 지하철을 타요.","낮에는 회사 사무실, 자동차 공장, 우체국에서 일해요.","저녁에는 공원에서 달리기를 하거나 미술관에 가요."],"title":"□□도 여행 신문 ⑦ □□시 사람의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#21','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C10',3,'ox','auto','신문 ⑧에서 주차할 곳이 모자란 것은 좁은 곳에 많은 사람과 자동차가 모였기 때문이에요.',ARRAY['SO4-2-u3-X28']::text[],false,'{"seq":21,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"ox","stem":"신문 ⑧에서 주차할 곳이 모자란 것은 좁은 곳에 많은 사람과 자동차가 모였기 때문이에요.","answer":"O","reason_options":[{"t":"도시는 좁은 지역에 많은 사람이 모여 살기 때문에","correct":true},{"t":"도시에는 자동차가 거의 없기 때문에","mis":"SO4-2-u3-X28"}],"mis":"SO4-2-u3-X28","explanation":["둘째 줄을 읽어요.","좁고 많아요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#22','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C6',3,'ox','auto','신문 ④의 개발 소식은 「지역의 환경과 변화」 갈래에 붙여요.',ARRAY['SO4-2-u3-X32']::text[],false,'{"seq":22,"concept":"SO4-2-u3-C6","difficulty":3,"kind":"ox","stem":"신문 ④의 개발 소식은 「지역의 환경과 변화」 갈래에 붙여요.","answer":"O","reason_options":[{"t":"환경의 이용과 개발에 따른 영향과 조화를 이루는 방법이기 때문에","correct":true},{"t":"개발 소식은 도시 생활의 문제점이기 때문에","mis":"SO4-2-u3-X32"}],"mis":"SO4-2-u3-X32","explanation":["④는 개발이에요.","주제①에서 배웠어요.","그래서 O예요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#23','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C10',4,'mc','auto','신문 ⑤~⑧을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X27','SO4-2-u3-X24','SO4-2-u3-X22']::text[],false,'{"seq":23,"concept":"SO4-2-u3-C10","difficulty":4,"kind":"mc","stem":"신문 ⑤~⑧을 함께 볼 때 알 수 있는 것으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"□□시는 많은 사람이 모여 사는 활동의 중심이고, 편리함과 함께 생긴 문제를 줄이려고 노력해요","correct":true},{"t":"□□시에는 문제점이 하나도 없어요","mis":"SO4-2-u3-X27"},{"t":"□□시 사람들은 주로 김을 길러요","mis":"SO4-2-u3-X24"},{"t":"□□시에는 산업과 교통이 발달하지 않았어요","mis":"SO4-2-u3-X22"}],"explanation":["⑤⑥은 도시예요.","⑦은 생활이에요.","⑧은 좋은 점과 문제점이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#24','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C5',4,'essay','teacher','신문 ④의 개발 가운데 하나를 골라 좋은 점과 문제점을 쓰고, 인간과 환경의 조화를 이루는 방법을 하나 제안하세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u3-C5","difficulty":4,"kind":"essay","stem":"신문 ④의 개발 가운데 하나를 골라 좋은 점과 문제점을 쓰고, 인간과 환경의 조화를 이루는 방법을 하나 제안하세요.","answer_guide":{"answer":"예: ○○군 케이블카를 골랐어요. 관광객이 늘어 지역 경제에 도움이 되었지만 숲이 훼손되었어요. 케이블카 둘레 숲길 한쪽에 자연 휴식년제를 하여 숲이 다시 회복할 시간을 주면 좋겠어요.","scoring_points":["개발을 하나 골랐는가","좋은 점과 문제점을 모두 썼는가","조화를 이루는 방법을 제안했는가"]},"explanation":["하나를 골라요.","두 얼굴을 써요.","방법을 제안해요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_b#25','soc',4,2,'u3','','g4_2_soc_u3_review_b','unit_review','SO4-2-u3-C1',4,'essay','teacher','우리 지역에서 볼 수 있는 자연환경과 인문환경을 하나씩 쓰고, 그 인문환경이 생기면서 사람들의 생활이 어떻게 달라졌을지 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u3-C1","difficulty":4,"kind":"essay","stem":"우리 지역에서 볼 수 있는 자연환경과 인문환경을 하나씩 쓰고, 그 인문환경이 생기면서 사람들의 생활이 어떻게 달라졌을지 쓰세요.","answer_guide":{"answer":"예: 자연환경은 마을 옆을 흐르는 하천이고, 인문환경은 하천을 건너는 다리예요. 다리가 생기면서 사람들이 돌아가지 않고 빠르게 건너편 마을과 학교에 갈 수 있게 되었을 거예요.","scoring_points":["자연환경을 썼는가","인문환경을 썼는가","생활의 변화를 썼는가"]},"explanation":["하나씩 골라요.","인문환경을 봐요.","변화를 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#1','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C1',1,'ox','auto','신문 ②의 저수지 가까이에 펼쳐진 논은 자연환경이에요.',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C1","difficulty":1,"kind":"ox","stem":"신문 ②의 저수지 가까이에 펼쳐진 논은 자연환경이에요.","answer":"X","reason_options":[{"t":"논은 사람들이 농사를 지으려고 만든 인문환경이기 때문에","correct":true},{"t":"논은 넓게 펼쳐져 있어 자연환경이기 때문에","mis":"SO4-2-u3-X01"}],"mis":"SO4-2-u3-X01","explanation":["논은 누가 만들었나요?","사람들이에요.","그래서 X예요."],"asset":{"type":"passage","lines":["② 들판 △△군 — 저수지 가까이에 논이 넓게 펼쳐져 있어요.","비닐하우스에서는 딸기를 기르고, 축사에서는 소를 키워요.","옛 지도에는 논과 밭뿐이었는데, 요즘 지도에는 아파트가 많아요.","요즘에는 대형 할인점과 기차역, 박물관도 생겼어요."],"title":"□□도 여행 신문 ② 들판 △△군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#2','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C2',1,'ox','auto','신문 ①에서 스키장이 생긴 뒤로 ○○군에 식당과 숙박 시설이 많아졌어요.',ARRAY['SO4-2-u3-X05']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C2","difficulty":1,"kind":"ox","stem":"신문 ①에서 스키장이 생긴 뒤로 ○○군에 식당과 숙박 시설이 많아졌어요.","answer":"O","reason_options":[{"t":"관광객이 늘어 음식과 잠자리가 필요해졌기 때문에","correct":true},{"t":"스키장과 식당은 서로 관계없기 때문에","mis":"SO4-2-u3-X05"}],"mis":"SO4-2-u3-X05","explanation":["넷째 줄을 읽어요.","관광객이 늘었어요.","그래서 O예요."],"asset":{"type":"passage","lines":["① 산골 ○○군 — 울창한 숲과 맑은 계곡이 있어요.","언덕 목장에서 양을 기르고, 산꼭대기에는 풍력 발전기가 돌아요.","옛날에는 산비탈 밭에서 감자를 길렀어요.","스키장이 생긴 뒤로 관광객이 늘어 식당과 숙박 시설이 많아졌어요."],"title":"□□도 여행 신문 ① 산골 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#3','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C3',1,'ox','auto','신문 ②의 박물관은 문화 시설이에요.',ARRAY['SO4-2-u3-X07']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C3","difficulty":1,"kind":"ox","stem":"신문 ②의 박물관은 문화 시설이에요.","answer":"O","reason_options":[{"t":"옛 물건이나 작품을 보며 문화를 누리는 곳이기 때문에","correct":true},{"t":"박물관은 물건을 사고파는 상점이기 때문에","mis":"SO4-2-u3-X07"}],"mis":"SO4-2-u3-X07","explanation":["박물관에서 무엇을 하나요?","옛 물건을 봐요.","그래서 O예요."],"asset":{"type":"passage","lines":["② 들판 △△군 — 저수지 가까이에 논이 넓게 펼쳐져 있어요.","비닐하우스에서는 딸기를 기르고, 축사에서는 소를 키워요.","옛 지도에는 논과 밭뿐이었는데, 요즘 지도에는 아파트가 많아요.","요즘에는 대형 할인점과 기차역, 박물관도 생겼어요."],"title":"□□도 여행 신문 ② 들판 △△군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#4','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C4',1,'ox','auto','신문 ③에서 배가 싣고 들어오는 것은 공장에서 만든 제품이에요.',ARRAY['SO4-2-u3-X10']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C4","difficulty":1,"kind":"ox","stem":"신문 ③에서 배가 싣고 들어오는 것은 공장에서 만든 제품이에요.","answer":"X","reason_options":[{"t":"배가 싣고 들어오는 것은 물건을 만드는 재료인 원료이기 때문에","correct":true},{"t":"원료와 제품은 같은 것이기 때문에","mis":"SO4-2-u3-X10"}],"mis":"SO4-2-u3-X10","explanation":["셋째 줄을 읽어요.","원료가 들어와요.","그래서 X예요."],"asset":{"type":"passage","lines":["③ 바닷가 ◇◇군 — 넓은 갯벌과 하얀 모래사장이 있어요.","앞바다 양식장에서는 김을 기르고, 수산물 직판장에서는 생선을 팔아요.","큰 항구에 배가 원료를 싣고 들어오면 바닷가 공장이 제품을 만들어요.","공장이 생긴 뒤로 일하러 오는 사람이 늘었어요."],"title":"□□도 여행 신문 ③ 바닷가 ◇◇군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#5','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C5',1,'ox','auto','신문 ④의 ○○군 케이블카는 좋은 점과 문제점을 함께 가져왔어요.',ARRAY['SO4-2-u3-X11']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C5","difficulty":1,"kind":"ox","stem":"신문 ④의 ○○군 케이블카는 좋은 점과 문제점을 함께 가져왔어요.","answer":"O","reason_options":[{"t":"관광객은 늘었지만 숲이 훼손되었기 때문에","correct":true},{"t":"케이블카는 좋은 점만 가져왔기 때문에","mis":"SO4-2-u3-X11"}],"mis":"SO4-2-u3-X11","explanation":["첫째 줄을 읽어요.","늘고 훼손됐어요.","그래서 O예요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#6','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C7',1,'ox','auto','신문 ⑤의 □□시가 밤에도 환한 것은 불이 켜진 곳이 많기 때문이에요.',ARRAY['SO4-2-u3-X19']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C7","difficulty":1,"kind":"ox","stem":"신문 ⑤의 □□시가 밤에도 환한 것은 불이 켜진 곳이 많기 때문이에요.","answer":"O","reason_options":[{"t":"사람들이 밤늦게까지 활동해 거리와 건물에 불이 켜져 있기 때문에","correct":true},{"t":"도시는 밤에도 해가 지지 않기 때문에","mis":"SO4-2-u3-X19"}],"mis":"SO4-2-u3-X19","explanation":["첫째 줄을 읽어요.","불이 켜져 있어요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑤ □□시 — 밤에도 거리와 건물에 불이 환하게 켜져 있어요.","시청과 법원 같은 공공 기관, 큰 병원과 상점이 많아요.","□□도에 사는 사람 대부분이 □□시에 모여 살아요.","□□도의 정치, 경제, 사회 활동의 중심이에요."],"title":"□□도 여행 신문 ⑤ □□시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#7','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C8',1,'ox','auto','신문 ⑥에서 □□시의 공항은 교통과 관련 있는 곳이에요.',ARRAY['SO4-2-u3-X23']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C8","difficulty":1,"kind":"ox","stem":"신문 ⑥에서 □□시의 공항은 교통과 관련 있는 곳이에요.","answer":"O","reason_options":[{"t":"사람과 물건이 비행기로 오가는 곳이기 때문에","correct":true},{"t":"공항은 물건을 만드는 곳이기 때문에","mis":"SO4-2-u3-X23"}],"mis":"SO4-2-u3-X23","explanation":["둘째 줄을 읽어요.","교통 시설이에요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑥ □□시의 산업 — 자동차 공장, 전통 시장, 은행, 불꽃 축제가 유명해요.","□□시의 교통 — 지하철역과 기차역, 버스 터미널, 공항이 있어요.","길과 탈것이 이어져 사람과 물건이 빠르게 오가요."],"title":"□□도 여행 신문 ⑥ □□시의 산업과 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#8','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C9',1,'ox','auto','신문 ⑦에서 우체국에서 일하는 것은 서비스를 제공하는 일이에요.',ARRAY['SO4-2-u3-X24']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C9","difficulty":1,"kind":"ox","stem":"신문 ⑦에서 우체국에서 일하는 것은 서비스를 제공하는 일이에요.","answer":"O","reason_options":[{"t":"편지나 물건을 보내 주며 사람들을 돕기 때문에","correct":true},{"t":"우체국은 물건을 만드는 곳이기 때문에","mis":"SO4-2-u3-X24"}],"mis":"SO4-2-u3-X24","explanation":["둘째 줄을 읽어요.","사람을 도와요.","그래서 O예요."],"asset":{"type":"passage","lines":["⑦ □□시 사람의 하루 — 아침에 아파트에서 나와 지하철을 타요.","낮에는 회사 사무실, 자동차 공장, 우체국에서 일해요.","저녁에는 공원에서 달리기를 하거나 미술관에 가요."],"title":"□□도 여행 신문 ⑦ □□시 사람의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#9','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C2',2,'match','auto','신문 ①의 모습과 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":9,"concept":"SO4-2-u3-C2","difficulty":2,"kind":"match","stem":"신문 ①의 모습과 하는 일을 알맞게 이으세요.","pairs":[{"l":"목장","r":"양을 길러요"},{"l":"풍력 발전기","r":"바람으로 전기를 만들어요"},{"l":"숙박 시설","r":"관광객에게 숙소를 빌려줘요"}],"mis":"SO4-2-u3-X04","explanation":["목장은 가축이에요.","발전기는 전기예요.","숙박 시설은 숙소예요."],"asset":{"type":"passage","lines":["① 산골 ○○군 — 울창한 숲과 맑은 계곡이 있어요.","언덕 목장에서 양을 기르고, 산꼭대기에는 풍력 발전기가 돌아요.","옛날에는 산비탈 밭에서 감자를 길렀어요.","스키장이 생긴 뒤로 관광객이 늘어 식당과 숙박 시설이 많아졌어요."],"title":"□□도 여행 신문 ① 산골 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#10','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C3',2,'match','auto','신문 ②의 장소와 생활 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":10,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"match","stem":"신문 ②의 장소와 생활 모습을 알맞게 이으세요.","pairs":[{"l":"논","r":"벼농사를 지어요"},{"l":"비닐하우스","r":"딸기를 길러요"},{"l":"기차역","r":"기차를 타고 다른 지역에 가요"}],"mis":"SO4-2-u3-X07","explanation":["논은 벼예요.","비닐하우스는 딸기예요.","기차역은 기차예요."],"asset":{"type":"passage","lines":["② 들판 △△군 — 저수지 가까이에 논이 넓게 펼쳐져 있어요.","비닐하우스에서는 딸기를 기르고, 축사에서는 소를 키워요.","옛 지도에는 논과 밭뿐이었는데, 요즘 지도에는 아파트가 많아요.","요즘에는 대형 할인점과 기차역, 박물관도 생겼어요."],"title":"□□도 여행 신문 ② 들판 △△군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#11','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C4',2,'match','auto','신문 ③의 장소와 하는 일을 알맞게 이으세요.','{}'::text[],false,'{"seq":11,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"match","stem":"신문 ③의 장소와 하는 일을 알맞게 이으세요.","pairs":[{"l":"양식장","r":"김을 길러요"},{"l":"수산물 직판장","r":"생선을 팔아요"},{"l":"바닷가 공장","r":"원료로 제품을 만들어요"}],"mis":"SO4-2-u3-X09","explanation":["양식장은 기르기예요.","직판장은 팔기예요.","공장은 만들기예요."],"asset":{"type":"passage","lines":["③ 바닷가 ◇◇군 — 넓은 갯벌과 하얀 모래사장이 있어요.","앞바다 양식장에서는 김을 기르고, 수산물 직판장에서는 생선을 팔아요.","큰 항구에 배가 원료를 싣고 들어오면 바닷가 공장이 제품을 만들어요.","공장이 생긴 뒤로 일하러 오는 사람이 늘었어요."],"title":"□□도 여행 신문 ③ 바닷가 ◇◇군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#12','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C5',2,'match','auto','신문 ④의 지역과 개발 모습을 알맞게 이으세요.','{}'::text[],false,'{"seq":12,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"match","stem":"신문 ④의 지역과 개발 모습을 알맞게 이으세요.","pairs":[{"l":"산골 ○○군","r":"케이블카"},{"l":"바닷가 ◇◇군","r":"간척으로 만든 공업 단지"},{"l":"들판 △△군","r":"고속도로"}],"mis":"SO4-2-u3-X12","explanation":["산은 케이블카예요.","바다는 간척이에요.","들은 고속도로예요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#13','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C6',2,'match','auto','낱말과 뜻을 알맞게 이으세요. (단원 정리)','{}'::text[],false,'{"seq":13,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"match","stem":"낱말과 뜻을 알맞게 이으세요. (단원 정리)","pairs":[{"l":"간척","r":"갯벌이나 바다를 새 땅으로 만들어요"},{"l":"산사태","r":"산의 흙이나 바위가 무너져 내려요"},{"l":"자연 휴식년제","r":"일정 기간 사람의 출입을 막아요"}],"mis":"SO4-2-u3-X17","explanation":["간척은 땅 만들기예요.","산사태는 무너짐이에요.","휴식년제는 쉬기예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#14','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C8',2,'match','auto','신문 ⑥의 □□시 산업과 이름을 알맞게 이으세요.','{}'::text[],false,'{"seq":14,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"match","stem":"신문 ⑥의 □□시 산업과 이름을 알맞게 이으세요.","pairs":[{"l":"자동차 공장","r":"제조업"},{"l":"전통 시장","r":"상업"},{"l":"은행","r":"금융업"},{"l":"불꽃 축제","r":"관광 산업"}],"mis":"SO4-2-u3-X22","explanation":["공장은 만들어요.","시장은 팔아요.","은행과 축제도 이어요."],"asset":{"type":"passage","lines":["⑥ □□시의 산업 — 자동차 공장, 전통 시장, 은행, 불꽃 축제가 유명해요.","□□시의 교통 — 지하철역과 기차역, 버스 터미널, 공항이 있어요.","길과 탈것이 이어져 사람과 물건이 빠르게 오가요."],"title":"□□도 여행 신문 ⑥ □□시의 산업과 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#15','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C10',2,'match','auto','신문 ⑧의 도시 문제와 노력을 알맞게 이으세요.','{}'::text[],false,'{"seq":15,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"match","stem":"신문 ⑧의 도시 문제와 노력을 알맞게 이으세요.","pairs":[{"l":"미세 먼지","r":"바람길 숲"},{"l":"늘어나는 쓰레기","r":"장바구니 쓰기 캠페인"}],"mis":"SO4-2-u3-X29","explanation":["먼지는 공기예요.","바람길 숲이에요.","쓰레기는 캠페인이에요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#16','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C11',2,'match','auto','정리 방법과 하는 일을 알맞게 이으세요. (단원 정리)','{}'::text[],false,'{"seq":16,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"match","stem":"정리 방법과 하는 일을 알맞게 이으세요. (단원 정리)","pairs":[{"l":"도시 그리기","r":"살고 싶은 도시와 시설을 그려요"},{"l":"이야기책 만들기","r":"책 모양을 만들고 글과 그림을 넣어요"},{"l":"묶어 보기","r":"가운데 단원 이름을 놓고 갈래마다 이어 붙여요"}],"mis":"SO4-2-u3-X30","explanation":["그리기는 그림이에요.","이야기책은 책이에요.","묶기는 갈래예요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#17','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C5',3,'error','auto','신문 ④를 보며 친구들이 의견을 말했어요. 의견을 잘못 낸 친구는 누구인가요?',ARRAY['SO4-2-u3-X15']::text[],false,'{"seq":17,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"error","stem":"신문 ④를 보며 친구들이 의견을 말했어요. 의견을 잘못 낸 친구는 누구인가요?","options":[{"t":"친구 나 — 「그냥 찬성이야. 까닭은 없어.」","correct":true,"mis_target":"SO4-2-u3-X15"},{"t":"친구 가 — 「일자리가 늘어 찬성하지만 폐수를 줄여야 해.」","mis":"SO4-2-u3-X15"},{"t":"친구 다 — 「숲이 훼손돼서 케이블카는 반대야.」","mis":"SO4-2-u3-X15"}],"explanation":["의견에 무엇이 필요할까요?","까닭이에요.","친구 나가 잘못 냈어요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#18','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C2',3,'error','auto','세 지역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X04','SO4-2-u3-X06','SO4-2-u3-X10']::text[],false,'{"seq":18,"concept":"SO4-2-u3-C2","difficulty":3,"kind":"error","stem":"세 지역을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「○○군은 넓은 논에서 벼농사를 주로 지어.」","correct":true,"mis_target":"SO4-2-u3-X04"},{"t":"친구 가 — 「△△군은 저수지 가까이 논이 있어.」","mis":"SO4-2-u3-X06"},{"t":"친구 나 — 「◇◇군은 항구로 원료가 들어와.」","mis":"SO4-2-u3-X10"}],"explanation":["○○군은 산골이에요.","산비탈 밭이에요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["① 산골 ○○군 — 울창한 숲과 맑은 계곡이 있어요.","언덕 목장에서 양을 기르고, 산꼭대기에는 풍력 발전기가 돌아요.","옛날에는 산비탈 밭에서 감자를 길렀어요.","스키장이 생긴 뒤로 관광객이 늘어 식당과 숙박 시설이 많아졌어요."],"title":"□□도 여행 신문 ① 산골 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#19','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C7',3,'error','auto','도시를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)',ARRAY['SO4-2-u3-X20','SO4-2-u3-X18','SO4-2-u3-X19']::text[],false,'{"seq":19,"concept":"SO4-2-u3-C7","difficulty":3,"kind":"error","stem":"도시를 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)","options":[{"t":"친구 가 — 「「도시」 하면 「조용하다」가 떠올라. 사람이 많아서야.」","correct":true,"mis_target":"SO4-2-u3-X20"},{"t":"친구 나 — 「도시는 활동의 중심이야.」","mis":"SO4-2-u3-X18"},{"t":"친구 다 — 「도시에는 편의 시설이 많아.」","mis":"SO4-2-u3-X19"}],"explanation":["낱말과 까닭이 맞나요?","많은데 조용할까요?","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#20','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C9',3,'error','auto','신문 ⑦을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X24','SO4-2-u3-X25']::text[],false,'{"seq":20,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"error","stem":"신문 ⑦을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「□□시 사람들은 대부분 목장에서 일해.」","correct":true,"mis_target":"SO4-2-u3-X24"},{"t":"친구 가 — 「우체국은 서비스를 제공해.」","mis":"SO4-2-u3-X24"},{"t":"친구 다 — 「미술관에 가는 것도 여가 생활이야.」","mis":"SO4-2-u3-X25"}],"explanation":["둘째 줄을 읽어요.","목장은 없어요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["⑦ □□시 사람의 하루 — 아침에 아파트에서 나와 지하철을 타요.","낮에는 회사 사무실, 자동차 공장, 우체국에서 일해요.","저녁에는 공원에서 달리기를 하거나 미술관에 가요."],"title":"□□도 여행 신문 ⑦ □□시 사람의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#21','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C10',3,'error','auto','신문 ⑧의 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X29','SO4-2-u3-X27']::text[],false,'{"seq":21,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"error","stem":"신문 ⑧의 노력을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「장바구니 캠페인은 미세 먼지를 줄이려는 노력이야.」","correct":true,"mis_target":"SO4-2-u3-X29"},{"t":"친구 가 — 「바람길 숲은 공기를 맑게 해.」","mis":"SO4-2-u3-X29"},{"t":"친구 나 — 「도로가 막히는 건 문제점이야.」","mis":"SO4-2-u3-X27"}],"explanation":["장바구니는 무엇을 줄이나요?","쓰레기예요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#22','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C11',3,'error','auto','단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X32']::text[],false,'{"seq":22,"concept":"SO4-2-u3-C11","difficulty":3,"kind":"error","stem":"단원을 정리하며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「바람길 숲은 「지역의 환경과 변화」 갈래에 붙여.」","correct":true,"mis_target":"SO4-2-u3-X32"},{"t":"친구 가 — 「세 지역의 특징은 「지역의 환경과 변화」에 붙여.」","mis":"SO4-2-u3-X32"},{"t":"친구 다 — 「도시 생활의 문제점은 「도시의 특징과 생활 모습」에 붙여.」","mis":"SO4-2-u3-X32"}],"explanation":["바람길 숲은 무엇이었나요?","도시 문제 해결 노력이에요.","친구 나가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#23','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C5',4,'mc','auto','신문 ④와 ⑧을 함께 볼 때 같은 점으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X11','SO4-2-u3-X13','SO4-2-u3-X29']::text[],false,'{"seq":23,"concept":"SO4-2-u3-C5","difficulty":4,"kind":"mc","stem":"신문 ④와 ⑧을 함께 볼 때 같은 점으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"편리함과 함께 생긴 문제를 생태 통로나 바람길 숲 같은 노력으로 줄여요","correct":true},{"t":"두 신문 모두 문제점이 없어요","mis":"SO4-2-u3-X11"},{"t":"두 신문 모두 개발을 되돌렸어요","mis":"SO4-2-u3-X13"},{"t":"두 신문 모두 쓰레기만 다뤄요","mis":"SO4-2-u3-X29"}],"explanation":["④는 개발 소식이에요.","⑧은 도시 생활이에요.","둘 다 노력이 있어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#24','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C8',4,'essay','teacher','신문 ⑤와 ⑥을 보고 □□시가 도시인 까닭을 인구·산업·교통 가운데 두 가지를 들어 쓰세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u3-C8","difficulty":4,"kind":"essay","stem":"신문 ⑤와 ⑥을 보고 □□시가 도시인 까닭을 인구·산업·교통 가운데 두 가지를 들어 쓰세요.","answer_guide":{"answer":"예: □□시에는 □□도 사람 대부분이 모여 살아 인구가 많아요. 또 자동차 공장, 전통 시장, 은행처럼 여러 산업이 발달하고 지하철역과 공항이 있어 교통도 발달했어요. 그래서 □□시는 도시예요.","scoring_points":["두 가지를 골랐는가","신문의 사실로 썼는가","도시인 까닭과 이었는가"]},"explanation":["둘을 골라요.","사실로 써요.","까닭과 이어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_c#25','soc',4,2,'u3','','g4_2_soc_u3_review_c','unit_review','SO4-2-u3-C11',4,'essay','teacher','자연과 조화를 이룬 □□시를 상상해, 신문 ⑧의 문제 하나가 해결된 모습과 그 도시에서 사는 나의 하루를 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u3-C11","difficulty":4,"kind":"essay","stem":"자연과 조화를 이룬 □□시를 상상해, 신문 ⑧의 문제 하나가 해결된 모습과 그 도시에서 사는 나의 하루를 쓰세요.","answer_guide":{"answer":"예: 바람길 숲이 도시 곳곳에 생겨 미세 먼지 없는 맑은 날이 많아졌어요. 나는 아침에 숲길을 따라 자전거를 타고 학교에 가고, 저녁에는 물이 흐르는 공원에서 가족과 산책해요.","scoring_points":["문제가 해결된 모습을 썼는가","나의 하루를 썼는가","자연과 조화를 이룬 모습인가"]},"explanation":["문제를 골라요.","해결된 모습을 써요.","나의 하루를 써요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#1','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C1',1,'mc','auto','신문 ③의 ◇◇군에서 볼 수 있는 것 가운데 인문환경은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":1,"concept":"SO4-2-u3-C1","difficulty":1,"kind":"mc","stem":"신문 ③의 ◇◇군에서 볼 수 있는 것 가운데 인문환경은 무엇인가요?","options":[{"t":"항구","correct":true},{"t":"갯벌","mis":"SO4-2-u3-X01"},{"t":"모래사장","mis":"SO4-2-u3-X01"},{"t":"앞바다","mis":"SO4-2-u3-X01"}],"explanation":["사람이 만든 것이에요.","배가 드나들어요.","항구예요."],"asset":{"type":"passage","lines":["③ 바닷가 ◇◇군 — 넓은 갯벌과 하얀 모래사장이 있어요.","앞바다 양식장에서는 김을 기르고, 수산물 직판장에서는 생선을 팔아요.","큰 항구에 배가 원료를 싣고 들어오면 바닷가 공장이 제품을 만들어요.","공장이 생긴 뒤로 일하러 오는 사람이 늘었어요."],"title":"□□도 여행 신문 ③ 바닷가 ◇◇군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#2','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C2',1,'mc','auto','신문 ①의 ○○군 목장에서 기르는 동물은 무엇인가요?',ARRAY['SO4-2-u3-X04','SO4-2-u3-X06','SO4-2-u3-X09']::text[],false,'{"seq":2,"concept":"SO4-2-u3-C2","difficulty":1,"kind":"mc","stem":"신문 ①의 ○○군 목장에서 기르는 동물은 무엇인가요?","options":[{"t":"양","correct":true},{"t":"소","mis":"SO4-2-u3-X04"},{"t":"돼지","mis":"SO4-2-u3-X06"},{"t":"김","mis":"SO4-2-u3-X09"}],"explanation":["둘째 줄을 읽어요.","언덕 목장이에요.","양이에요."],"asset":{"type":"passage","lines":["① 산골 ○○군 — 울창한 숲과 맑은 계곡이 있어요.","언덕 목장에서 양을 기르고, 산꼭대기에는 풍력 발전기가 돌아요.","옛날에는 산비탈 밭에서 감자를 길렀어요.","스키장이 생긴 뒤로 관광객이 늘어 식당과 숙박 시설이 많아졌어요."],"title":"□□도 여행 신문 ① 산골 ○○군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#3','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C3',1,'mc','auto','신문 ②에서 △△군 비닐하우스에서 기르는 것은 무엇인가요?',ARRAY['SO4-2-u3-X06']::text[],false,'{"seq":3,"concept":"SO4-2-u3-C3","difficulty":1,"kind":"mc","stem":"신문 ②에서 △△군 비닐하우스에서 기르는 것은 무엇인가요?","options":[{"t":"딸기","correct":true},{"t":"감자","mis":"SO4-2-u3-X06"},{"t":"김","mis":"SO4-2-u3-X06"},{"t":"양","mis":"SO4-2-u3-X06"}],"explanation":["둘째 줄을 읽어요.","비닐하우스예요.","딸기예요."],"asset":{"type":"passage","lines":["② 들판 △△군 — 저수지 가까이에 논이 넓게 펼쳐져 있어요.","비닐하우스에서는 딸기를 기르고, 축사에서는 소를 키워요.","옛 지도에는 논과 밭뿐이었는데, 요즘 지도에는 아파트가 많아요.","요즘에는 대형 할인점과 기차역, 박물관도 생겼어요."],"title":"□□도 여행 신문 ② 들판 △△군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#4','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C4',1,'mc','auto','신문 ③에서 ◇◇군 바닷가에 있는 자연환경은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":4,"concept":"SO4-2-u3-C4","difficulty":1,"kind":"mc","stem":"신문 ③에서 ◇◇군 바닷가에 있는 자연환경은 무엇인가요?","options":[{"t":"넓은 갯벌","correct":true},{"t":"큰 항구","mis":"SO4-2-u3-X01"},{"t":"양식장","mis":"SO4-2-u3-X01"},{"t":"바닷가 공장","mis":"SO4-2-u3-X01"}],"explanation":["첫째 줄을 읽어요.","자연 그대로예요.","갯벌이에요."],"asset":{"type":"passage","lines":["③ 바닷가 ◇◇군 — 넓은 갯벌과 하얀 모래사장이 있어요.","앞바다 양식장에서는 김을 기르고, 수산물 직판장에서는 생선을 팔아요.","큰 항구에 배가 원료를 싣고 들어오면 바닷가 공장이 제품을 만들어요.","공장이 생긴 뒤로 일하러 오는 사람이 늘었어요."],"title":"□□도 여행 신문 ③ 바닷가 ◇◇군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#5','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C5',1,'mc','auto','신문 ④에서 ○○군 산 한쪽 길을 몇 해 동안 쉬게 하는 제도는 무엇인가요?',ARRAY['SO4-2-u3-X14','SO4-2-u3-X12']::text[],false,'{"seq":5,"concept":"SO4-2-u3-C5","difficulty":1,"kind":"mc","stem":"신문 ④에서 ○○군 산 한쪽 길을 몇 해 동안 쉬게 하는 제도는 무엇인가요?","options":[{"t":"자연 휴식년제","correct":true},{"t":"간척","mis":"SO4-2-u3-X14"},{"t":"생태 하천","mis":"SO4-2-u3-X14"},{"t":"공업 단지","mis":"SO4-2-u3-X12"}],"explanation":["넷째 줄을 읽어요.","쉬는 기간이에요.","자연 휴식년제예요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#6','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C7',1,'mc','auto','신문 ⑤에서 □□시에 많은 것은 무엇인가요?',ARRAY['SO4-2-u3-X19','SO4-2-u3-X18']::text[],false,'{"seq":6,"concept":"SO4-2-u3-C7","difficulty":1,"kind":"mc","stem":"신문 ⑤에서 □□시에 많은 것은 무엇인가요?","options":[{"t":"큰 병원과 상점","correct":true},{"t":"넓은 갯벌","mis":"SO4-2-u3-X19"},{"t":"산비탈 밭","mis":"SO4-2-u3-X18"},{"t":"김 양식장","mis":"SO4-2-u3-X18"}],"explanation":["둘째 줄을 읽어요.","편의 시설이에요.","병원과 상점이에요."],"asset":{"type":"passage","lines":["⑤ □□시 — 밤에도 거리와 건물에 불이 환하게 켜져 있어요.","시청과 법원 같은 공공 기관, 큰 병원과 상점이 많아요.","□□도에 사는 사람 대부분이 □□시에 모여 살아요.","□□도의 정치, 경제, 사회 활동의 중심이에요."],"title":"□□도 여행 신문 ⑤ □□시"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#7','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C8',1,'mc','auto','신문 ⑥에서 □□시의 불꽃 축제는 어떤 산업과 관련 있나요?',ARRAY['SO4-2-u3-X22']::text[],false,'{"seq":7,"concept":"SO4-2-u3-C8","difficulty":1,"kind":"mc","stem":"신문 ⑥에서 □□시의 불꽃 축제는 어떤 산업과 관련 있나요?","options":[{"t":"관광 산업","correct":true},{"t":"금융업","mis":"SO4-2-u3-X22"},{"t":"제조업","mis":"SO4-2-u3-X22"},{"t":"상업","mis":"SO4-2-u3-X22"}],"explanation":["관광객이 찾아와요.","행사예요.","관광 산업이에요."],"asset":{"type":"passage","lines":["⑥ □□시의 산업 — 자동차 공장, 전통 시장, 은행, 불꽃 축제가 유명해요.","□□시의 교통 — 지하철역과 기차역, 버스 터미널, 공항이 있어요.","길과 탈것이 이어져 사람과 물건이 빠르게 오가요."],"title":"□□도 여행 신문 ⑥ □□시의 산업과 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#8','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C9',1,'mc','auto','신문 ⑦에서 □□시 사람들의 여가 생활은 무엇인가요?',ARRAY['SO4-2-u3-X25','SO4-2-u3-X24']::text[],false,'{"seq":8,"concept":"SO4-2-u3-C9","difficulty":1,"kind":"mc","stem":"신문 ⑦에서 □□시 사람들의 여가 생활은 무엇인가요?","options":[{"t":"공원에서 달리기","correct":true},{"t":"사무실에서 회의","mis":"SO4-2-u3-X25"},{"t":"공장에서 조립","mis":"SO4-2-u3-X25"},{"t":"양식장에서 김 기르기","mis":"SO4-2-u3-X24"}],"explanation":["셋째 줄을 읽어요.","저녁의 일이에요.","달리기예요."],"asset":{"type":"passage","lines":["⑦ □□시 사람의 하루 — 아침에 아파트에서 나와 지하철을 타요.","낮에는 회사 사무실, 자동차 공장, 우체국에서 일해요.","저녁에는 공원에서 달리기를 하거나 미술관에 가요."],"title":"□□도 여행 신문 ⑦ □□시 사람의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#9','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C1',2,'error','auto','환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)',ARRAY['SO4-2-u3-X02','SO4-2-u3-X01','SO4-2-u3-X03']::text[],false,'{"seq":9,"concept":"SO4-2-u3-C1","difficulty":2,"kind":"error","stem":"환경을 두고 친구들이 말했어요. 잘못 말한 친구는 누구인가요? (단원 정리)","options":[{"t":"친구 가 — 「기온은 사람이 만든 인문환경이야.」","correct":true,"mis_target":"SO4-2-u3-X02"},{"t":"친구 나 — 「다리는 인문환경이야.」","mis":"SO4-2-u3-X01"},{"t":"친구 다 — 「섬은 자연환경이야.」","mis":"SO4-2-u3-X03"}],"explanation":["기온은 날씨예요.","자연환경이에요.","친구 가가 잘못 말했어요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#10','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C3',2,'blank','auto','들이 펼쳐진 지역은 땅이 넓고 (    )해 논과 밭, 도로를 만들기 좋아요. 빈칸에 알맞은 말은 무엇인가요? (단원 정리)',ARRAY['SO4-2-u3-X06']::text[],false,'{"seq":10,"concept":"SO4-2-u3-C3","difficulty":2,"kind":"blank","stem":"들이 펼쳐진 지역은 땅이 넓고 (    )해 논과 밭, 도로를 만들기 좋아요. 빈칸에 알맞은 말은 무엇인가요? (단원 정리)","options":[{"t":"평평","correct":true},{"t":"가파르","mis":"SO4-2-u3-X06"},{"t":"울퉁불퉁","mis":"SO4-2-u3-X06"},{"t":"비스듬","mis":"SO4-2-u3-X06"}],"explanation":["들판을 떠올려요.","높낮이가 없어요.","평평해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#11','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C4',2,'error','auto','신문 ③을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X10','SO4-2-u3-X01']::text[],false,'{"seq":11,"concept":"SO4-2-u3-C4","difficulty":2,"kind":"error","stem":"신문 ③을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 다 — 「공장이 생긴 뒤로 ◇◇군에 사는 사람이 줄었어.」","correct":true,"mis_target":"SO4-2-u3-X10"},{"t":"친구 가 — 「배가 원료를 싣고 들어와.」","mis":"SO4-2-u3-X10"},{"t":"친구 나 — 「갯벌은 자연환경이야.」","mis":"SO4-2-u3-X01"}],"explanation":["넷째 줄을 읽어요.","사람이 늘었어요.","친구 다가 잘못 말했어요."],"asset":{"type":"passage","lines":["③ 바닷가 ◇◇군 — 넓은 갯벌과 하얀 모래사장이 있어요.","앞바다 양식장에서는 김을 기르고, 수산물 직판장에서는 생선을 팔아요.","큰 항구에 배가 원료를 싣고 들어오면 바닷가 공장이 제품을 만들어요.","공장이 생긴 뒤로 일하러 오는 사람이 늘었어요."],"title":"□□도 여행 신문 ③ 바닷가 ◇◇군"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#12','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C5',2,'blank','auto','개발로 생기는 좋은 점과 문제점은 같은 개발에서 (    ) 생겨요. 빈칸에 알맞은 말은 무엇인가요? (단원 정리)',ARRAY['SO4-2-u3-X13','SO4-2-u3-X11']::text[],false,'{"seq":12,"concept":"SO4-2-u3-C5","difficulty":2,"kind":"blank","stem":"개발로 생기는 좋은 점과 문제점은 같은 개발에서 (    ) 생겨요. 빈칸에 알맞은 말은 무엇인가요? (단원 정리)","options":[{"t":"함께","correct":true},{"t":"따로따로","mis":"SO4-2-u3-X13"},{"t":"번갈아 한 번씩","mis":"SO4-2-u3-X13"},{"t":"절대로 안","mis":"SO4-2-u3-X11"}],"explanation":["케이블카를 떠올려요.","늘고 훼손됐어요.","함께 생겨요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#13','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C6',2,'sa','auto','신문 ④에서 케이블카를 놓아 숲이 훼손되면 위험이 커지는 일로, 산의 흙이 무너져 내리는 일은 무엇인가요? 세 글자로 쓰세요.','{}'::text[],false,'{"seq":13,"concept":"SO4-2-u3-C6","difficulty":2,"kind":"sa","stem":"신문 ④에서 케이블카를 놓아 숲이 훼손되면 위험이 커지는 일로, 산의 흙이 무너져 내리는 일은 무엇인가요? 세 글자로 쓰세요.","answer":["산사태"],"explanation":["숲이 훼손됐어요.","흙이 무너져요.","산사태예요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"},"mis":"SO4-2-u3-X17"}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#14','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C8',2,'error','auto','신문 ⑥을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X23','SO4-2-u3-X22']::text[],false,'{"seq":14,"concept":"SO4-2-u3-C8","difficulty":2,"kind":"error","stem":"신문 ⑥을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 나 — 「길이 이어질수록 곳과 곳 사이가 멀어져.」","correct":true,"mis_target":"SO4-2-u3-X23"},{"t":"친구 가 — 「지하철역과 기차역은 교통 시설이야.」","mis":"SO4-2-u3-X23"},{"t":"친구 다 — 「전통 시장은 상업이야.」","mis":"SO4-2-u3-X22"}],"explanation":["셋째 줄을 읽어요.","빠르게 오가요.","친구 나가 잘못 말했어요."],"asset":{"type":"passage","lines":["⑥ □□시의 산업 — 자동차 공장, 전통 시장, 은행, 불꽃 축제가 유명해요.","□□시의 교통 — 지하철역과 기차역, 버스 터미널, 공항이 있어요.","길과 탈것이 이어져 사람과 물건이 빠르게 오가요."],"title":"□□도 여행 신문 ⑥ □□시의 산업과 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#15','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C10',2,'error','auto','신문 ⑧을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?',ARRAY['SO4-2-u3-X27','SO4-2-u3-X29']::text[],false,'{"seq":15,"concept":"SO4-2-u3-C10","difficulty":2,"kind":"error","stem":"신문 ⑧을 보며 친구들이 말했어요. 잘못 말한 친구는 누구인가요?","options":[{"t":"친구 가 — 「□□시 생활에는 좋은 점만 있어.」","correct":true,"mis_target":"SO4-2-u3-X27"},{"t":"친구 나 — 「출퇴근 시간에 도로가 막혀.」","mis":"SO4-2-u3-X27"},{"t":"친구 다 — 「장바구니로 쓰레기를 줄여.」","mis":"SO4-2-u3-X29"}],"explanation":["둘째·셋째 줄을 읽어요.","문제점도 있어요.","친구 가가 잘못 말했어요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#16','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C11',2,'blank','auto','단원 내용을 묶을 때는 가운데에 (    )을 놓고 두 갈래로 이어 붙여요. 빈칸에 알맞은 말은 무엇인가요? (단원 정리)',ARRAY['SO4-2-u3-X32']::text[],false,'{"seq":16,"concept":"SO4-2-u3-C11","difficulty":2,"kind":"blank","stem":"단원 내용을 묶을 때는 가운데에 (    )을 놓고 두 갈래로 이어 붙여요. 빈칸에 알맞은 말은 무엇인가요? (단원 정리)","options":[{"t":"단원 이름","correct":true},{"t":"내 이름","mis":"SO4-2-u3-X32"},{"t":"그림 한 장","mis":"SO4-2-u3-X32"},{"t":"빈 종이","mis":"SO4-2-u3-X32"}],"explanation":["가운데가 중심이에요.","무엇을 공부했나요?","단원 이름이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#17','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C5',3,'mc','auto','신문 ④의 ◇◇군 공업 단지에서 생긴 폐수 문제를 줄이는 노력으로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X14','SO4-2-u3-X11','SO4-2-u3-X12']::text[],false,'{"seq":17,"concept":"SO4-2-u3-C5","difficulty":3,"kind":"mc","stem":"신문 ④의 ◇◇군 공업 단지에서 생긴 폐수 문제를 줄이는 노력으로 가장 알맞은 것은 무엇인가요?","options":[{"t":"폐수를 깨끗하게 거른 뒤 흘려보내고 오염된 물길을 생태 하천으로 되살려요","correct":true},{"t":"공장을 더 많이 지어요","mis":"SO4-2-u3-X14"},{"t":"폐수를 갯벌에 그대로 흘려보내요","mis":"SO4-2-u3-X11"},{"t":"고라니 길을 하나 더 만들어요","mis":"SO4-2-u3-X12"}],"explanation":["폐수가 문제예요.","물을 깨끗하게 해요.","그것을 골라요."],"asset":{"type":"passage","lines":["④ 개발 소식 — ○○군 산에 케이블카를 놓자 관광객이 늘었지만 숲이 훼손됐어요.","◇◇군은 갯벌을 간척해 공업 단지를 만들었어요. 일자리는 늘고 폐수가 생겼어요.","△△군 고속도로에는 고라니가 건너는 생태 통로를 만들었어요.","○○군 산 한쪽 길은 몇 해 동안 사람이 들어가지 못하게 쉬게 해요."],"title":"□□도 여행 신문 ④ 개발 소식"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#18','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C1',3,'mc','auto','신문 ①~③에 나온 것 가운데 자연환경만 모은 것은 무엇인가요?',ARRAY['SO4-2-u3-X01']::text[],false,'{"seq":18,"concept":"SO4-2-u3-C1","difficulty":3,"kind":"mc","stem":"신문 ①~③에 나온 것 가운데 자연환경만 모은 것은 무엇인가요?","options":[{"t":"계곡 · 저수지 둘레의 들판 · 갯벌","correct":true},{"t":"목장 · 논 · 항구","mis":"SO4-2-u3-X01"},{"t":"스키장 · 비닐하우스 · 양식장","mis":"SO4-2-u3-X01"},{"t":"계곡 · 기차역 · 갯벌","mis":"SO4-2-u3-X01"}],"explanation":["사람이 만든 것을 빼요.","계곡과 갯벌이에요.","들판도 자연이에요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#19','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C8',3,'mc','auto','□□시처럼 사람이 도시로 많이 모이는 까닭을 신문 ⑥과 이어 가장 잘 말한 것은 무엇인가요?',ARRAY['SO4-2-u3-X22','SO4-2-u3-X23','SO4-2-u3-X21']::text[],false,'{"seq":19,"concept":"SO4-2-u3-C8","difficulty":3,"kind":"mc","stem":"□□시처럼 사람이 도시로 많이 모이는 까닭을 신문 ⑥과 이어 가장 잘 말한 것은 무엇인가요?","options":[{"t":"여러 산업이 발달해 일자리가 많고 교통이 편리하기 때문이에요","correct":true},{"t":"공장과 시장이 하나도 없기 때문이에요","mis":"SO4-2-u3-X22"},{"t":"교통이 불편하기 때문이에요","mis":"SO4-2-u3-X23"},{"t":"사는 사람이 적어 조용하기 때문이에요","mis":"SO4-2-u3-X21"}],"explanation":["산업을 봐요.","교통을 봐요.","둘을 합쳐요."],"asset":{"type":"passage","lines":["⑥ □□시의 산업 — 자동차 공장, 전통 시장, 은행, 불꽃 축제가 유명해요.","□□시의 교통 — 지하철역과 기차역, 버스 터미널, 공항이 있어요.","길과 탈것이 이어져 사람과 물건이 빠르게 오가요."],"title":"□□도 여행 신문 ⑥ □□시의 산업과 교통"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#20','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C9',3,'mc','auto','무언극으로 신문 ⑦의 하루를 발표할 때 꼭 지킬 점은 무엇인가요?',ARRAY['SO4-2-u3-X26']::text[],false,'{"seq":20,"concept":"SO4-2-u3-C9","difficulty":3,"kind":"mc","stem":"무언극으로 신문 ⑦의 하루를 발표할 때 꼭 지킬 점은 무엇인가요?","options":[{"t":"대사 없이 몸짓과 표정만으로 나타내요","correct":true},{"t":"장면마다 이름을 크게 외쳐요","mis":"SO4-2-u3-X26"},{"t":"글자 판을 들고 보여 줘요","mis":"SO4-2-u3-X26"},{"t":"노래로 설명해요","mis":"SO4-2-u3-X26"}],"explanation":["무언극이에요.","말이 없어요.","몸짓과 표정이에요."],"asset":{"type":"passage","lines":["⑦ □□시 사람의 하루 — 아침에 아파트에서 나와 지하철을 타요.","낮에는 회사 사무실, 자동차 공장, 우체국에서 일해요.","저녁에는 공원에서 달리기를 하거나 미술관에 가요."],"title":"□□도 여행 신문 ⑦ □□시 사람의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#21','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C10',3,'mc','auto','신문 ⑧의 문제를 풀 캠페인 문구로 가장 알맞은 것은 무엇인가요?',ARRAY['SO4-2-u3-X29','SO4-2-u3-X27','SO4-2-u3-X28']::text[],false,'{"seq":21,"concept":"SO4-2-u3-C10","difficulty":3,"kind":"mc","stem":"신문 ⑧의 문제를 풀 캠페인 문구로 가장 알맞은 것은 무엇인가요?","options":[{"t":"「장바구니 하나로 □□시가 가벼워져요!」","correct":true},{"t":"「쓰레기는 많을수록 좋아요!」","mis":"SO4-2-u3-X29"},{"t":"「도시에는 문제가 없어요!」","mis":"SO4-2-u3-X27"},{"t":"「차를 더 많이 타요!」","mis":"SO4-2-u3-X28"}],"explanation":["쓰레기를 줄여요.","짧고 기억에 남아요.","그것을 골라요."],"asset":{"type":"passage","lines":["⑧ □□시 생활 — 일자리가 많고 병원과 영화관이 가까워 편리해요.","그런데 출퇴근 시간에는 도로가 꽉 막히고 주차할 곳이 모자라요.","버려지는 쓰레기가 늘고, 미세 먼지가 많은 날도 있어요.","시는 바람길 숲을 만들고, 주민들은 장바구니 쓰기 캠페인을 열었어요."],"title":"□□도 여행 신문 ⑧ □□시 생활"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#22','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C6',3,'mc','auto','놀이로 단원을 정리할 때 문제를 맞히지 못해 이전 칸으로 물러나면 어떻게 되나요? (단원 정리)',ARRAY['SO4-2-u3-X16']::text[],false,'{"seq":22,"concept":"SO4-2-u3-C6","difficulty":3,"kind":"mc","stem":"놀이로 단원을 정리할 때 문제를 맞히지 못해 이전 칸으로 물러나면 어떻게 되나요? (단원 정리)","options":[{"t":"지나온 칸은 지워지지 않고 다시 풀며 도착할 수 있어요","correct":true},{"t":"처음부터 모든 칸을 다시 지워요","mis":"SO4-2-u3-X16"},{"t":"놀이가 바로 끝나요","mis":"SO4-2-u3-X16"},{"t":"물러난 사람은 정리를 할 수 없어요","mis":"SO4-2-u3-X16"}],"explanation":["물러나도 괜찮아요.","지나온 칸은 남아요.","다시 도전해요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#23','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C11',4,'mc','auto','「다양한 환경과 삶의 모습」 단원을 가장 잘 정리한 것은 무엇인가요?',ARRAY['SO4-2-u3-X04','SO4-2-u3-X27','SO4-2-u3-X03']::text[],false,'{"seq":23,"concept":"SO4-2-u3-C11","difficulty":4,"kind":"mc","stem":"「다양한 환경과 삶의 모습」 단원을 가장 잘 정리한 것은 무엇인가요?","options":[{"t":"지역마다 다른 환경 속에서 사람들은 환경을 이용하며 살고, 도시처럼 사람이 모인 곳에도 좋은 점과 문제점이 있어 조화를 이루려 노력해요","correct":true},{"t":"모든 지역의 환경과 생활은 같아요","mis":"SO4-2-u3-X04"},{"t":"도시 생활에는 좋은 점만 있어요","mis":"SO4-2-u3-X27"},{"t":"환경은 사람의 생활과 관계없어요","mis":"SO4-2-u3-X03"}],"explanation":["주제①은 환경이에요.","주제②는 도시예요.","둘을 합쳐요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#24','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C9',4,'essay','teacher','신문 ⑦의 □□시 사람의 하루를 바탕으로 사는 곳·하는 일·여가 생활을 한 문장씩 써서 무언극 계획을 세우세요.','{}'::text[],false,'{"seq":24,"concept":"SO4-2-u3-C9","difficulty":4,"kind":"essay","stem":"신문 ⑦의 □□시 사람의 하루를 바탕으로 사는 곳·하는 일·여가 생활을 한 문장씩 써서 무언극 계획을 세우세요.","answer_guide":{"answer":"예: 사는 곳 — 아파트 현관문을 열고 나오는 몸짓을 해요. 하는 일 — 우체국에서 손님에게 상자를 받아 저울에 올리는 몸짓을 해요. 여가 생활 — 공원에서 팔을 흔들며 달리는 몸짓을 해요.","scoring_points":["세 갈래를 모두 썼는가","말이 아니라 몸짓으로 썼는가","신문 ⑦과 맞는가"]},"explanation":["셋을 골라요.","몸짓을 써요.","말은 빼요."],"asset":{"type":"passage","lines":["⑦ □□시 사람의 하루 — 아침에 아파트에서 나와 지하철을 타요.","낮에는 회사 사무실, 자동차 공장, 우체국에서 일해요.","저녁에는 공원에서 달리기를 하거나 미술관에 가요."],"title":"□□도 여행 신문 ⑦ □□시 사람의 하루"}}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
INSERT INTO question_bank (qcode,subject,grade,semester,unit_code,lesson_code,source_set,source_kind,concept_code,difficulty,qkind,grading,stem,misconception_codes,has_variant,payload) VALUES ('g4_2_soc_u3_review_d#25','soc',4,2,'u3','','g4_2_soc_u3_review_d','unit_review','SO4-2-u3-C6',4,'essay','teacher','이 단원의 두 주제 「지역의 환경과 변화」와 「도시의 특징과 생활 모습」이 어떻게 이어지는지, 사람과 환경의 조화와 이어 쓰세요.','{}'::text[],false,'{"seq":25,"concept":"SO4-2-u3-C6","difficulty":4,"kind":"essay","stem":"이 단원의 두 주제 「지역의 환경과 변화」와 「도시의 특징과 생활 모습」이 어떻게 이어지는지, 사람과 환경의 조화와 이어 쓰세요.","answer_guide":{"answer":"예: 주제①에서는 산·들·바다 지역 사람들이 환경을 이용하고 개발하며 생긴 좋은 점과 문제점을 배웠어요. 주제②에서는 사람이 많이 모인 도시에도 좋은 점과 문제점이 있음을 배웠어요. 두 주제 모두 사람들이 환경과 조화를 이루려고 노력한다는 점에서 이어져요.","scoring_points":["주제①을 썼는가","주제②를 썼는가","조화와 이어 두 주제를 묶었는가"]},"explanation":["주제①을 떠올려요.","주제②를 떠올려요.","이어 써요."]}'::jsonb) ON CONFLICT (qcode) DO UPDATE SET concept_code=EXCLUDED.concept_code, difficulty=EXCLUDED.difficulty, qkind=EXCLUDED.qkind, grading=EXCLUDED.grading, stem=EXCLUDED.stem, misconception_codes=EXCLUDED.misconception_codes, has_variant=EXCLUDED.has_variant, payload=EXCLUDED.payload, is_active=true;
